3. Create a `PokemonReport` class that generates the detailed report:

```java
public class PokemonReport {
    private final TypeChart typeChart;
    private final PokemonLibrary pokemonLibrary;
    private final Map<String, Double> weaknesses = new HashMap<>();
    private final Map<String, Double> resistances = new HashMap<>();

    public PokemonReport(TypeChart typeChart, PokemonLibrary pokemonLibrary) {
        this.typeChart = typeChart;
        this.pokemonLibrary = pokemonLibrary;
    }

    public void analyze(Pokemon pokemon) {
        for (String type : pokemon.getTypes()) {
            for (String otherType : typeChart.chart.keySet()) {
                double weaknessFactor = typeChart.getWeakness(otherType, type);
                if (weaknessFactor > 1) {
                    weaknesses.putIfAbsent(otherType, weaknessFactor);
                }
            }
        }

        for (String type : typeChart.chart.keySet()) {
            double resistanceFactor = typeChart.getResistance(type, pokemon.getType());
            if (resistanceFactor < 1) {
                resistances.putIfAbsent(type, resistanceFactor);
            }
        }
    }

    public String getReport() {
        StringBuilder report = new StringBuilder();
        report.append("Pokemon: ").append(pokemonLibrary.getPokemonByName(pokemon.getName()).getName()).append("\n");
        report.append("Weaknesses:\n");
        for (Map.Entry<String, Double> entry : weaknesses.entrySet()) {
            report.append(entry.getKey()).append(": ").append(entry.getValue()).append("\n");
        }
        report.append("Resistances:\n");
        for (Map.Entry<String, Double> entry : resistances.entrySet()) {
            report.append(entry.getKey()).append(": ").append(1 / entry.getValue()).append("\n");
        }
        return report.toString();
    }
}
```

