[' Creating a full implementation of such a complex system requires extensive code and goes beyond the scope of this platform. However, I can provide you with an outline and guidance on how to approach the task. You'll need to use C++11 or higher for threading support and other modern features.

1. Use a `std::map` to store semaphores indexed by their unique identifiers. Each semaphore can be represented as a `std::mutex` and a `std::condition_variable`.

```cpp
#include <map>
#include <mutex>
#include <condition_variable>
#include <new>
#include <stdexcept>

class SemaphoreManager {
public:
    SemaphoreManager() {}

    void createSemaphore(unsigned int id, unsigned int initialValue) {
        auto it = semaphores_.emplace(id, std::make_unique<Semaphore>(initialValue));
        if (!it.second) {
            throw std::runtime_error("Failed to create semaphore with duplicate ID");
        }
    }

    void deleteSemaphore(unsigned int id) {
        auto it = semaphores_.find(id);
        if (it == semaphores_.end()) {
            throw std::runtime_error("Failed to find semaphore with given ID");
        }
        it->second->~Semaphore();
        semaphores_.erase(it);
    }

private:
    struct Semaphore {
        Semaphore(unsigned int initialValue) : value_(initialValue), mutex_(), cv_() {}

        void wait() {
            std::unique_lock<std::mutex> lock(mutex_);
            while (value_ <= 0) {
                cv_.wait(lock);
            }
            --value_;
            lock.unlock();
        }

        void signal() {
            std::unique_lock<std::mutex> lock(mutex_);
            ++value_;
            lock.unlock();
            cv_.notify_one();
        }

        unsigned int value_;
        std::mutex mutex_;
        std::condition_variable cv_;
    };

    std::map<unsigned int, std::unique_ptr<Semaphore>> semaphores_;
};
```

