    async fn load(file_path: &str, max_retries: usize, timeout: Duration) -> Result<Self, Box<dyn std::error::Error>> {
        let config = serde_json::from_reader(File::open(file_path)?).unwrap();
        let unique_servers = Arc::new(HashSet::with_capacity(config.servers.len()));

        let mut loaded_servers = vec![];
        let mut errors = vec![];

        for server in &config.servers {
            if unique_servers.contains(&server.address.clone()) {
                errors.push(format!("Duplicate server address: {}", server.address));
                continue;
            }
            unique_servers.insert(server.address.clone());

            let config_loader = Arc::new(Self {
                config: Arc::clone(&config),
                unique_servers,
                max_retries,
                timeout,
            });

