                    Ok(_) => loaded_servers.push(server.clone()),
                    Err(e) => errors.push(format!("Validation error for server {}: {}", server.address, e)),
                }
            });
        }

        // Wait for all tasks to complete and collect results
        let mut handles = vec![];
        for _ in 0..config.servers.len() {
            handles.push(task::spawn(async move {
                task::yield_now().await;
            }));
        }

        for handle in handles {
            handle.join().await;
        }

        if errors.is_empty() {
            Ok(ConfigLoader { config, unique_servers, max_retries, timeout })
        } else {
            Err(errors.into())
        }
    }
}

