using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Xml;
using System.Xml.XPath;
using System.Threading;
using System.Runtime.ExceptionServices;

public class ModuleManager
{
    private readonly string _baseDirectory;

    public ModuleManager(string baseDirectory)
    {
        _baseDirectory = Path.Combine(baseDirectory, "modules");
    }

    public string GetConfigValue(string moduleIdentifier, string attributeName)
    {
        var modulePath = Path.Combine(_baseDirectory, moduleIdentifier);
        if (!Directory.Exists(modulePath))
            Directory.CreateDirectory(modulePath);

        var envVariableName = $"MOD_{moduleIdentifier}";
        if (!Environment.GetEnvironmentVariables().ContainsKey(envVariableName))
        {
            Environment.SetEnvironmentVariable(envVariableName, modulePath);
        }

        var lockObject = new object();
        var environmentValue = Interlocked.Exchange(ref _environmentValues[envVariableName], null);
        if (environmentValue == null)
        {
            lock (lockObject)
            {
                if (_environmentValues[envVariableName] == null)
                {
                    var xmlFilePath = Path.Combine(modulePath, "config.xml");
                    if (!File.Exists(xmlFilePath))
                        throw new FileNotFoundException("Config file not found", xmlFilePath);

                    using (var reader = XmlReader.Create(xmlFilePath))
                    {
                        var configNode = reader.SelectSingleNode("/config/element[@name='" + attributeName + "']");
                        if (configNode == null)
                            throw new XPathException("No matching element found for attribute name: " + attributeName);

                        _environmentValues[envVariableName] = configNode.Value;
                    }
                }
            }
        }

        return _environmentValues[envVariableName];
    }

    private readonly Dictionary<string, string> _environmentVariables = new Dictionary<string, string>();
}
```

