const scriptCache = new Map();
const roleFetchPromise = fetch('https://api.example.com/user-role')
  .then(response => response.json())
  .then(data => data.role);

async function generateFooter(scripts) {
  const role = await (roleFetchPromise || (roleFetchPromise = fetch('https://api.example.com/user-role')));
  if (role !== 'admin') {
    scripts = scripts.filter(script => !script.hasOwnProperty('adminOnly'));
  }

  let footerHtml = '<div id="footer">';

  for (const script of scripts) {
    const key = script.key || Math.random().toString(36).substring(7);
    const sanitizedCode = document.createTextNode(DOMPurify.sanitize(script.code));

    if (!scriptCache.has(key)) {
      footerHtml += `<script id="${key}" key="${key}">${sanitizedCode}</script>`;
      scriptCache.set(key, sanitizedCode);
    } else {
      const existingScript = document.getElementById(key);
      if (existingScript) {
        existingScript.innerHTML = sanitizedCode;
      }
    }
  }

  footerHtml += '</div>';

  // Insert the generated HTML into the body of the document
  const footer = document.createElement('div');
  footer.innerHTML = footerHtml;
  document.body.appendChild(footer);
}
```

This function fetches user role information from an external API and filters out scripts marked as `adminOnly` if the user is not an administrator. It uses DOMPurify to sanitize script content, preventing cross-scripting (XSS) attacks. The function caches sanitized script content to minimize latency when rendering multiple scripts with the same code.

