      this.apiConnected = false;
    }

    process.on('cpuUsage', () => {
      this.serverLoad = process.cpuUsage().user / (1024 * 1024);
    });

    this.start();
  }

  start() {
    if (!this.pause && this.apiConnected) {
      setTimeout(() => {
        this.stream.write(`Server Load: ${this.serverLoad.toFixed(2)}, API Connected: ${this.apiConnected}\n`);
        this.collectData();
        this.start();
      }, 1000 / this.rateLimit);
    }
  }

  collectData() {
    // Implement data collection logic here
  }

  pauseDataCollection() {
    this.pause = true;
  }

  resumeDataCollection() {
    this.pause = false;
  }
}
```

