class ThemeFetcher {
    private static final int CACHE_EXPIRATION = 60 * 60 * 24; // 1 day in seconds
    private SharedPreferences preferences;
    private ApiService apiService;
    private File cacheDir;
    private ThemeParser parser;

    public ThemeFetcher(Context context, ApiService apiService) {
        this.preferences = PreferenceManager.getDefaultSharedPreferences(context);
        this.apiService = apiService;
        this.cacheDir = new File(context.getCacheDir(), "themes");
        this.parser = new ThemeParser();
    }

    public Bitmap fetchLatestTheme() {
        long lastFetch = preferences.getLong("last_theme_fetch", 0);
        long currentTime = System.currentTimeMillis();
        if (currentTime - lastFetch > CACHE_EXPIRATION) {
            try {
                Response<ThemeSpecification> response = apiService.getLatestTheme();
                ThemeSpecification spec = response.body();
                File themeFile = new File(cacheDir, spec.getId() + ".png");
                Bitmap bitmap = parser.parseTheme(themeFile);
                if (bitmap != null) {
                    preferences.edit().putLong("last_theme_fetch", currentTime).apply();
                    return bitmap;
                }
            } catch (IOException e) {
                Log.e("ThemeManager", "Error fetching latest theme: " + e.getMessage());
            }
        }
        // Return cached theme if available, or null otherwise
    }
}
```

