// random-string-generator.ts
import { CharacterSet } from './character-set';

class RandomStringGenerator {
  generate(length: number, charSet?: string): string {
    const characterSet = new CharacterSet(charSet);
    return characterSet.generateRandomString(length);
  }
}

// password-hasher.ts
import bcrypt from 'bcrypt';
import argon2 from 'argon2';
import pbkdf2 from 'pbkdf2';

class PasswordHasher {
  async hash(password: string, algorithm: string, iterations: number): Promise<string> {
    switch (algorithm) {
      case 'bcrypt':
        return bcrypt.hashSync(password, iterations);
      case 'argon2':
        return argon2.hashSync(password, { type: argon2.Argon2id, hashLength: 64, parallelism: 1, timeCost: iterations });
      case 'pbkdf2':
        const derivedKey = pbkdf2Sync(password, 'salt', iterations, 64, 'sha512');
        return Buffer.from(derivedKey).toString('hex');
    }
  }
}

// character-set.ts
export class CharacterSet {
  private alphanumeric: string;
  private lowercase: string;
  private uppercase: string;
  private custom: string;

  constructor(customCharSet?: string) {
    this.alphanumeric = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    this.lowercase = 'abcdefghijklmnopqrstuvwxyz0123456789';
    this.uppercase = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    this.custom = customCharSet || '';
  }

  generateRandomString(length: number): string {
    const characters = this.alphanumeric + this.lowercase + this.uppercase + this.custom;
    let result = '';
    for (let i = length; i > 0; --i) result += characters[Math.floor(Math.random() * characters.length)];
    return result;
  }
}

// logger.ts
