        free_state(states[i]);
    }
    free(states);
}

State** create_linked_list_from_fsa(int* states, int stateCount, Transition** transitions, int transitionCount, State** lastState) {
    if (!is_valid_fsa(states, stateCount, 0, transitions, transitionCount)) {
        fprintf(stderr, "Invalid FSA\n");
        return NULL;
    }

    // Allocate memory for the linked list and initialize the first state
    State** statesList = (State**)malloc((stateCount + 1) * sizeof(State*));
    if (!statesList) {
        fprintf(stderr, "Memory allocation failed\n");
        free_fsa(states, stateCount);
        return NULL;
    }

    // Initialize the first state
    statesList[0] = create_state(states[0]);
    if (!statesList[0]) {
        fprintf(stderr, "Memory allocation failed\n");
        free_fsa(states, stateCount);
        free(statesList);
        return NULL;
    }

    // Process the transitions and link the states together
    for (int i = 0; i < transitionCount; ++i) {
        Transition* transition = transitions[i];
        State* fromState = statesList[transition->id.next];
        if (!fromState) {
            fprintf(stderr, "Invalid state %d\n", transition->id.next);
            free_fsa(states, stateCount + 1);
            free(statesList);
            return NULL;
        }

        State* toState = create_state(transition->to->id);
        if (!toState) {
            fprintf(stderr, "Memory allocation failed\n");
            free_fsa(states, stateCount + 1);
            free(statesList);
            return NULL;
        }

        // Add the transition to the fromState and update the toState's next pointer
        if (!fromState->transitions) {
            fromState->transitions = (Transition*)malloc(sizeof(Transition));
            if (!fromState->transitions) {
                fprintf(stderr, "Memory allocation failed\n");
                free_fsa(states, stateCount + 1);
                free(statesList);
                return NULL;
            }
        }
        fromState->transitions[fromState->transitionCount] = *transition;
        fromState->transitionCount++;

        // Update the toState's next pointer and add it to the list
        toState->next = statesList[transition->to->id].next;
        statesList[transition->to->id].next = toState;
    }

    *lastState = statesList[stateCount - 1];
    return statesList;
}
```

