    if (path_length > 256) {
        return "Error: Filename exceeds the specified constraints.";
    }

    // Allocate memory for new filename and extensions
    char* new_filename = malloc(path_length + 10);
    if (!new_filename) {
        return "Error: Out of memory.";
    }

    // Copy the original filename
    strcpy(new_filename, original_filename);

    // Find and store digits in a temporary array
    int has_digit = 0;
    char digit_array[16];
    for (size_t i = 0; i < path_length; ++i) {
        if (isdigit(new_filename[i])) {
            digit_array[has_digit++] = new_filename[i];
        }
    }

    // Sort the digits in the array for consistent ordering
    qsort(digit_array, has_digit, sizeof(char), (int (*)(const void*, const void*))strcmp);

    // Append sorted digits to the new filename as a new extension
    if (has_digit > 0) {
        snprintf(new_filename + path_length - 4, 5, ".%d", digit_array[0]);
        for (size_t i = 1; i < has_digit; ++i) {
            snprintf(new_filename + path_length - 4 + i, 5 - i, "%d", digit_array[i]);
        }
    }

    // Replace the original extension with ".csv" or ".log" based on the current extension
    const char* ext = strrchr(new_filename, '.');
    if (ext && strcasecmp(ext, ".exe") == 0) {
        strcpy(ext, ".csv");
    } else if (ext && strlen(ext) < 6) {
        strcpy(ext, ".log");
    }

    // Handle potential path traversal vulnerabilities
    for (size_t i = 0; i < path_length; ++i) {
        if (new_filename[i] == '..') {
            return "Error: Potential path traversal vulnerability.";
        }
    }

    // Ensure compatibility across different operating systems
    for (size_t i = 0; i < path_length; ++i) {
        if (new_filename[i] == '/' || new_filename[i] == '\\') {
            new_filename[i] = '_';
        }
    }

    // Error handling for ambiguous extensions and invalid paths
    const char* dot = strchr(new_filename, '.');
    if (!dot || (dot > (new_filename + path_length - 4))) {
        return "Error: Ambiguous extension or invalid path.";
    }

    return new_filename;
}
