void check_and_set_default_theme_dir() {
    if (!default_theme_dir) default_theme_dir = "/path/to/themes";
}

ThemeCache* find_theme(const char *theme_name) {
    for (int i = 0; i < cache_size; ++i) {
        if (strcmp(theme_cache[i].path, theme_name) == 0 && theme_cache[i].png) continue;
        free(theme_cache[i].path);
    }
    return NULL;
}

ThemeCache* get_or_load_theme(const char *theme_name) {
    ThemeCache *cached_theme = find_theme(theme_name);
    if (cached_theme && cached_theme->png) return cached_theme;

    char path[256];
    snprintf(path, sizeof(path), "%s/%s.png", default_theme_dir, theme_name);
    cached_theme = malloc(sizeof(ThemeCache));
    strcpy(cached_theme->path, path);

    FILE *file = fopen(path, "rb");
    if (!file) return NULL;

    int error = 0;
    png_structp png_ptr = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
    if (!png_ptr) {
        fclose(file);
        return NULL;
    }

    png_infop info_ptr = png_create_info_struct(png_ptr);
    if (!info_ptr) {
        png_destroy_read_struct(&png_ptr, (png_infopp)NULL, (png_infopp)NULL);
        fclose(file);
        return NULL;
    }

    if (setjmp(png_jmpbuf(png_ptr))) {
        png_destroy_read_struct(&png_ptr, &info_ptr, (png_infopp)NULL);
        fclose(file);
        free(cached_theme->path);
        return NULL;
    }

    png_init_io(png_ptr, file);
    png_read_info(png_ptr, info_ptr);
    png_ptr->end_code = PNG_DICT_END;

    cached_theme->png = png_create_write_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
    if (!cached_theme->png) {
        png_destroy_read_struct(&png_ptr, &info_ptr, (png_infopp)NULL);
        fclose(file);
        free(cached_theme->path);
        return NULL;
    }

    png_infop new_info_ptr = png_create_info_struct(cached_theme->png);
    if (!new_info_ptr) {
        png_destroy_write_struct(&cached_theme->png, &new_info_ptr);
        png_destroy_read_struct(&png_ptr, &info_ptr, (png_infopp)NULL);
        fclose(file);
        free(cached_theme->path);
        return NULL;
    }

    png_set_write_fn(cached_theme->png, NULL, write_data, NULL);
    png_set_error_fn(cached_theme->png, error_handler, (void*)cached_theme);

    png_read_update_info(png_ptr, info_ptr);
    png_write_info(cached_theme->png, new_info_ptr);

    int bit_depth = png_get_bit_depth(png_ptr, info_ptr);
    if (bit_depth != 8) {
        png_destroy_read_struct(&png_ptr, &info_ptr, (png_infopp)NULL);
        png_destroy_write_struct(&cached_theme->png, &new_info_ptr);
        fclose(file);
        free(cached_theme->path);
        return NULL;
    }

    png_read_update_info(png_ptr, info_ptr);
    png_write_image(cached_theme->png, new_info_ptr);
    png_write_end(cached_theme->png, new_info_ptr);

    png_destroy_read_struct(&png_ptr, &info_ptr, (png_infopp)NULL);
    fclose(file);

    return cached_theme;
}
```

