    source_buffer = (char*)malloc(source_size);
    if (!source_buffer) {
        fclose(source_file);
        log_error("Failed to allocate memory for source buffer.");
        return NULL;
    }

    size_t read = fread(source_buffer, 1, source_size, source_file);
    if (read != source_size) {
        free(source_buffer);
        fclose(source_file);
        log_error("Failed to read source file.");
        return NULL;
    }

    Config* config = malloc(sizeof(Config));
    if (!config) {
        free(source_buffer);
        fclose(source_file);
        log_error("Failed to allocate memory for configuration.");
        return NULL;
    }

    // Initialize the configuration structure with provided parameters.

    FILE *destination_file = fopen(destination, "wb");
    if (!destination_file) {
        free(config);
        free(source_buffer);
        fclose(source_file);
        log_error("Failed to open destination file: %s", strerror(errno));
        return NULL;
    }

    // Use the third-party library to convert JPEG to PDF.
    // Handle any errors gracefully, logging warnings but not halting the operation.

    pdf_data = serialize_pdf(pdf_data);
    if (!pdf_data) {
        fclose(destination_file);
        free(config);
        free(source_buffer);
        log_error("Failed to serialize PDF.");
        return NULL;
    }

    size_t written = fwrite(pdf_data, 1, strlen(pdf_data), destination_file);
    if (written != strlen(pdf_data)) {
        free(pdf_data);
        fclose(destination_file);
        free(config);
        free(source_buffer);
        log_error("Failed to write PDF data.");
        return NULL;
    }

    free(pdf_data);
    fclose(destination_file);
    free(config);
    free(source_buffer);
    fclose(source_file);

    return NULL;
}
