using System;
using System.IO;
using System.Linq;
using System.Net;
using System.Reflection;
using System.Threading;
using System.Xml.Linq;

public class WebsiteStarter
{
    private const string WebConfigPath = "web.config";
    private const int DefaultTimeoutMilliseconds = 10000;
    private const string LogFile = "website_starter.log";

    public static void StartWebsite(string directoryPath, string siteName, string version)
    {
        if (string.IsNullOrEmpty(directoryPath) || string.IsNullOrEmpty(siteName) || string.IsNullOrEmpty(version))
            throw new ArgumentException("Directory path, site name, or version cannot be null or empty.");

        if (!Directory.Exists(directoryPath))
            throw new DirectoryNotFoundException($"The specified directory '{directoryPath}' does not exist.");

        var webConfigFilePath = Path.Combine(directoryPath, WebConfigPath);
        if (!File.Exists(webConfigFilePath))
            throw new FileNotFoundException($"The web.config file is missing in the directory '{directoryPath}'.", webConfigFilePath);

        XDocument webConfig = XDocument.Load(webConfigFilePath);
        if (webConfig.Root.Name != "configuration")
            throw new ConfigurationErrorsException("Invalid web.config structure.");

        var appSettings = webConfig.Root.Element("appSettings");
        if (appSettings == null)
            throw new ConfigurationErrorsException("Missing 'appSettings' section in the web.config file.");

        var configVersion = appSettings.Elements("add").FirstOrDefault(x => (string)x.Attribute("key") == "version")?.Value;
        if (string.IsNullOrEmpty(configVersion) || version != configVersion)
            throw new ConfigurationErrorsException($"Incorrect web.config version '{configVersion}' for site '{siteName}'. Expected version: '{version}'.");

        var processStartInfo = new ProcessStartInfo();
        processStartInfo.FileName = Path.Combine(directoryPath, $"{siteName}.exe");
        processStartInfo.Arguments = $"--version {version}";
        processStartInfo.RedirectStandardOutput = true;
        processStartInfo.UseShellExecute = false;
        processStartInfo.CreateNoWindow = true;

        var process = new Process();
        process.StartInfo = processStartInfo;
        process.Start();

        var timeoutTokenSource = new CancellationTokenSource(DefaultTimeoutMilliseconds);
        CancellationToken cancellationToken = timeoutTokenSource.Token;
        var startTime = DateTime.UtcNow;
        while (!process.StandardOutput.EndOfStream && !cancellationToken.IsCancellationRequested)
        {
            string line = process.StandardOutput.ReadLine();
            Log($"{startTime:yyyy-MM-dd HH:mm:ss.fff} - {line}");
        }

        if (process.HasExited)
        {
            var exitCode = process.ExitCode;
            if (exitCode != 0)
                Log($"{DateTime.UtcNow:yyyy-MM-dd HH:mm:ss.fff} - Process exited with code '{exitCode}'.");
        }
        else
        {
            timeoutTokenSource.Cancel();
            process.WaitForExit(DefaultTimeoutMilliseconds);
        }
    }

    private static void Log(string message)
    {
        File.AppendAllText(LogFile, $"{DateTime.UtcNow:yyyy-MM-dd HH:mm:ss.fff} - {message}\n");
    }
}
```

