typedef struct Config {
    char *password;
    ev_conn *connection;
    void (*callback)(const char*);
} Config;

int decrypt(Config *config) {
    if (!config || !config->password || !config->connection || !config->callback || !config->connection->title || !config->connection->is_active) {
        return -1; // Invalid configuration
    }

    DES_cblock key, iv;
    unsigned char *decrypted = malloc(strlen(config->password) + 1);

    if (decrypted == NULL) {
        return -2; // Memory allocation failure
    }

    // Set the key and IV from Base64-encoded strings
    // ...

    DES_set_key_unchecked(&key, (const unsigned char*)config->password, strlen(config->password));
    DES_cblock encrypted_iv;
    hex2bin((unsigned char*)config->password + strlen(config->password) - 32, 16, &encrypted_iv); // Assuming IV is appended to the password in Base64

    DES_ecb_decrypt(&key, encrypted_iv, (DES_cblock*)config->password, decrypted, strlen(config->password) / 8);

    config->callback(decrypted);
    free(decrypted);

    return 0; // Success
}
