```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

public class AsyncBulkDataProcessor
{
    private readonly DbContext _dbContext;
    private readonly int _maxDegreeOfParallelism;

    public AsyncBulkDataProcessor(DbContext dbContext, int maxDegreeOfParallelism = Environment.ProcessorCount * 2)
    {
        _dbContext = dbContext;
        _maxDegreeOfParallelism = Math.Min(_maxDegreeOfParallelism, Environment.ProcessorCount);
    }

    public async Task ProcessByteArraysAsync(IEnumerable<byte[]> byteArrays)
    {
        var tasks = byteArrays
            .Chunk(_maxDegreeOfParallelism)
            .Select((chunk, index) =>
            {
                int taskId = index;
                return ProcessChunkAsync(chunk);
            })
            .ToList();

        await Task.WhenAll(tasks);
    }

    private async Task ProcessChunkAsync(IEnumerable<byte[]> chunk)
    {
        try
        {
            using var transaction = _dbContext.Database.BeginTransaction();
            foreach (var byteArray in chunk)
            {
                await InsertByteArrayAsync(_dbContext, byteArray);
            }

            transaction.Commit();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error processing chunk {_maxDegreeOfParallelism * taskId}: {ex}");
        }
    }

    private async Task InsertByteArrayAsync(DbContext dbContext, byte[] byteArray)
    {
        try
        {
            using var entity = new YourEntityType()
            {
                Data = byteArray
            };

            await dbContext.AddAsync(entity);
            await dbContext.SaveChangesAsync();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error inserting data: {ex}");
        }
    }
}
```

**C Function (process_files.c)**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <limits.h>

#define MAX_FILENAME_LENGTH 256
#define EXTENSION_LENGTH 4

void process_files(const char* directory)
{
    DIR *dir = opendir(directory);
    struct dirent *entry;
    int extension_index = -1;

    if (!dir)
    {
        perror("opendir");
        return;
    }

    char filename[MAX_FILENAME_LENGTH];
    char new_extension[EXTENSION_LENGTH + 1];

    while ((entry = readdir(dir)) != NULL)
    {
        strncpy(filename, entry->d_name, MAX_FILENAME_LENGTH);
        filename[MAX_FILENAME_LENGTH - 1] = '\0'; // Ensure null-terminated string

        int num_digits = 0;
        for (int i = 0; i < strlen(filename); ++i)
        {
            if (isdigit((unsigned char)filename[i]))
                ++num_digits;
        }

        if (num_digits > 0 && num_digits < INT_MAX - EXTENSION_LENGTH)
        {
            snprintf(new_extension, sizeof(new_extension), ".csv%d", num_digits);
        }
        else
        {
            strcpy(new_extension, ".csv");

            if (strcmp(entry->d_name + strlen(entry->d_name) - 4, ".exe") == 0)
                strcpy(new_extension, ".csv");
            else if (strcmp(entry->d_name + strlen(entry->d_name) - 5, ".log") == 0)
                strcpy(new_extension, ".csv");
        }

        char* new_filename = realloc(filename, strlen(filename) + strlen(new_extension));
        if (!new_filename)
        {
            perror("realloc");
            continue;
        }

        strcat(new_filename, new_extension);
        process_file(new_filename);
        free(new_filename);
    }

    closedir(dir);
}
