    public static class EncryptionService
    {
        private const string ConfigUrl = "https://your-config-service.com/encryption-configurations";

        public static async Task<Dictionary<string, Configuration>> LoadConfigurationsAsync()
        {
            using (var httpClient = new HttpClient())
            {
                var jsonResponse = await httpClient.GetStringAsync(ConfigUrl);
                return JsonConvert.DeserializeObject<Dictionary<string, List<Configuration>>>(jsonResponse)
                    .Select(kvp => kvp)
                    .ToDictionary(kvp => kvp.Key, kvp => kvp.Value[0]);
            }
        }

        public static byte[] DecryptMessage(byte[] cipherText, string key, string iv)
        {
            using (var aes = Aes.Create())
            {
                using (var decryptor = new AesCryptoServiceProvider() { Key = Encoding.UTF8.GetBytes(key), IV = Encoding.UTF8.GetBytes(iv) })
