```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class AesCbcDecrypter
{
    private readonly byte[] _key;
    private readonly byte[] _iv;
    private readonly HMACSHA256 _hmac;
    private readonly HashAlgorithmName _hmacAlgorithm = HashAlgorithmName.SHA256;
    private readonly AesCryptoServiceProvider _aes;
    private readonly Rfc2898DeriveBytes _prf;

    public AesCbcDecrypter(byte[] key, byte[] iv)
    {
        _key = key;
        _iv = iv;
        _aes = new AesCryptoServiceProvider();
        _aes.KeySize = 256;
        _aes.BlockSize = 128;
        _aes.Mode = CipherMode.CBC;
        _aes.Padding = PaddingMode.PKCS7;
        _prf = new Rfc2898DeriveBytes(key, iv, 1000); // Derive HMAC key from AES key and IV
        _hmac = new HMACSHA256(_prf.GetBytes(_hmacAlgorithm.CreateHashSize()));
    }

    public byte[] GenerateIv()
    {
        var rng = RandomNumberGenerator.Create();
        var iv = new byte[16];
        rng.GenerateBytes(iv);
        return iv;
    }

    public async Task<List<byte[]>> DecryptBatchAsync(Stream input, List<byte[]> ivs)
    {
        _aes.Key = _key;
        _aes.IV = _iv;

        var decryptedData = new List<byte[]>();
        using (var cs = new CryptoStream(input, _aes.CreateDecryptor(), CryptoStreamMode.Read))
        {
            byte[] buffer = new byte[4096];
            int read;
            while ((read = await cs.ReadAsync(buffer, 0, buffer.Length)) > 0)
            {
                var iv = ivs[ivs.IndexOf(_aes.IV)]; // Use the correct IV for each block
                _aes.IV = iv;
                var hmac = _hmac.ComputeHash(buffer);
                Array.Copy(hmac, buffer.Length - hmac.Length, buffer, buffer.Length - hmac.Length, hmac.Length); // Append HMAC to the end of the buffer

                using (var md5 = MD5.Create())
                {
                    var hash = md5.ComputeHash(buffer);
                    if (!VerifyHmac(hash)) throw new Exception("Invalid HMAC");
                }

                decryptedData.Add(new ArraySegment<byte>(buffer, 0, read - hmac.Length).ToArray());
            }
        }

        return decryptedData;
    }

    private bool VerifyHmac(byte[] data)
    {
        var hmac = _hmac.ComputeHash(data);
        using (var md5 = MD5.Create())
        {
            var hash = md5.ComputeHash(data);
            return Array.TrueForAll(hash, i => hash[i] == hmac[i]);
        }
    }
}
```

