class IntArray {
  constructor(size, memoryLimit) {
    this.arrayBuffer = new ArrayBuffer(size * Int32Array.BYTES_PER_ELEMENT);
    this.view = new Int32Array(this.arrayBuffer);
    this.memoryLimit = memoryLimit;
    this.currentSize = 0;
  }

  resize(newSize) {
    if (newSize > this.memoryLimit || newSize < this.currentSize) {
      throw new Error('Invalid array size');
    }

    const newArrayBuffer = new ArrayBuffer(newSize * Int32Array.BYTES_PER_ELEMENT);
    const newView = new Int32Array(newArrayBuffer);

    if (this.currentSize > 0) {
      newView.set(this.view, 0);
    }

    this.arrayBuffer = newArrayBuffer;
    this.view = newView;
    this.currentSize = newSize;
  }
}

