using namespace boost;
using namespace std;
using namespace sandesh;
using namespace mockito;

struct Vertex {
    string ip;
    string metadata_ip;
    string uuid;
};

typedef adjacency_list<vecS, vecS, undirectedS, Vertex> Graph;

class MockInterfaceTable : public InterfaceTable {
public:
    MOCK_METHOD0(FindVmUuidFromMetadataIp, bool());
};

void generateGraph(Graph& g, int verticesCount, int edgesCount) {
    default_random_engine generator;
    uniform_int_distribution<int> distribution(1, 254);

    for (int i = 0; i < verticesCount; ++i) {
        Vertex v;
        v.ip = to_string(distribution(generator));
        v.metadata_ip = to_string(distribution(generator));
        add_vertex(g, v);
    }

    for (int i = 0; i < edgesCount; ++i) {
        int a = generator() % verticesCount;
        int b = generator() % verticesCount;

        if (a == b) continue;

        auto& va = g[a];
        auto& vb = g[b];

        edge(a, b, edge_property_t()).second->vertex_properties()[0] = va.ip;
        edge(a, b, edge_property_t()).second->vertex_properties()[1] = vb.ip;
    }
}

int main() {
    MockInterfaceTable mockInterfaceTable;
    when(mockInterfaceTable.FindVmUuidFromMetadataIp()).thenReturn(true);

    Graph g;
    int verticesCount = 1000;
    int edgesCount = 5000;

    generateGraph(g, verticesCount, edgesCount);

    // Integrate with Sandesh-based monitoring system here...

    return 0;
}
```

