```cpp
#include <vector>
#include <unordered_map>

class Record {
public:
    int key;
    long offset;
};

class HashTable {
private:
    static constexpr size_t SIZE = 1024;
    std::unordered_map<int, size_t> hashMap;
    std::vector<Record> records;

public:
    Record* get(int key) {
        size_t index = hash(key);
        size_t currentIndex = index;
        do {
            if (records[currentIndex].key == key) return &records[currentIndex];
            currentIndex = (index + 1 + records.size()) % SIZE;
        } while (currentIndex != index);
        return nullptr;
    }

    void put(Record& record) {
        size_t index = hash(record.key);
        size_t currentIndex = index;
        do {
            if (records[currentIndex].key == 0) {
                records[currentIndex] = record;
                hashMap[record.key] = currentIndex;
                break;
            }
            currentIndex = (index + 1 + records.size()) % SIZE;
        } while (currentIndex != index);
    }

    size_t hash(int key) const {
        return key % SIZE;
    }
};
```

