```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public class AdvancedRandomValueGenerator
{
    private readonly Random _random;
    private readonly FileStream _logFile;
    private readonly string _logFilePath;
    private readonly Tuple<int, int> _range;
    private readonly long _resetThreshold;
    private long _iterationCount;
    private long _lastResetTime;

    public AdvancedRandomValueGenerator(Tuple<int, int> range, long resetThreshold, string logFilePath)
    {
        _range = range;
        _resetThreshold = resetThreshold;
        _logFilePath = logFilePath;
        _random = new Random();

        if (_range.Item1 > _range.Item2)
            throw new ArgumentException("Minimum value should not exceed maximum.");

        _logFile = File.OpenWrite(_logFilePath);
    }

    public int NextInt()
    {
        lock (_random)
        {
            if (Interlocked.Increment(ref _iterationCount) >= _resetThreshold && DateTime.UtcNow - _lastResetTime > TimeSpan.FromMinutes(5))
                Reseed();

            return _range.Item1 + new Random().Next(_range.Item2 - _range.Item1);
        }
    }

    public float NextFloat()
    {
        lock (_random)
        {
            if (Interlocked.Increment(ref _iterationCount) >= _resetThreshold && DateTime.UtcNow - _lastResetTime > TimeSpan.FromMinutes(5))
                Reseed();

            return _range.Item1 + (float)(_random.NextDouble() * (_range.Item2 - _range.Item1));
        }
    }

    private void Reseed()
    {
        _lastResetTime = DateTime.UtcNow;
        _random.Next(); // Consume the random number to ensure it's not used again immediately
    }

    public void Log(object value)
    {
        var logWriter = new StreamWriter(_logFile);
        logWriter.WriteLine($"{DateTime.UtcNow}: {value}");
        logWriter.Flush();
    }

    public override string ToString()
    {
        return $"AdvancedRandomValueGenerator: Seed={_random.NextState}, Range={_range}, IterationCount={_iterationCount}, LastResetTime={_lastResetTime}";
    }
}
```

