import java.io.*;
import java.util.*;

class Record {
    int value;

    public Record(int value) {
        this.value = value;
    }
}

class DataManager {
    private final Record[] records;
    private final UnionFind uf;
    private final Object lock = new Object();
    private static final int MAX_RECORDS = 10000;

    public DataManager() throws IOException {
        records = new Record[MAX_RECORDS];
        uf = new UnionFind(MAX_RECORDS);

        // Load data from file if it exists
        loadDataFromFile();
    }

    private void loadDataFromFile() throws IOException {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream("data.bin"))) {
            while (true) {
                try {
                    records[uf.findSet(ois.readInt())] = (Record) ois.readObject();
                } catch (EOFException eof) {
                    break;
                }
            }
        }
    }

    public void saveDataToFile() throws IOException {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream("data.bin"))) {
            for (Record record : records) {
                if (record != null) {
                    oos.writeInt(uf.findSet(record));
                    oos.writeObject(record);
                }
            }
        }
    }

    public void addRecord(int value) throws InterruptedException {
        synchronized (lock) {
            for (int i = 0; i < records.length; i++) {
                if (records[i] == null || records[uf.findSet(value)] != records[i]) {
                    int index = uf.unionSets(value, i);
                    records[index] = new Record(value);
                    break;
                }
            }
        }
    }

    public int getDisjointPairsCount() {
        return uf.getCount();
    }
}

class UnionFind {
    private final int[] parent;
    private final int[] size;

    public UnionFind(int n) {
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
    }

    public int findSet(int x) {
        if (parent[x] != x) {
            parent[x] = findSet(parent[x]);
        }
        return parent[x];
    }

    public void unionSets(int x, int y) {
        int rootX = findSet(x);
        int rootY = findSet(y);

        if (rootX != rootY) {
            if (size[rootX] < size[rootY]) {
                int temp = rootX;
                rootX = rootY;
                rootY = temp;
            }
            parent[rootY] = rootX;
            size[rootX] += size[rootY];
        }
    }

    public int getCount() {
        return Arrays.stream(size).filter(i -> i > 1).sum();
    }
}
```

This code provides a `DataManager` class that manages an array of records, uses a Union-Find data structure to check for disjoint pairs, and serializes/deserializes the records to/from a file. The `DataManager` class also includes synchronization mechanisms to ensure data integrity and consistency in a concurrent environment.

