#include <pthread.h>
#include <semaphore.h>
#include <log4c.h>

struct log_private {
    LOG *logger;
};

void log_message(const struct log_private *lp, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vlog_debug(lp->logger, format, args);
    va_end(args);
}

char* generate_new_filename(const char *original_filename) {
    size_t len = strlen(original_filename);
    if (len > 1024) {
        return "Error: Filename exceeds the maximum length of 1024 characters.";
    }

    char *new_filename = malloc(len + 16); // Allocate extra space for extension and number of chars.
    strcpy(new_filename, original_filename);

    size_t ext_start = len - 4; // Start from the last dot (if any).
    if (ext_start > len) {
        ext_start = len; // If no extension, use the entire filename.
    }

    char *extension = ".csv";
    if (strcasecmp(new_filename + ext_start, ".exe") == 0) {
        extension = ".csv";
    } else if (ext_start > 3 && strcasecmp(new_filename + ext_start - 3, ".dat") != 0) {
        extension = ".dat";
    }

    size_t num_chars = len;
    for (size_t i = 0; i < len; ++i) {
        if (!isalnum(new_filename[i])) {
            --num_chars;
        }
    }

    snprintf(new_filename + ext_start, 16 - ext_start, "%zu", num_chars); // Append the number of alphanumeric characters.
    strcat(new_filename, extension);

    return new_filename;
}

pid_t execute_command(const char *filename) {
    pid_t child_pid = fork();

    if (child_pid == -1) {
        log_message(&log_private, "Error: Fork failed.");
        return -1;
    } else if (child_pid > 0) { // Parent process.
        int status;
        waitpid(child_pid, &status, 0);
        if (WIFEXITED(status)) {
            return WEXITSTATUS(status);
        } else {
            log_message(&log_private, "Error: Command execution failed.");
            return -1;
        }
    } else { // Child process.
        execlp("./", "./", filename, NULL);
        perror("Error: Execvp failed");
        exit(EXIT_FAILURE);
    }
}

char* execute_command_and_get_filename(const char *original_filename) {
    char *new_filename = generate_new_filename(original_filename);
    if (new_filename == NULL) {
        return new_filename;
    }

    int result = execute_command(new_filename);
    if (result == -1) {
        free(new_filename);
        return "Error: Command execution failed.";
    } else if (result != 0) {
        log_message(&log_private, "Warning: Command executed with non-zero exit status.");
    }

    return new_filename;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return -1;
    }

    struct log_private log_private = {
        .logger = LOG4C_ROOT_LOGGER
    };

    char *result = execute_command_and_get_filename(argv[1]);
    if (result == NULL) {
        fprintf(stderr, "%s\n", result);
        return -1;
    }

    printf("New filename: %s\n", result);
    free(result);
    return 0;
}
```

