```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <limits.h>

typedef struct {
    int* data;
    size_t capacity;
    size_t length;
} DataSet;

void merge(DataSet* a, size_t left, size_t mid, size_t right) {
    // Implement the merge sort logic here
}

void mergeSort(DataSet* dataSet) {
    if (dataSet->length < 2) return;

    size_t length = dataSet->length;
    size_t chunkSize = length / 2;

    DataSet left, right;
    left.data = malloc((chunkSize > dataSet->capacity) ? dataSet->capacity : chunkSize * sizeof(int));
    right.data = malloc((length - chunkSize) * sizeof(int));

    memcpy(left.data, dataSet->data, (chunkSize > dataSet->capacity) ? dataSet->capacity * sizeof(int) : chunkSize * sizeof(int));
    left.capacity = (chunkSize > dataSet->capacity) ? dataSet->capacity : chunkSize;
    left.length = chunkSize;

    memcpy(right.data, dataSet->data + chunkSize, (length - chunkSize) * sizeof(int));
    right.capacity = length - chunkSize;
    right.length = length - chunkSize;

    mergeSort(&left);
    mergeSort(&right);
    merge(dataSet, 0, chunkSize, length);
}

void addNumber(DataSet* dataSet, int number) {
    if (dataSet->capacity == dataSet->length) {
        // Handle data overflow here
    }

    dataSet->data[dataSet->length++] = number;
