```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/mman.h>
#include <time.h>
#include <pthread.h>
#include <sys/stat.h>
#include <fcntl.h>

typedef struct Record {
    int *key;
} Record;

long offsets = 0;
int *keys = NULL;
Record *records = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void read_file(const char *filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    struct stat st;
    fstat(fd, &st);
    long file_size = st.st_size;

    char *buffer = mmap(NULL, file_size + 1, PROT_READ, MAP_PRIVATE, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Error mapping file");
        exit(EXIT_FAILURE);
    }

    char *token = strtok(buffer, " \n\t");
    while (token != NULL) {
        offsets++;
        keys = realloc(keys, offsets * sizeof(int));
        keys[offsets - 1] = atoi(token);
        token = strtok(NULL, " \n\t");
    }

    munmap(buffer, file_size + 1);
    close(fd);
}

void init_record(int *random_range) {
    records = realloc(records, offsets * sizeof(Record));

    pthread_mutex_lock(&mutex);
    for (long i = 0; i < offsets; ++i) {
        records[i].key = malloc(sizeof(int));
        int key_exists = 0;
        for (long j = 0; j < i; ++j) {
            if (*records[i].key == *keys[j]) {
                key_exists = 1;
                break;
            }
        }
        if (!key_exists) {
            *records[i].key = rand() % (random_range[1] - random_range[0] + 1) + random_range[0];
            for (long j = 0; j < i; ++j) {
                if (*records[i].key == *keys[j]) {
                    perror("Race condition detected");
                    exit(EXIT_FAILURE);
                }
            }
        } else {
            --i;
        }
    }
    pthread_mutex_unlock(&mutex);
}

long manage_memory(const long offsets_size, const long keys_size, const int *random_range, const char *filename) {
    if (offsets_size <= 0 || keys_size <= 0 || random_range == NULL || filename == NULL) {
        perror("Invalid parameters");
        return -1;
    }

    offsets = 0;
    keys = NULL;
    records = NULL;

    read_file(filename);

    if (offsets == 0) {
        perror("No data found in the file");
        return -1;
    }

    keys = realloc(keys, offsets * sizeof(int));

    init_record(random_range);

    return offsets;
}
```

This implementation reads a file line by line and stores unique integers in the `keys` array. It also dynamically allocates an array of `Record` structures, each containing a pointer to an integer, and initializes these pointers with random values within the specified range. The code uses a mutex to prevent race conditions when multiple threads are accessing the same memory simultaneously.

The function `manage_memory()` handles memory management, file reading errors, and potential I/O bottlenecks. It returns the total number of records successfully initialized or -1 if any allocation fails.']

