char* get_directory_path(const char *filename) {
    size_t length = strlen(filename);
    char *directory_path = malloc(length);
    strncpy(directory_path, filename, length);
    for (size_t i = length; i > 0; --i) {
        if (filename[i - 1] == '/') {
            directory_path[i] = '\0';
            break;
        }
    }
    return directory_path;
}

char* get_extension(const char *filename) {
    size_t length = strlen(filename);
    for (size_t i = length; i > 0; --i) {
        if (filename[i] == '.') {
            return filename + i;
        }
    }
    return "";
}

void log_operation(const char *operation, const char *filename, bool logging_enabled) {
    if (logging_enabled) {
        printf("%s: %s\n", operation, filename);
    }
}

char* create_unique_filename(const char *original_filename, const char *extension, bool logging_enabled) {
    time_t now = time(NULL);
    char timestamp[10];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", localtime(&now));
    size_t extension_length = strlen(extension);
    size_t new_filename_length = strlen(original_filename) + strlen(extension) + strlen(timestamp) + 2;
    char *new_filename = malloc(new_filename_length);
    strncpy(new_filename, original_filename, strlen(original_filename));
    size_t dot_index = strlen(new_filename) - extension_length;
    strncpy(new_filename + dot_index, timestamp, strlen(timestamp));
    strcat(new_filename, extension);
    log_operation("Created unique filename", new_filename, logging_enabled);
    return new_filename;
}

void modify_file_metadata(const char *original_filename, const char *extension, bool logging_enabled) {
    char *directory_path = get_directory_path(original_filename);
    char *new_filename = create_unique_filename(original_filename, extension, logging_enabled);
    char full_new_filename[strlen(directory_path) + strlen(new_filename) + 2];
    strcat(full_new_filename, directory_path);
    strcat(full_new_filename, "/");
    strcat(full_new_filename, new_filename);

    struct stat st;
    if (stat(full_new_filename, &st) == -1) {
        perror("stat");
        exit(EXIT_FAILURE);
    }

    if (S_ISREG(st.st_mode)) {
        log_operation("File exists as a regular file", full_new_filename, logging_enabled);
        unlink(full_new_filename);
    } else if (S_ISDIR(st.st_mode)) {
        log_operation("File exists as a directory", full_new_filename, logging_enabled);
        char new_directory[strlen(directory_path) + strlen(timestamp) + 2];
        strcat(new_directory, directory_path);
        strcat(new_directory, "_");
        strcat(new_directory, timestamp);
        mkdir(new_directory, 0755);
        strcpy(full_new_filename, new_directory);
        strcat(full_new_filename, "/");
        strcat(full_new_filename, new_filename);
    } else {
        log_operation("File does not exist", full_new_filename, logging_enabled);
        return;
    }

    int fd = open(full_new_filename, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IXUSR);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }
