```cpp
#include <iostream>
#include <string>
#include <vector>
#include <filesystem>
#include <regex>
#include <cstdlib>
#include <new>

namespace fs = std::filesystem;

constexpr size_t MAX_PATH_LENGTH = 256;
constexpr char DOT_HIDDEN[] = ". ";
constexpr char RESERVED_NAMES[] = "CON PRN LPT COM";
constexpr char EXE_EXT[] = ".exe";
constexpr char LOG_EXT[] = ".log";
constexpr char CSV_EXT[] = ".csv";

std::string sanitize_path(const std::string& path) {
    if (path.size() > MAX_PATH_LENGTH) {
        throw std::runtime_error("Path exceeds the maximum length of 256 characters.");
    }

    std::regex invalid_path_regex{R"((?:\.\.|://))"};
    if (std::regex_search(path, invalid_path_regex)) {
        throw std::runtime_error("Invalid path detected: " + path);
    }

    std::string sanitized;
    for (char c : path) {
        if (c == ' ') {
            sanitized += '_';
        } else if (std::find(RESERVED_NAMES, RESERVED_NAMES + sizeof(RESERVED_NAMES), c) != std::end(RESERVED_NAMES)) {
            throw std::runtime_error("Reserved name detected: " + path);
        } else {
            sanitized += c;
        }
    }

    return sanitized;
}

std::string count_numeric_chars(const std::string& filename) {
    int count = 0;
    for (char c : filename) {
        if (isdigit(c)) {
            count++;
        }
    }
    return std::to_string(count);
}

std::string generate_new_filename(const std::string& original, const std::string& numeric_chars) {
    size_t dot_pos = original.find_last_of('.');
    std::string extension;
    if (dot_pos != std::string::npos) {
        extension = original.substr(dot_pos);
        if (extension == EXE_EXT) {
            extension = CSV_EXT;
        } else if (extension != LOG_EXT) {
            extension = LOG_EXT;
        }
    }

    std::string new_filename = original.substr(0, dot_pos);
    if (!new_filename.empty()) {
        new_filename += numeric_chars;
    }
    if (!extension.empty()) {
        new_filename += extension;
    }

    return new_filename;
}

void process_directory(const fs::path& directory) {
    for (const auto& entry : fs::recursive_directory_iterator{directory}) {
        if (entry.is_regular_file()) {
            std::string filename = entry.path().filename().string();
            filename = sanitize_path(filename);

            if (filename.find(DOT_HIDDEN) != 0) { // Exclude hidden files unless explicitly requested
                std::string numeric_chars = count_numeric_chars(filename);
                std::string new_extension = filename.empty() ? numeric_chars : filename.back() == '.' ? numeric_chars + numeric_chars : numeric_chars;
                std::string new_filename = generate_new_filename(filename, new_extension);

                fs::path new_path = entry.path().parent_path() / new_filename;
                if (new_path != entry.path()) {
                    try {
                        std::filesystem::rename(entry.path(), new_path);
                        std::cout << "Renamed: " << entry.path().string() << " -> " << new_path.string() << '\n';
                    } catch (const std::exception& e) {
                        std::cerr << "Error renaming file: " << e.what() << '\n';
                    }
                }
            }
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <directory>\n";
        return 1;
    }

    try {
        process_directory(fs::path{argv[1]});
    } catch (const std::exception& e) {
        std::cerr << "Error processing directory: " << e.what() << '\n';
        return 1;
    }

    return 0;
}
```

