#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <semaphore.h>
#include <pthread.h>

typedef struct {
    char *file_path;
    off_t file_size;
    void *mapped_file;
    int is_valid;
} FileData;

sem_t sem_mutex; // Semaphore for mutual exclusion
sem_t sem_files; // Semaphore to control access to files

void* process_file(void *data) {
    FileData *fd = (FileData *) data;
    int min = INT_MAX, max = INT_MIN;
    long sum = 0;

    if (fd->is_valid && fd->mapped_file != NULL) {
        char *ptr = (char *) fd->mapped_file;
        for (long i = 0; i < fd->file_size; i += sizeof(int)) {
            int num;
            memcpy(&num, ptr + i, sizeof(int));
            if (num >= 0) {
                sum += num;
                min = (min > num) ? num : min;
                max = (max < num) ? num : max;
            }
        }
    }

    sem_post(&sem_files); // Release file after processing

    free(fd->mapped_file);
    free(fd);
    return NULL;
}

int main() {
    FileData *files = malloc(NUM_FILES * sizeof(FileData));

    for (int i = 0; i < NUM_FILES; ++i) {
        files[i].file_path = calloc(MAX_PATH, sizeof(char));
        sprintf(files[i].file_path, "file%d.dat", i);

        int fd = open(files[i].file_path, O_RDONLY);
        struct stat st;
        fstat(fd, &st);
        files[i].file_size = st.st_size;

        if (fd >= 0) {
            files[i].mapped_file = mmap(NULL, files[i].file_size, PROT_READ, MAP_PRIVATE, fd, 0);
            close(fd);
            files[i].is_valid = (files[i].mapped_file != MAP_FAILED);
        } else {
            perror("Error opening file");
            free(files[i].file_path);
            continue;
        }
    }

    sem_init(&sem_mutex, 0, 1);
    sem_init(&sem_files, 0, NUM_FILES);

    pthread_t threads[NUM_FILES];

    for (int i = 0; i < NUM_FILES; ++i) {
        if (pthread_create(&threads[i], NULL, process_file, &files[i])) {
            perror("Error creating thread");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < NUM_FILES; ++i) {
        pthread_join(threads[i], NULL);
    }

    sem_destroy(&sem_mutex);
    sem_destroy(&sem_files);

    printf("Min: %d\n", min);
    printf("Max: %d\n", max);
    printf("Average: %.2f\n", (float) sum / NUM_FILES);

    for (int i = 0; i < NUM_FILES; ++i) {
        free(files[i].file_path);
    }
    free(files);

    return EXIT_SUCCESS;
}
```

This solution uses memory mapping to read the files into memory, allowing for efficient access. It also employs semaphores to manage concurrent access to both the shared data and the files themselves. The function `process_file()` handles potential I/O errors by checking if the file is valid before processing it. If an error occurs during file opening or mapping, the corresponding FileData structure is skipped.

The solution also supports multi-threading for concurrent file reading to improve performance. However, keep in mind that this pseudo-code does not include error handling for potential issues with thread creation and joining, which should be addressed in a production environment.']

