std::mutex mtx;
const int MAX_LINE_LENGTH = 1024;
const int BUFFER_GROWTH_FACTOR = 2;

struct FileData {
    std::ifstream file;
    size_t bufferSize = 0;
    char* buffer;
};

void processFile(FileData& data, bool sort) {
    // Read and process lines concurrently
    std::string line;
    while (std::getline(data.file, line)) {
        if (line.length() > MAX_LINE_LENGTH) {
            std::cerr << "Line too long: " << line << "\n";
            continue;
        }

        std::string lowerLine = std::move(line);
        std::transform(lowerLine.begin(), lowerLine.end(), lowerLine.begin(), ::tolower);
        lowerLine.erase(std::remove_if(lowerLine.begin(), lowerLine.end(), ::ispunct), lowerLine.end());

        mtx.lock();
        auto it = data.buffer ? std::find(data.buffer, data.buffer + data.bufferSize, '\n') : nullptr;
        if (it != nullptr) {
            *it = '\0';
            std::vector<std::string> lines{data.buffer, it};
            processLines(lines, sort);
            it = std::find(data.buffer, data.buffer + data.bufferSize, '\n');
            if (it != nullptr) {
                *it = '\n';
            } else {
                data.buffer[data.bufferSize] = '\n';
            }
        } else {
            data.bufferSize += line.length() + 1;
            char* newBuffer = new char[data.bufferSize];
            if (data.buffer) {
                std::copy(data.buffer, data.buffer + data.bufferSize, newBuffer);
                std::copy(line.c_str(), line.c_str() + line.length() + 1, newBuffer + data.bufferSize - (line.length() + 1));
            } else {
                std::copy(line.c_str(), line.c_str() + line.length() + 1, newBuffer);
            }
            delete[] data.buffer;
            data.buffer = newBuffer;
        }
        mtx.unlock();
    }
}

void processLines(const std::vector<std::string>& lines, bool sort) {
    if (sort) {
        std::set<std::string> sortedLines;
        for (const auto& line : lines) {
            sortedLines.insert(line);
        }
        for (auto it = sortedLines.begin(); it != sortedLines.end(); ++it) {
            std::cout << *it << "\n";
        }
    } else {
        for (const auto& line : lines) {
            std::cout << line << "\n";
        }
    }
}

void logError(const char* message, const char* logFile = "pipeline_errors.log") {
    FILE* file = fopen(logFile, "a");
    if (file) {
        fprintf(file, "%s\n", message);
        fclose(file);
    } else {
        std::cerr << "Error logging to file: " << strerror(errno) << "\n";
    }
}

int main(int argc, char* argv[]) {
    bool sort = false;
    std::string logFile = "pipeline_errors.log";

    for (int i = 1; i < argc; ++i) {
        if (argv[i][0] == '-' && argv[i][1] == 's') {
            sort = true;
        } else if (argv[i][0] == '-' && argv[i][1] == 'l') {
            if (++i < argc) {
                logFile = argv[i];
            }
        } else {
            std::ifstream file(argv[i]);
            if (!file.is_open()) {
                logError("Failed to open file: ", argv[i]);
                continue;
            }
            FileData data{std::move(file), 0, nullptr};
            std::thread t(&processFile, data, sort).detach();
        }
    }

    return 0;
}
```

