```java
import java.io.*;
import javax.crypto.*;
import java.security.*;
import java.security.spec.*;
import java.util.*;

public class CommandExecutor {
    private Cipher cipher;
    private KeyPair keyPair;
    private Signature signature;
    private KeyManagementSystem keyManagementSystem;
    private long startTime;
    private long endTime;
    private long executionTime;

    public CommandExecutor(KeyManagementSystem keyManagementSystem, int keySize) throws Exception {
        this.keyManagementSystem = keyManagementSystem;
        this.cipher = Cipher.getInstance("AES/" + KeyPropertyBeans.getKeySize(keySize));
        this.keyPair = keyManagementSystem.generateKeyPair();
        this.signature = Signature.getInstance("SHA256withECDSA");
    }

    public void executeCommand(String command) throws Exception {
        startTime = System.currentTimeMillis();
        Process process = Runtime.getRuntime().exec(command);
        InputStream inputStream = process.getInputStream();
        InputStreamReader inputStreamReader = new InputStreamReader(inputStream);
        BufferedReader bufferedReader = new BufferedReader(inputStreamReader);
        String line;
        StringBuilder output = new StringBuilder();
        while ((line = bufferedReader.readLine()) != null) {
            output.append(line).append("\n");
        }
        int exitValue = process.waitFor();
        endTime = System.currentTimeMillis();
        executionTime = endTime - startTime;

        if (exitValue == 0 && checkFileExistsAndDelete("target_file")) {
            System.out.println("Command executed successfully.");
        } else {
            throw new Exception("Command execution failed with exit value: " + exitValue);
        }
    }

    private boolean checkFileExistsAndDelete(String fileName) {
        File file = new File(fileName);
        return file.exists() && file.delete();
    }

    public Map<String, Object> getResult() {
        Map<String, Object> result = new HashMap<>();
        result.put("cipher", cipher.getAlgorithm());
        result.put("keyManagementSystem", keyManagementSystem);
        result.put("signatureAlgorithm", signature.getAlgorithm());
        result.put("executionTime", executionTime);
        return result;
    }
}
