import java.util.concurrent.ConcurrentHashMap;
import java.util.Properties;

public final class ConfigManager {
    private static final Map<String, AppConfig> CACHE = new ConcurrentHashMap<>();
    private static final long CACHE_EXPIRATION_MILLIS = 60 * 60 * 1000L; // 1 hour

    public static AppConfig getAppConfig(String filePath) {
        synchronized (CACHE) {
            AppConfig config = CACHE.get(filePath);
            if (config != null && System.currentTimeMillis() - config.lastAccessed < CACHE_EXPIRATION_MILLIS) {
                return config;
            }
        }

        try (InputStream inputStream = new FileInputStream(filePath)) {
            Properties properties = new Properties();
            properties.load(inputStream);
            AppConfig appConfig = new AppConfig(properties);

            synchronized (CACHE) {
                CACHE.putIfAbsent(filePath, appConfig);
                CACHE.replace(filePath, config != null ? config : appConfig);
                appConfig.lastAccessed = System.currentTimeMillis();
            }

            handleEnvironmentVariablesAndRemoteServices(appConfig);
            validateAppConfig(appConfig);
            return appConfig;
        } catch (IOException e) {
            throw new RuntimeException("Failed to load configuration from file: " + filePath, e);
        }
    }

