function authenticateAndResolveDNS($username, $password, $domain) {
    // Initialize session and access token variables
    if (!isset($_SESSION)) {
        session_start();
    }
    $accessToken = null;

    // Attempt OAuth 2.0 authentication
    try {
        $authenticator = new OAuthAuthenticator($username, $password);
        $accessToken = $authenticator->authenticate();
        $_SESSION['access_token'] = $accessToken;
    } catch (Exception $e) {
        // Log authentication failure and handle error appropriately
        logAuthenticationError($e->getMessage());
        return false;
    }

    // Retrieve user-specific domain information using the access token
    try {
        $domainInfo = DomainResolver::getDomainInfoByAccessToken($accessToken);
    } catch (Exception $e) {
        // Log error and handle error appropriately
        logError($e->getMessage());
        return false;
    }

    // Cache domain information for performance
    cacheDomainInfo($domainInfo);

    // Perform DNS resolution using the C-based module resolveDNS
    $dnsServers = getConfiguredDNSServers();
    $resolvedHostnames = [];

    foreach ($dnsServers as $server) {
        try {
            $resolvedHostname = resolveDNS($domainInfo['primary_ip'], $server);
            if (!empty($resolvedHostname)) {
                $resolvedHostnames[] = $resolvedHostname;
                break; // Exit the loop once a valid response is received
            }
        } catch (Exception $e) {
            // Log error and handle server unavailability appropriately
            logDNSServerError($server, $e->getMessage());
        }
    }

    // In case no valid response was received after trying all servers, use a fallback mechanism
    if (empty($resolvedHostnames)) {
        $fallbackHostname = getFallbackHostname();
        if (!empty($fallbackHostname)) {
            $resolvedHostnames[] = $fallbackHostname;
        }
    }

    // Return the resolved hostnames or an error message if necessary
    return $resolvedHostnames;
}
