[' Here's a C# function that meets your requirements:

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Security.Cryptography;
using System.Configuration;
using Newtonsoft.Json;

public string DecryptMessage(string base64EncodedMessage, string configFilePath, int timeoutMilliseconds)
{
    var decryptedMessage = string.Empty;
    var startTime = DateTime.Now;
    var fallbackConfigurations = LoadConfigurations(configFilePath);
    var currentConfigurationIndex = 0;

    CancellationTokenSource cancellationTokenSource = new CancellationTokenSource();
    CancellationToken token = cancellationTokenSource.Token;

    Action decryptAction = () =>
    {
        try
        {
            using (var tripledes = TripleDES.Create())
            {
                var base64DecodedBytes = Convert.FromBase64String(base64EncodedMessage);
                var iv = fallbackConfigurations[currentConfigurationIndex].IV;
                var key = fallbackConfigurations[currentConfigurationIndex].Key;

                using (var ms = new MemoryStream(base64DecodedBytes))
                {
                    using (var cs = new CryptoStream(ms, tripledes.CreateDecryptor(key, iv), CryptoStreamMode.Read))
                    {
                        var buffer = new byte[cs.ReadBufferSize];
                        int read;
                        while ((read = cs.Read(buffer, 0, buffer.Length)) > 0)
                        {
                            ms.Write(buffer, 0, read);
                        }
                    }
                }

                decryptedMessage = Encoding.UTF8.GetString(ms.ToArray());
            }
        }
        catch (Exception ex)
        {
            LogError($"Decryption attempt with configuration #{currentConfigurationIndex}: {ex.Message}");
        }
    };

    var cts = new CancellationTokenSource();
    var timeoutTask = Task.Run(async () => await Task.Delay(timeoutMilliseconds, token), cts.Token);

    try
    {
        decryptAction();

        while (!decryptedMessage.Any() && currentConfigurationIndex < fallbackConfigurations.Count - 1)
        {
            currentConfigurationIndex++;
            decryptAction();
        }
    }
    catch (OperationCanceledException)
    {
        LogError($"Decryption timed out after {(DateTime.Now - startTime).TotalMilliseconds}ms");
    }
    finally
    {
        cts.Cancel();
        timeoutTask.Wait();
    }

    return decryptedMessage;
}

private List<Configuration> LoadConfigurations(string configFilePath)
{
    var json = File.ReadAllText(configFilePath);
    return JsonConvert.DeserializeObject<List<Configuration>>(json);
}

private void LogError(string message)
{
