using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class FileHashResult
{
    public string Hash { get; set; }
    public string StatusMessage { get; set; }
}

public class ApiResponse
{
    [JsonProperty("username")]
    public string Username { get; set; }
    [JsonProperty("password")]
    public string Password { get; set; }
    [JsonProperty("status")]
    public string Status { get; set; }
}

public class FileValidationResult
{
    public Dictionary<string, FileHashResult> Files { get; set; }
    public List<Exception> Errors { get; set; }
}

private const int BufferSize = 4096;
private static readonly HttpClient _httpClient = new HttpClient();
private static readonly Dictionary<string, ApiResponse> _apiCache = new Dictionary<string, ApiResponse>();

public async Task<FileValidationResult> ProcessAndValidateFileContents(IEnumerable<string> filePaths)
{
    var results = new FileValidationResult { Files = new Dictionary<string, FileHashResult>(), Errors = new List<Exception>() };

    var tasks = filePaths.Select(ProcessFile).ToList();
    await Task.WhenAll(tasks);

    if (results.Errors.Any())
    {
        results.Files = null;
    }

    return results;

    async Task<FileHashResult> ProcessFile(string filePath)
    {
        try
        {
            using var fileStream = File.OpenRead(filePath);
            SHA256 sha256 = SHA256.Create();
            byte[] hash;

            using (MemoryStream ms = new MemoryStream())
            {
                int read;
                while ((read = await fileStream.ReadAsync(new byte[BufferSize])) > 0)
                {
                    ms.Write(read, 0, read);
                }

                hash = sha256.ComputeHash(ms.ToArray());
            }

            return new FileHashResult { Hash = BitConverter.ToString(hash).Replace("-", "").ToLower(), StatusMessage = "Success" };
        }
        catch (Exception ex)
        {
            results.Errors.Add(ex);
            return new FileHashResult { Hash = null, StatusMessage = $"Error processing file: {filePath}: {ex.Message}" };
        }
    }

    async Task<ApiResponse> GetApiCredentials()
    {
        string cacheKey = "username_password";

        if (_apiCache.TryGetValue(cacheKey, out var apiResponse))
            return apiResponse;

        try
        {
            HttpResponseMessage response = await _httpClient.GetAsync("https://your-external-api-url/credentials");
            response.EnsureSuccessStatusCode();
            string jsonResponse = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<ApiResponse>(jsonResponse);
        }
        catch (HttpRequestException ex)
        {
            // Handle HTTP errors like 404 etc.
            _apiCache[cacheKey] = new ApiResponse { Status = "API Error" };
            return _apiCache[cacheKey];
        }
        catch (Exception ex)
        {
            // Handle other non-HTTP errors
            _apiCache[cacheKey] = new ApiResponse { Status = "API Request Failure" };
            return _apiCache[cacheKey];
        }
    }

    async Task<FileHashResult> ValidateCredentials(string hash, string filePath)
    {
        var credentials = await GetApiCredentials();

        if (credentials.Status != "Success")
        {
            return new FileHashResult { Hash = null, StatusMessage = $"API Error: Unable to retrieve credentials." };
        }

        try
        {
            using var httpContent = new StringContent(hash, Encoding.UTF8, "application/json");
            HttpResponseMessage response = await _httpClient.PostAsync($"https://your-external-api-url/validate/{filePath}", httpContent);
            response.EnsureSuccessStatusCode();
            string jsonResponse = await response.Content.ReadAsStringAsync();
            var validationResult = JsonConvert.DeserializeObject<ApiResponse>(jsonResponse);

            if (validationResult.Status != "Success")
            {
                return new FileHashResult { Hash = null, StatusMessage = $"File Validation Error: {validationResult.Status}" };
            }

            return new FileHashResult { Hash = hash, StatusMessage = "Validation Success" };
        }
        catch (HttpRequestException ex)
        {
            // Handle HTTP errors like 404 etc.
            return new FileHashResult { Hash = null, StatusMessage = $"API Error: Unable to validate file." };
        }
        catch (Exception ex)
        {
            // Handle other non-HTTP errors
            return new FileHashResult { Hash = null, StatusMessage = $"API Request Failure: {ex.Message}" };
        }
    }
}
```

