        AddTransformation<T>("csv", reader => CsvReader.Create(reader, CultureInfo.InvariantCulture).GetRecords<T>());
        AddTransformation<byte[]>("binary", reader => reader.ReadToEnd());
    }

    public void AddTransformation<T>(string format, Func<StreamReader, IEnumerable<T>> transformation)
    {
        _transformations[format] = transformation;
    }

    public async Task ProcessAsync(Stream input, Stream output, string format, CancellationToken cancellationToken)
    {
        if (!_transformations.ContainsKey(format))
            throw new ArgumentException($"Invalid data format: {format}");

        using var reader = new StreamReader(input);
        _currentInput = reader;

        try
        {
            _currentOutput = _transformations[format](reader).GetEnumerator();

            while (_currentOutput.MoveNext() && !cancellationToken.IsCancellationRequested)
            {
                var item = _currentOutput.Current;
                await WriteToStreamAsync(output, item);
            }
        }
        catch (Exception ex)
        {
            // Handle exceptions and dispose resources appropriately
        }
        finally
        {
            if (_currentInput != null)
