    public string Name { get; set; }
    // Add other properties as needed
}

public class FileHandler
{
    private readonly string _compressionFormat;
    private readonly Type _dataStructureType;

    public FileHandler(string compressionFormat, Type dataStructureType)
    {
        _compressionFormat = compressionFormat;
        _dataStructureType = dataStructureType;
    }

    public MyDataStructure[] LoadAndVerify(string filePath)
    {
        using (FileStream fs = File.OpenRead(filePath))
        {
            if (_compressionFormat == "lzma")
            {
                using (var input = new LZMAInputStream(fs, CompressionMode.Decompress))
                {
                    var buffer = new byte[input.Length];
                    input.Read(buffer, 0, buffer.Length);
                    return Deserialize(buffer);
                }
            }
            else
            {
                throw new NotSupportedException($"Unsupported compression format: {_compressionFormat}");
            }
        }

        byte[] checksum;
        using (var bf = new BinaryFormatter())
        {
            using (MemoryStream ms = new MemoryStream(fs.ReadAllBytes()))
            {
                checksum = CalculateChecksum(ms);
            }
        }

        using (FileStream fs = File.OpenRead(filePath))
        {
            byte[] fileChecksum;
            using (var bf = new BinaryFormatter())
            {
                fileChecksum = (byte[])bf.Deserialize(fs);
            }

            if (!checksum.SequenceEqual(fileChecksum))
            {
                throw new Exception("Data integrity check failed.");
            }
        }

        return Deserialize(File.ReadAllBytes(filePath));
    }

    private byte[] CalculateChecksum(Stream stream)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            return sha256.ComputeHash(stream);
        }
    }

    private MyDataStructure[] Deserialize(byte[] data)
    {
        using (var ms = new MemoryStream(data))
        {
            var bf = new BinaryFormatter();
            return (MyDataStructure[])bf.Deserialize(ms);
        }
    }
}
