2. Node.js Script (Filtering, Compression, and Storage)

```javascript
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const AWS = require('aws-sdk');
const readline = require('readline');

// Configure S3 storage
const s3 = new AWS.S3({ region: 'us-west-2' });
const bucketName = 'my-bucket';
const prefix = 'processed/';

function processFile(filePath) {
  const fileStream = fs.createReadStream(filePath);
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

  const filteredLines = [];
  rl.on('line', (line) => {
    if (!line.includes('keyword')) {
      filteredLines.push(line);
    }
  });

  rl.on('close', () => {
    const compressedContent = zlib.gzipSync(Buffer.concat(filteredLines));

    // Upload to S3
    const params = {
      Bucket: bucketName,
      Key: `${prefix}${path.basename(filePath)}`,
      Body: compressedContent,
      ContentType: 'application/gzip',
      ACL: 'public-read'
    };

    s3.upload(params, (err, data) => {
      if (err) {
        console.error(`Error uploading to S3: ${err}`);
      } else {
        console.log(`Successfully uploaded to S3: ${data.Location}`);
      }
    });
  });
}
```

This solution uses the SevenZip library for .NET to handle LZMA compression, Newtonsoft.Json for serialization/deserialization, and AWS SDK for Node.js to store processed files in S3. Both functions are designed with modularity, error handling, and logging in mind, making them easy to test, debug, and transition to production environments.']

