    fn new(tasks: HashMap<String, Box<dyn plugins::PluginTask>>, health_check_interval: Duration) -> Self {
        AppConfig { tasks, health_check_interval }
    }
}

struct AppState {
    tasks: Vec<JoinHandle<Result<(), Box<dyn std::error::Error>>>>,
    config: Arc<AppConfig>,
}

impl AppState {
    async fn run(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        let mut handles = Vec::new();

        for task in &self.config.tasks {
            let task_name = task.0.clone();
            let task = task.1;
            let config = self.config.clone();
            let handle = tokio::spawn(async move {
                info!("Starting task: {}", task_name);
                task.run().await?;
                info!("Task {} completed", task_name);
                Ok::<(), Box<dyn std::error::Error>>(())
            });
            handles.push(handle);
        }

        // Run health checks in a separate task
        let check_interval = interval(self.config.health_check_interval);
        let app_state = self.clone();
        tokio::spawn(async move {
            loop {
                check_interval.tick().await;
                app_state.check_tasks().await;
            }
        });

        // Wait for all tasks to complete
        let results: Vec<Result<(), Box<dyn std::error::Error>>> = futures::future::join_all(handles).await;

        if results.iter().any(|result| result.is_err()) {
            error!("Encountered errors during task execution");
        }

        Ok::<(), Box<dyn std::error::Error>>(())
    }

    async fn check_tasks(&self) {
        // Implement health checks here
    }
}

fn main() {
    // Initialize logging
    // ...

    let tasks = HashMap::from([
        ("task1".to_string(), Box::new(core_tasks::task1)),
        // Add more tasks here
    ]);

    let config = AppConfig::new(tasks, Duration::from_secs(60));
    let state = Arc::new(AppState { tasks: vec![], config });

