[" Due to the complexity of the task, I will provide a high-level design and an outline for the C function, along with some key data structures and functions. Implementing this solution would require extensive coding and testing, which is beyond the scope of this platform.

1. Define the `item` structure:

```c
typedef struct {
    char *name;
    int quantity;
} item;
```

2. Define a hash table structure with linked lists for collision handling:

```c
typedef struct hash_table {
    unsigned long size;
    unsigned long count;
    item **items;
} hash_table;
```

3. Implement a function to initialize the hash table:

```c
hash_table *init_hash_table(unsigned long size) {
    // Allocate memory for the hash table and its items array
    hash_table *ht = malloc(sizeof(hash_table));
    ht->size = size;
    ht->count = 0;
    ht->items = calloc(size, sizeof(item*));
    return ht;
}
```

4. Implement a function to calculate the hash index for a given key:

```c
unsigned long hash_function(const char *key, unsigned long size) {
    unsigned long hash = 5381;
    for (int i = 0; key[i]; ++i)
        hash = ((hash << 5) + hash) + key[i]; /* hash * 33 + c */
    return hash % size;
}
```

5. Implement functions to add and retrieve items from the hash table:

```c
item *find_item(const char *name, hash_table *ht) {
    // Calculate the hash index for the given name
    unsigned long index = hash_function(name, ht->size);

    // Iterate through the linked list at the calculated index
    item *current = ht->items[index];
    while (current != NULL) {
        if (strcmp(current->name, name) == 0)
            return current;
        current = current->next;
    }

    // If not found, return NULL
    return NULL;
}

void add_item(const char *name, int quantity, hash_table *ht) {
    // Find the item with the given name or create a new one if it doesn't exist
    item *existing = find_item(name, ht);

    // If the item already exists, update its quantity and return
    if (existing != NULL) {
        existing->quantity += quantity;
        return;
    }

    // Allocate memory for a new item and add it to the hash table
    item *new_item = malloc(sizeof(item));
    new_item->name = strdup(name);
    new_item->quantity = quantity;

    unsigned long index = hash_function(name, ht->size);
    new_item->next = ht->items[index];
    ht->items[index] = new_item;
    ht->count++;
}
```

6. Implement a linked list structure and functions for managing the collection of items:

```c
typedef struct item_list {
    item *head;
    int total_quantity;
    int capacity;
