    private readonly List<string> _trustedOrigins;
    private readonly IContentRepository _contentRepository;

    public RequestHandler(IDatabase redisDb, IContentRepository contentRepository)
    {
        _redisDb = redisDb;
        _contentRepository = contentRepository;
        LoadTrustedOrigins();
    }

    private void LoadTrustedOrigins()
    {
