        _trustedOrigins = JsonConvert.DeserializeObject<List<string>>(json);
    }

    public async Task HandleAsync(HttpContext context)
    {
        if (!IsTrustedOrigin(context.Request.Headers["Origin"]))
        {
            context.Response.StatusCode = (int)HttpStatusCode.InternalServerError;
            return;
        }

        var sectionId = context.Request.Query["section"];
        var elementId = context.Request.Query["element"];
        var content = await ReadContentAsync(context);

        if (!await UpdateContentInRepositoryAsync(sectionId, elementId, content))
        {
            context.Response.StatusCode = (int)HttpStatusCode.InternalServerError;
            return;
        }

        await CacheAndPropagateContentAsync(sectionId, elementId, content);
        LogRequestDetails(context);
    }

    private bool IsTrustedOrigin(string origin)
    {
        return _trustedOrigins.Contains(origin);
    }

    private async Task<string> ReadContentAsync(HttpContext context)
    {
        // Read content from request body
        await context.Request.Body.CopyToAsync(new MemoryStream());
        var content = await new StreamReader(context.Request.Body).ReadToEndAsync();
        context.Request.EnableBuffering();
        return content;
    }

