        allocated_sizes[i] = *array_sizes[i] * sizeof(union U);
    }

    union U {
        long long int64;
        int int32;
        Record record;
    };

    void *memory_block = malloc(total_memory);
    if (!memory_block) {
        log_error("Error: Memory allocation failed.");
        return -1;
    }

    for (size_t i = 0; i < 3; ++i) {
        char *current_ptr = memory_block;
        current_ptr += i * allocated_sizes[i];
        *array_sizes[i] = allocated_sizes[i] / sizeof(union U);
        array_sizes[i] = (size_t *)current_ptr;
    }

    srand(time(NULL));
    return *array_sizes[0];
}

void init_data(size_t size, union U *array) {
    for (size_t i = 0; i < size; ++i) {
        array[i].record.offset = rand() % 100000000;
        array[i].record.key = rand() % 101 - 50;
    }
}

void copy_keys(size_t size, int *keys, union U *records) {
    for (size_t i = 0; i < size; ++i) {
        records[i].int32 = keys[i];
    }
}

int main() {
    size_t array_sizes[3] = {100, 500, 200};
    size_t allocated_sizes[3];
    int init_result = init_memory(array_sizes, allocated_sizes, 1024 * 1024);

    if (init_result == -1) {
        return 1;
    }

    long *long_arr = (long *)array_sizes[0];
    int keys_arr[500];
    Record records[100];

    init_data(init_result, (union U *)long_arr);
    memcpy(keys_arr, (int *)long_arr + 1, sizeof(int) * init_result);

    copy_keys(init_result, keys_arr, (union U *)records);

    // Use the initialized data structures here...

    free((void *)array_sizes[0]);
    free((void *)array_sizes[1]);
    free((void *)array_sizes[2]);

    return 0;
}
```

This code defines a `Record` structure, a log_error function to write errors to a file, and an init_memory function that handles memory allocation and initialization. The main function demonstrates how to use the functions for initializing and copying data structures. It also takes care of memory deallocation at the end.']

