3. Implement a thread-safe dynamic array:

```cpp
class DynamicArray {
public:
    DynamicArray(size_t initialSize) : data_(std::make_unique<NFAPI_CRC_INDICATION_PDU_T[]>(initialSize)), capacity_(initialSize), size_(0) {}

    ~DynamicArray() = default;

    void resize(size_t newSize) {
        if (newSize > capacity_) {
            auto newData = std::make_unique<NFAPI_CRC_INDICATION_PDU_T[]>(newSize);
            std::copy_n(*data_, size_, newData.get());
            data_.swap(newData);
            capacity_ = newSize;
        }
    }

    void push_back(const NFAPI_CRC_INDICATION_PDU_T& pdu) {
        if (size_ == capacity_) resize(capacity_ * 2);
        data_[size_++] = pdu;
    }

private:
    std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T[]> data_;
    size_t capacity_;
    size_t size_;
};
```

4. Implement a thread-safe pseudo-random number generator:

```cpp
class PRNG {
public:
    explicit PRNG(uint32_t seed) : mt_(seed), gen_(mt_) {}

    uint32_t next() {
        std::uniform_int_distribution<> distr(0, UINT16_MAX);
        return distr(mt_);
    }

private:
    std::mt19937 mt_;
    std::uniform_int_distribution<> gen_;
};
```

5. Implement the main function that initializes and manages the array in a multi-threaded environment:

```cpp
void initCRCIndications(DynamicArray& array, size_t N, const PRNG& prng) {
    std::vector<std::unique_ptr<RX_UE_INFORMATION_TAG_SOURCE>> dataSources;
    // Initialize data sources for RX_UE_INFORMATION_TAG and RNTI values

    std::mutex mtx;
    std::condition_variable cv;
    std::queue<NFAPI_CRC_INDICATION_PDU_T> readyQueue;

    auto producer = [&](size_t startIndex) {
        for (size_t i = startIndex; i < N; ++i) {
            NFAPI_CRC_INDICATION_PDU_T pdu;
            pdu.RX_UE_INFORMATION_TAG = dataSources[0]->getTag();
            pdu.RNTI = dataSources[1]->getRNTI();
            pdu.CRC_INDICATION_REL8_TAG = i;
            pdu.CRCFLAG = prng.next() % 2 == 0;
            std::unique_lock<std::mutex> lock(mtx);
            readyQueue.push(pdu);
            lock.unlock();
            cv.notify_one();
        }
    };

    auto consumer = [&]() {
        for (auto& pdu : array) {} // Empty loop to ensure the consumer runs

        while (true) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this] { return !readyQueue.empty(); });
            auto pdu = readyQueue.front();
            readyQueue.pop();
            lock.unlock();
            array.push_back(pdu);
        }
    };

    dataSources.emplace_back(std::make_unique<RX_UE_INFORMATION_TAG_SOURCE>());
    dataSources.emplace_back(std::make_unique<RNTI_SOURCE>());

    std::vector<std::thread> threads;
    for (size_t i = 0; i < std::thread::hardware_concurrency(); ++i) {
        threads.emplace_back(producer, i * N / threads.size());
    }
    threads.emplace_back(consumer);
}
