// Custom allocator for records to minimize reallocations and improve performance
template<typename T, std::size_t N>
class RecordAllocator : public std::allocator<T[N]> {
public:
    using value_type = T[N];
    using pointer = T*;
    using const_pointer = const T*;
    using reference = T&;
    using const_reference = const T&;
    using size_type = std::size_t;
    using difference_type = std::ptrdiff_t;

    RecordAllocator() noexcept {}

    template<typename U>
    struct rebind {
        using other = RecordAllocator<U, N>;
    };

    pointer allocate(std::size_type n) {
        auto* ptr = static_cast<T*>(std::allocate(n * N));
        std::fill_n(ptr, n * N, 0); // Initialize records with random values within a specified range
        return ptr;
    }

    void deallocate(pointer p, std::size_type) {
        std::free(p);
    }
};

// Custom allocator for forward lists to minimize reallocations and improve performance
template<typename T>
class ForwardListAllocator : public std::allocator<std::list<T>> {
public:
    using value_type = std::list<T>;
    using pointer = std::list<T>*;
    using const_pointer = const std::list<T>*;
    using reference = std::list<T>&;
    using const_reference = const std::list<T>&;
    using size_type = std::size_t;
    using difference_type = std::ptrdiff_t;

    ForwardListAllocator() noexcept {}

    template<typename U>
    struct rebind {
        using other = ForwardListAllocator<U>;
    };

    pointer allocate(std::size_type n) {
        auto* ptr = static_cast<std::list<T>*>(std::allocate(n * sizeof(std::list<T>)));
        std::fill_n(ptr, n, std::list<T>()); // Initialize forward lists
        return ptr;
    }

    void deallocate(pointer p, std::size_type) {
        std::free(p);
    }
};

// Function to manage memory allocation and initialization for multiple data structures
void manageMemory(std::vector<long> offsets, std::vector<int> keys, std::list<Record<int>> records, std::list<std::string> forwardList, const std::string& insertionPoint, const std::string& newString) {
    // Custom allocators for records and forward lists
    using RecordAlloc = RecordAllocator<Record<int>, sizeof(Record<int>)>;
    using ForwardListAlloc = ForwardListAllocator<std::string>;

    // Allocate memory for records with random values within a specified range
    RecordAlloc recordAlloc;
    auto recordsMemory = recordAlloc.allocate(keys.size());
    try {
        std::fill_n(recordsMemory, keys.size(), Record<int>{});
        Record<int>* currentRecord = new (recordsMemory) Record<int>[keys.size()];
        for (size_t i = 0; i < keys.size(); ++i) {
            currentRecord[i].value = std::rand() % 100; // Initialize records with random values within a specified range
            new (static_cast<void*>(currentRecord + i)) Record<int>(currentRecord[i].value); // Construct records in-place
        }
        records.assign(recordsMemory, recordsMemory + keys.size());
    } catch (std::bad_alloc& e) {
        std::cerr << "Error allocating memory: " << e.what() << '\n';
        for (auto* record : recordsMemory) delete record;
        std::free(recordsMemory);
        throw;
    }

    // Allocate memory for forward list and handle insertion point
    ForwardListAlloc forwardListAlloc;
    auto forwardListMemory = forwardListAlloc.allocate(1);
    try {
        std::list<std::string>* currentForwardList = new (forwardListMemory) std::list<std::string>();
        for (const auto& str : forwardList) {
            currentForwardList->push_back(str);
        }

        auto it = std::search(currentForwardList->begin(), currentForwardList->end(), insertionPoint.begin(), insertionPoint.end());
        if (it != currentForwardList->end()) {
            currentForwardList->insert(it, newString);
        } else {
            currentForwardList->push_back(newString);
        }
        forwardList = *currentForwardList;
    } catch (std::bad_alloc& e) {
        std::cerr << "Error allocating memory: " << e.what() << '\n';
        for (auto* list : forwardListMemory) delete list;
        std::free(forwardListMemory);
        throw;
    }
}
```

