};

std::unordered_map<std::string, Sensor*> sensorMap;
std::mutex sensorsMutex;

void generateSensorData(const std::string& id, double mean) {
    std::normal_distribution<float> distribution(mean, 0.5f); // Gaussian distribution with mean and standard deviation of 0.5
    Sensor* sensor = new Sensor{id, std::chrono::system_clock::now().time_since_epoch().count(), distribution(generator)};
    std::unique_lock<std::mutex> lock(sensorsMutex);
    sensorMap[id] = sensor;
    lock.unlock();
}

void processSensorData() {
    for (auto& pair : sensorMap) {
        Sensor* sensor = pair.second;
        // Process the sensor data here
    }
}

void cleanup() {
    std::unique_lock<std::mutex> lock(sensorsMutex);
    for (auto it = sensorMap.begin(); it != sensorMap.end(); ) {
        auto sensor = it->second;
        it = sensorMap.erase(it);
        delete sensor;
    }
}

void manageSensorData(int numThreads, double mean) {
    std::random_device rd;
    std::mt19937 generator(rd());

    std::vector<std::thread> threads;
    for (int i = 0; i < numThreads; ++i) {
        threads.emplace_back(&generateSensorData, std::to_string(i), mean);
    }

    for (auto& thread : threads) {
        thread.join();
    }

    processSensorData();
    cleanup();
}
