typedef struct Record {
    int *value;
    struct Record *left, *right;
} Record;

Record* create_node(int key) {
    Record *new_node = (Record *)malloc(sizeof(Record));
    if (!new_node) return NULL;
    new_node->value = malloc(sizeof(int));
    if (!new_node->value) {
        free(new_node);
        return NULL;
    }
    *new_node->value = key;
    new_node->left = new_node->right = NULL;
    return new_node;
}

void insert(Record **root, int key) {
    if (*root == NULL) {
        *root = create_node(key);
        return;
    }

    if (key < (*root)->value[0]) {
        insert(&(*root)->left, key);
    } else if (key > (*root)->value[0]) {
        insert(&(*root)->right, key);
    }
}

int find_median(Record *root) {
    if (!root || !root->left && !root->right) return root->value[0];

    Record *temp = root->left;
    while (temp->right) temp = temp->right;
    return temp->value[0];
}

int search(Record *root, int key) {
    if (!root) return -1;

    if (key < root->value[0]) return search(root->left, key);
    else if (key > root->value[0]) return search(root->right, key);
    else return root->value[0];
}

void in_order_traversal(Record *root) {
    if (!root) return;

    in_order_traversal(root->left);
    printf("%d ", root->value[0]);
    in_order_traversal(root->right);
}

long *offsets = NULL;
int *keys = NULL;
Record **bst = NULL;

int init(size_t offset_count, size_t key_count, int min_val, int max_val, bool use_bst) {
    if (offset_count > LONG_MAX / sizeof(long)) return -1;

    offsets = malloc(offset_count * sizeof(long));
    if (!offsets) goto error;
    for (size_t i = 0; i < offset_count; ++i) offsets[i] = i;

    keys = malloc(key_count * sizeof(int));
    if (!keys) goto error;

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < key_count; ++i) {
        int input = fgetc(stdin);
        if (input == EOF || input < min_val || input > max_val) {
            fprintf(stderr, "Invalid input: %d. Expected value between %d and %d.\n", input, min_val, max_val);
            goto error;
        }
        keys[i] = input;
    }

    if (use_bst) {
        bst = malloc(key_count * sizeof(Record*));
        if (!bst) goto error;
        for (size_t i = 0; i < key_count; ++i) insert(bst + i, keys[i]);
    }

    int *values = malloc(key_count * sizeof(int));
    if (!values) goto error;
    for (size_t i = 0; i < key_count; ++i) {
        int random_val = rand() % (max_val - min_val + 1) + min_val;
        while (1) {
            int found = 0;
            for (size_t j = 0; j < i; ++j) {
                if (values[j] == random_val) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                values[i] = random_val;
                break;
            }
            random_val = rand() % (max_val - min_val + 1) + min_val;
        }
    }

    for (size_t i = 0; i < key_count; ++i) {
        ((Record *)values[i])->value = values[i];
        if (use_bst) insert(bst[i], keys[i]);
    }

    return key_count;

error:
    free(offsets);
    free(keys);
    for (size_t i = 0; i < key_count; ++i) free(values[i]);
    free(values);
    if (bst) free(bst);
    return -1;
}
