```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <stdexcept>
#include <memory>
#include <cstdlib>

struct Record {
    long offset;
    int key;
    int value;
};

class RecordManager {
private:
    std::unordered_map<int, size_t> keysToIndices;
    std::vector<Record> records;
    std::mutex mtx;

public:
    RecordManager() = default;

    ~RecordManager() {
        clear();
    }

    void insert(const Record& record) {
        std::unique_lock<std::mutex> lock(mtx);

        if (keysToIndices.find(record.key) != keysToIndices.end()) {
            update(record.key, record);
        } else {
            records.push_back(record);
            keysToIndices[record.key] = records.size() - 1;
        }
    }

    Record get(int key) const {
        std::unique_lock<std::mutex> lock(mtx);

        auto it = keysToIndices.find(key);
        if (it == keysToIndices.end()) {
            throw std::out_of_range("Key not found");
        }

        return records[it->second];
    }

    void update(int key, const Record& newRecord) {
        std::unique_lock<std::mutex> lock(mtx);

        auto it = keysToIndices.find(key);
        if (it == keysToIndices.end()) {
            throw std::out_of_range("Key not found");
        }

        records[it->second] = newRecord;
    }

    void sort() {
        std::sort(records.begin(), records.end(), [](const Record& a, const Record& b) {
            return a.key < b.key;
        });
    }

    void clear() {
        keysToIndices.clear();
        records.clear();
    }
};
```

