        int vertices;
        fscanf(file, "%d", &vertices);
        total_vertices += vertices;
    }
    rewind(file);

    *num_shapes = (total_vertices + (*num_shapes - 1) * avg_vertices_per_shape) / avg_vertices_per_shape;
    if (*num_shapes > UINT64_MAX / sizeof(double)) {
        fprintf(stderr, "Integer overflow detected. Please reduce the average vertex count per shape.\n");
        exit(1);
    }
}

Shape* allocate_shapes(uint64_t num_shapes) {
