    if (!colors) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
    srand(hash(file)); // Replace 'file' with the actual file pointer or a suitable seed source
    for (uint64_t i = 0; i < num_shapes; ++i) {
        colors[i].r = brightness + rand() % (255 - 2 * brightness);
        colors[i].g = brightness + rand() % (255 - 2 * brightness);
        colors[i].b = brightness + rand() % (256 - 3 * brightness);
    }
    return colors;
}

uint32_t hash(FILE* file) {
    uint32_t hash = 5381;
    int c;
    while ((c = fgetc(file)) != EOF) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash;
}
