#include <iostream>
#include <vector>
#include <unordered_map>
#include <random>
#include <cstdlib>
#include <new>
#include <atomic>
#include <mutex>

const int MAX_MEMORY = 1000000; // Maximum memory limit (in bytes)

struct Record {
    int value;
    int* key;
};

class MemoryManager {
public:
    MemoryManager(int offsetSize, int recordSize) :
        offsets_(offsetSize), keys_(offsetSize), records_(recordSize),
        memoryUsed_(0), maxMemory_(MAX_MEMORY) {}

    Record* allocateRecord() {
        if (memoryUsed_ + sizeof(Record) > maxMemory_) {
            std::cerr << "Out of memory!" << std::endl;
            return nullptr;
        }

        auto it = keys_.end();
        for (auto i = keys_.begin(); i != keys_.end(); ++i) {
            if (!*i) {
                it = i;
                break;
            }
        }

        if (it == keys_.end()) {
            resizeKeys(keys_, offsets_.size() * 2);
            it = keys_.end();
            for (auto i = keys_.begin(); i != keys_.end(); ++i) {
                if (!*i) {
                    it = i;
                    break;
                }
            }
        }

        *it = static_cast<int>(offsets_.size());
        offsets_.push_back(0);
        memoryUsed_ += sizeof(Record);
        return &records_[offsets_.size() - 1];
    }

    void setValue(Record* record, int value) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, MAX_MEMORY / sizeof(int) - 1);

        while (true) {
            int key = dis(gen);
            if (find(keys_[key]) == keys_[key].end()) {
                record->value = value;
                record->key = &keys_[key];
                keys_[key] = record;
                break;
            }
        }
    }

    Record* findRecord(int offset) const {
        auto it = keys_.find(offset);
        if (it == keys_.end()) return nullptr;
        return it->second;
    }

private:
    void resizeKeys(std::vector<int>& vec, size_t newSize) {
        std::vector<int> temp(newSize);
        std::copy(vec.begin(), vec.end(), temp.begin());
        vec.resize(newSize);
        vec.swap(temp);
    }

    std::vector<int> offsets_;
    std::unordered_map<int, Record*> keys_;
    std::vector<Record> records_;
    size_t memoryUsed_;
    size_t maxMemory_;
};
```

