        perror("Failed to open file.");
        exit(EXIT_FAILURE);
    }

    fseek(file, 0, SEEK_END);
    long filesize = ftell(file);
    rewind(file);

    long *offsets = calloc(filesize / sizeof(long), sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        exit(EXIT_FAILURE);
    }

    size_t bytes_read = fread(offsets, sizeof(long), filesize / sizeof(long), file);
    if (bytes_read != filesize / sizeof(long)) {
        perror("Failed to read file.");
        exit(EXIT_FAILURE);
    }

    return offsets;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <offsets_file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    long *offsets = read_offsets(argv[1]);
    int *keys = create_keys(1024);
    record *records = create_records(1024);

    // Use the offsets, keys, and records arrays here...

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
```

This code reads the `offsets` file into memory efficiently by using `calloc()`, which initializes all allocated memory to zero. The prime number generation function checks for primality using trial division up to the square root of the number, and the random number generator uses a seed based on the current time. The main function demonstrates how to use these functions to read an offsets file, generate keys, and create records.']

