const int MAX_RECORDS = 1000000;
const int KEY_RANGE = 1000000;
const int OFFSET_ALIGNMENT = 64;
const int RECORD_SIZE = sizeof(int);

std::forward_list<std::string> dataList;
std::vector<long> offsets;
std::vector<int> keys;
std::vector<int> records;
std::mutex mtx;

void allocateMemory() {
    if (offsets.size() + records.size() > MAX_RECORDS) {
        // Handle memory allocation overflow
    }

    long offset = 0;
    for (auto it = dataList.begin(); it != dataList.end(); ++it) {
        while (offset + RECORD_SIZE * records.size() > OFFSET_ALIGNMENT * ((offset + OFFSET_ALIGNMENT - 1) / OFFSET_ALIGNMENT)) {
            offset += OFFSET_ALIGNMENT;
        }

        offsets.push_back(offset);
        keys.push_back(-1); // Initialize as unoccupied
    }
}

void manipulateData() {
    srand(time(0));
    allocateMemory();

    int recordIndex = 0;
    for (auto it = dataList.begin(); it != dataList.end(); ++it) {
        mtx.lock();
        while (keys[recordIndex] != -1) {
            // Handle duplicate key collision resolution
            ++recordIndex;
        }
        keys[recordIndex] = std::stoi(*it);
        records[recordIndex] = rand() % KEY_RANGE;
        mtx.unlock();
        ++recordIndex;
    }
}

void serializeData(const std::string& filename) {
    std::ofstream file(filename, std::ios::binary | std::ios::trunc);
    if (file.is_open()) {
        file.write((char*)&offsets[0], offsets.size() * sizeof(long));
        file.write((char*)&keys[0], keys.size() * sizeof(int));
        file.write((char*)&records[0], records.size() * RECORD_SIZE);
        file.close();
    }
}

void deserializeData(const std::string& filename) {
    std::ifstream file(filename, std::ios::binary);
    if (file.is_open()) {
        file.read((char*)&offsets[0], offsets.size() * sizeof(long));
        file.read((char*)&keys[0], keys.size() * sizeof(int));
        file.read((char*)&records[0], records.size() * RECORD_SIZE);
        file.close();
    }
}

void insertString(const std::string& str, const std::string& newStr) {
    auto it = dataList.begin();
    if (it == dataList.end() || *(it++) != str) {
        dataList.push_back(str);
    }
    mtx.lock();
    dataList.insertAfter(it, newStr);
    mtx.unlock();
}

