```java
import java.util.*;
import java.time.*;
import java.math.*;

class Order {
    // ... (order properties)
}

interface InventoryManagementSystem {
    BigDecimal getPrice(String productId, Locale locale);
    int getStockLevel(String productId);
    double getTaxRate(Locale locale);
}

class Cache<K, V> {
    // ... (cache implementation)
}

class InvoiceSummary {
    private Order order;
    private BigDecimal totalPrice;
    private boolean isValid;

    // constructors, getters and setters
}

public class InvoiceGenerator {
    private final InventoryManagementSystem inventory;
    private final Cache<String, Map<Locale, InvoiceSummary>> cache;
    private final PaymentGatewayApi paymentGateway;
    private final int maxRetries;
    private final Duration retryInterval;

    public InvoiceGenerator(InventoryManagementSystem inventory, Cache<String, Map<Locale, InvoiceSummary>> cache, PaymentGatewayApi paymentGateway, int maxRetries, Duration retryInterval) {
        this.inventory = inventory;
        this.cache = cache;
        this.paymentGateway = paymentGateway;
        this.maxRetries = maxRetries;
        this.retryInterval = retryInterval;
    }

    public InvoiceSummary generateInvoiceSummary(Order order, Locale locale) {
        String orderId = order.getId();
        Map<Locale, InvoiceSummary> cachedInvoices = cache.get(orderId);

        if (cachedInvoices != null && cachedInvoices.containsKey(locale)) {
            return cachedInvoices.get(locale);
        }

        InvoiceSummary invoiceSummary = new InvoiceSummary();
        invoiceSummary.setOrder(order);

        try {
            BigDecimal totalPrice = BigDecimal.ZERO;
            for (OrderItem item : order.getItems()) {
                String productId = item.getProductId();
                BigDecimal price = inventory.getPrice(productId, locale);
                if (price == null) {
                    invoiceSummary.setValid(false);
                    break;
                }
                totalPrice = totalPrice.add(item.getQuantity().multiply(price));
            }

            if (invoiceSummary.isValid()) {
                double taxRate = inventory.getTaxRate(locale);
                BigDecimal subtotal = totalPrice;
                BigDecimal taxAmount = subtotal.multiply(new BigDecimal(String.valueOf(taxRate)));
                BigDecimal totalWithTax = subtotal.add(taxAmount);

                invoiceSummary.setTotalPrice(totalWithTax);
            }
        } catch (Exception e) {
            // handle exceptions, log errors and set invoiceSummary.isValid(false)
        }

        if (invoiceSummary.isValid()) {
            BigDecimal transactionAmount = invoiceSummary.getTotalPrice();
            boolean validated = paymentGateway.validateTransactionAmount(transactionAmount);
            if (!validated) {
                invoiceSummary.setValid(false);
            }
        }

        if (invoiceSummary.isValid()) {
            cache.putIfAbsent(orderId, new HashMap<>());
            Map<Locale, InvoiceSummary> cachedInvoices = cache.get(orderId);
            cachedInvoices.put(locale, invoiceSummary);
        }

        return invoiceSummary;
    }
}
```

