#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char* str;
    int value;
    struct node* next;
} entry;

typedef struct node {
    entry* data;
    struct node* next;
} node;

node* create_list(int size) {
    node* head = NULL, *current = NULL, *temp;

    for (int i = 0; i < size; ++i) {
        temp = (node*)malloc(sizeof(node));
        if (!temp) {
            perror("Memory allocation error");
            return NULL;
        }

        temp->data = (entry*)malloc(sizeof(entry));
        if (!temp->data) {
            free(temp);
            perror("Memory allocation error");
            return NULL;
        }

        temp->data->str = malloc(RAND_MAX * sizeof(char));
        if (!temp->data->str) {
            free(temp->data);
            free(temp);
            perror("Memory allocation error");
            return NULL;
        }

        for (int j = 0; j < RAND_MAX; ++j) {
            temp->data->str[j] = rand() % 36 + 'a' - 10; // alphanumeric sequence
        }
        temp->data->str[RAND_MAX] = '\0';
        temp->data->value = rand() % 100;
        temp->next = NULL;

        if (!head) {
            head = current = temp;
        } else {
            current->next = temp;
            current = temp;
        }
    }

    return head;
}

void free_list(node* head) {
    node* current = head;
    while (head) {
        current = head;
        head = head->next;
        free(current->data->str);
        free(current->data);
        free(current);
    }
}
