Record* deserialize(const char *filename, size_t *num_records);

// Function to manage memory allocation, initialization, and concurrent access control
void init_data_structures(const char *filename, int semaphore_value, int log_detailed) {
    // Validate input parameters
    if (strlen(filename) < 5 || filename[0] == PATH_SEPARATOR) {
        fprintf(stderr, "Invalid filename\n");
        exit(EXIT_FAILURE);
    }

    // Determine file type and directory path, create a unique version identifier
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", localtime(&now));
    int num_digits = strlen(filename) - 5;
    char extension[10];
    strncpy(extension, filename + strlen(filename) - num_digits, num_digits);
    char new_filename[256];
    snprintf(new_filename, sizeof(new_filename), "%s%s%s%s", filename, timestamp, extension, ".dat");

    // Create the file and open it for writing
    int fd = open(new_filename, O_CREAT | O_WRONLY | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for offsets and keys arrays, handle potential allocation failures
    off_t offsets_size = ((OFFSET_MAX - OFFSET_MIN) / (OFFSET_MAX - OFFSET_MIN + 1)) * RECORDS_MAX;
    off_t keys_size = sizeof(int) * RECORDS_MAX;
    void *offsets = mmap(NULL, offsets_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (offsets == MAP_FAILED) {
        perror("mmap: offsets");
        exit(EXIT_FAILURE);
    }
    void *keys = mmap(NULL, keys_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (keys == MAP_FAILED) {
        perror("mmap: keys");
        munmap(offsets, offsets_size);
        exit(EXIT_FAILURE);
    }

    // Allocate memory for records array and initialize with unique random values
    size_t records_size = sizeof(Record) * RECORDS_MAX;
    Record *records = malloc(records_size);
    if (records == NULL) {
        perror("malloc: records");
        munmap(offsets, offsets_size);
        munmap(keys, keys_size);
        exit(EXIT_FAILURE);
    }

    // Initialize records with unique random values and serialize to the file
    for (size_t i = 0; i < RECORDS_MAX; ++i) {
        records[i].value = rand() % RANDOM_RANGE;
        serialize(new_filename, &records[i], 1);
    }

    // Create and initialize the semaphore
    if (sem_init(&semaphore, 0, semaphore_value) != 0) {
        perror("sem_init");
        free(records);
        munmap(offsets, offsets_size);
        munmap(keys, keys_size);
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Close the file and print success message
    close(fd);
    if (log_detailed) {
        printf("Data structures initialized successfully:\n");
        printf("  Offsets allocated: %ld\n", offsets_size);
        printf("  Keys allocated: %ld\n", keys_size);
        printf("  Records allocated: %ld\n", records_size);
    } else {
        printf("Data structures initialized.\n");
    }
}

