```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <err.h>
#include "minirand.h"

typedef struct {
    int min;
    int max;
} Config;

struct record {
    int value;
};

int loadAndInitializeData(const char *path, const Config *config) {
    FILE *file = fopen(path, "rb");
    if (!file) {
        err(1, "Failed to open file: %s", path);
    }

    struct stat st;
    if (fstat(fileno(file), &st) == -1) {
        err(1, "Failed to get file statistics");
    }

    long *offsets = malloc((st.st_size + sizeof(long) - 1) / sizeof(long));
    if (!offsets) {
        err(1, "Failed to allocate memory for offsets");
    }

    int *keys = malloc((st.st_size + sizeof(int) - 1) / sizeof(int));
    if (!keys) {
        free(offsets);
        err(1, "Failed to allocate memory for keys");
    }

    struct record *records = malloc((st.st_size - sizeof(long)) / sizeof(struct record));
    if (!records) {
        free(keys);
        free(offsets);
        err(1, "Failed to allocate memory for records");
    }

    size_t read = 0;
    size_t offset = 0;
    while (read < st.st_size) {
        size_t len = sizeof(long);
        if (fseek(file, offset, SEEK_SET) == -1) {
            err(1, "Failed to seek file");
        }
        if (fread(offsets + read / sizeof(long), 1, len, file) != len) {
            err(1, "Failed to read offsets");
        }
        offset += len;
        read += len;

        len = sizeof(int);
        if (fseek(file, offset, SEEK_SET) == -1) {
            err(1, "Failed to seek file");
        }
        if (fread(keys + read / sizeof(int), 1, len, file) != len) {
            err(1, "Failed to read keys");
        }
        offset += len;
        read += len;

        struct record *record = records + read / sizeof(struct record);
        record->value = minirand_get() % (config->max - config->min + 1) + config->min;
    }

    fclose(file);
    return st.st_size / sizeof(struct record);
}
```

