import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.ReentrantLock;

public class CustomRecord {
    private final String key;
    private volatile long value;
    private static final AtomicLong accessCount = new AtomicLong();
    private static final ReentrantLock lock = new ReentrantLock();

    public CustomRecord(String key) {
        this.key = key;
        this.value = 0L;
    }

    public void incrementValueIfExists(double factor, ConcurrentHashMap<String, CustomRecord> map, boolean updateIfExists) {
        if (updateIfExists) {
            lock.lock();
            try {
                CustomRecord record = map.get(key);
                if (record != null) {
                    record.value += Math.round(factor * this.value);
                    accessCount.incrementAndGet();
                }
            } finally {
                lock.unlock();
            }
        } else {
            CustomRecord existingRecord = map.get(key);
            if (existingRecord == null) {
                map.putIfAbsent(key, new CustomRecord(key));
            }
        }
    }
}

public void adjustAndManageRecord(ConcurrentHashMap<String, CustomRecord> map, String key, int increment, boolean updateIfExists) {
    double factor = 2.0;
    if (increment < 0) {
        factor = -factor;
        increment = Math.abs(increment);
    }
    CustomRecord record = map.get(key);
    if (record != null) {
        record.incrementValueIfExists(factor, map, updateIfExists);
    } else if (!updateIfExists) {
        map.putIfAbsent(key, new CustomRecord(key));
    }
}
