For sorting the data structure, you can use a stable in-place quicksort implementation:

```c
void swap(struct Data* a, struct Data* b) {
    struct Data temp = *a;
    *a = *b;
    *b = temp;
}

int compare_data(const void* a, const void* b) {
    return ((*(struct Data*)a).u.i - (*(struct Data*)b).u.i);
}

void sort(struct Data* data, size_t count) {
    if (count <= 1) return;

    struct Data pivot = data[count / 2];
    size_t left = 0, right = count - 1;

    while (left <= right) {
        while (compare_data(&pivot, &data[left]) > 0) left++;
        while (compare_data(&pivot, &data[right]) < 0) right--;

        if (left <= right) swap(&data[left], &data[right]);
        left++;
        right--;
    }

    if (count % 2 == 1) swap(&data[count / 2], &pivot);

    sort(data, left);
    sort(data + left, count - left);
}
```

