            fprintf(logfile, "Error: Memory allocation exceeded\n");
            break;
        }
        integers[count] = integer_value;
        count++;

        // Allocate memory for records and populate with random pointers
        if (records == NULL) {
            records = malloc(count * sizeof(Record));
        }
        records[count - 1].key = integer_value;
        records[count - 1].offset = offset_count++;
        records[count - 1].pointer = malloc(sizeof(void*));
        *(records[count - 1].pointer) = malloc(rand() % 100 + 1); // Replace with your desired pointer size and range

        // Insert record into BST and AVL tree (for comparison purposes)
