        //avl_tree_insert(avl_tree, integer_value);

        // Sort the array using a stable sorting algorithm (e.g., merge sort or quicksort with a custom comparator)
        sort(integers, count);
    }

    // Perform in-order traversal of BST and AVL tree for comparison purposes
    in_order_traversal(bst);
    //avl_tree_in_order_traversal(avl_tree);

    // Free dynamically allocated memory (excluding the sorted array)
    for (int i = 0; i < count; ++i) {
        free(records[i].pointer);
        free(records[i].pointer);
    }
    free(records);
    free(bst);
    // Close logging system (optional)
    fclose(logfile);
}
