#ifndef MEMORY_MANAGER_H
#define MEMORY_MANAGER_H

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct Record {
    int value;
} Record;

struct MemoryManager {
    long *offsets;
    int *keys;
    Record *records;
    size_t num_records;
    pthread_mutex_t lock;
};

MemoryManager* memory_manager_create(size_t offset_size, size_t key_size, size_t record_count);
void memory_manager_destroy(MemoryManager *mm);
bool memory_manager_serialize(const MemoryManager *mm, const char *filename);
bool memory_manager_deserialize(MemoryManager *mm, const char *filename);

#endif // MEMORY_MANAGER_H

// memory_manager.c
#include "memory_manager.h"

void init_records(Record *records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % 100;
    }
}

MemoryManager* memory_manager_create(size_t offset_size, size_t key_size, size_t record_count) {
    MemoryManager *mm = malloc(sizeof(MemoryManager));
    if (!mm) return NULL;

    mm->offsets = calloc(offset_size, sizeof(long));
    if (!mm->offsets) goto error;

    mm->keys = calloc(key_size, sizeof(int));
    if (!mm->keys) goto error;

    mm->records = malloc(record_count * sizeof(Record));
    if (!mm->records) goto error;

    mm->num_records = record_count;
    pthread_mutex_init(&mm->lock, NULL);

    init_records(mm->records, mm->num_records);

    return mm;

error:
    if (mm->offsets) free(mm->offsets);
    if (mm->keys) free(mm->keys);
    if (mm->records) free(mm->records);
    free(mm);
    return NULL;
}

void memory_manager_destroy(MemoryManager *mm) {
    if (mm->offsets) free(mm->offsets);
    if (mm->keys) free(mm->keys);
    if (mm->records) free(mm->records);
    pthread_mutex_destroy(&mm->lock);
    free(mm);
}

bool memory_manager_serialize(const MemoryManager *mm, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return false;

    fwrite(mm->offsets, sizeof(long), mm->num_records, file);
    fwrite(mm->keys, sizeof(int), mm->num_records, file);
    fwrite(mm->records, sizeof(Record), mm->num_records, file);

    fclose(file);
    return true;
}

bool memory_manager_deserialize(MemoryManager *mm, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return false;

    fread(mm->offsets, sizeof(long), mm->num_records, file);
    fread(mm->keys, sizeof(int), mm->num_records, file);
    fread(mm->records, sizeof(Record), mm->num_records, file);

    fclose(file);
    return true;
}
