} Record;

void validate_size(int size, int min, int max) {
    if (size < min || size > max) {
        fprintf(stderr, "Invalid size: %d. Valid range is [%d, %d].\n", size, min, max);
        exit(1);
    }
}

void* allocate_and_init(int size, int element_size, void (*init)(void*, const void*), void* userdata) {
    void* ptr = malloc(size * element_size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
    memset(ptr, 0, size * element_size);
    for (int i = 0; i < size; ++i) {
        init((char*)ptr + i * element_size, userdata);
    }
    return ptr;
}

void init_offsets(void* offsets, int size) {
    for (int i = 0; i < size; ++i) {
        ((long*)offsets)[i] = -i;
    }
}

void init_keys(void* keys, int size) {
    for (int i = 0; i < size; ++i) {
        ((int*)keys)[i] = i;
    }
}

void init_records(void* records, int num_records) {
    Record* record_ptr = (Record*)records;
    for (int i = 0; i < num_records; ++i) {
        sprintf(record_ptr[i].str, "Record %d", i);
        record_ptr[i].value = rand() % 100; // Replace with your desired range
    }
}

int hash(const void* key, int table_size) {
    const unsigned long ascii = (unsigned char)*key;
    return (ascii % table_size + table_size) % table_size;
}

void check_for_duplicates(Record* records, int num_records, int table_size) {
    Record* table = malloc(table_size * sizeof(Record));
    memset(table, 0, table_size * sizeof(Record));

    for (int i = 0; i < num_records; ++i) {
        int index = hash(&records[i].key, table_size);
        while (table[index].key != 0) {
            if (table[index].key == records[i].key) {
                fprintf(stderr, "Duplicate key found: %d\n", records[i].key);
                exit(1);
            }
            index = (index + 1) % table_size;
        }
        table[index] = records[i];
    }

    free(table);
}
