#include <sys/types.h>
#include <unistd.h>

#define MAX_HOSTNAME_LENGTH 256
#define MAX_FILENAME_LENGTH 256
#define BUFFER_SIZE 4096

int resolve_hostname_to_ip(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return -1;
    }

    void *address;
    struct sockaddr_in *ipv4_addr = (struct sockaddr_in *)res->ai_addr;
    address = &ipv4_addr->sin_addr.s_addr;

    memcpy(ip_address, address, sizeof(u_char) * 4);

    freeaddrinfo(res);
    return 0;
}

char *process_filename(const char *original_filename) {
    static char new_filename[MAX_FILENAME_LENGTH];
    int original_extension_length = strlen(strchr(original_filename, '.'));
    int num_digits = 0;
    int i;

    for (i = 0; original_filename[i] != '\0'; ++i) {
        if (isdigit((unsigned char)original_filename[i])) {
            ++num_digits;
        }
    }

    if (num_digits > 0) {
        int j = i - num_digits - original_extension_length;
        memcpy(new_filename + strlen(new_filename), &original_filename[j], num_digits);
    }

    strcpy(new_filename, original_filename);
    char *extension = strchr(new_filename, '.');

    if (extension != NULL && strcmp(extension, ".exe") == 0) {
        strcpy(extension, ".csv");
    } else {
        strcpy(extension, ".log");
    }

    return new_filename;
}
```

