class CharBuffer {
public:
    CharBuffer() : buffer_(CHAR_BUFFER_SIZE, '\0'), size_{0} {}

    void append(const std::string& str) {
        if (size_ + str.length() > CHAR_BUFFER_SIZE) {
            resize();
        }
        std::copy(str.begin(), str.end(), &buffer_[size_]);
        buffer_[size_+str.length()] = '\0';
        size_ += str.length();
    }

private:
    void resize() {
        char* new_buffer = new char[2 * CHAR_BUFFER_SIZE];
        std::copy(buffer_, buffer_ + size_, new_buffer);
        delete[] buffer_;
        buffer_ = new_buffer;
        CHAR_BUFFER_SIZE *= 2;
    }

    char* buffer_;
    int size_;
};

class FloatBuffer {
public:
    FloatBuffer(float precision) : precision_(precision), buffer_(new float[10]) {}

    void append(float value) {
        if (size_ == buffer_.size()) {
            resize();
        }
        buffer_[size_++] = value;
    }

private:
    void resize() {
        float* new_buffer = new float[2 * buffer_.size()];
        std::copy(buffer_, buffer_ + size_, new_buffer);
