void round_to_precision(double* value, int precision) {
    *value = round(*value * pow(10.0, precision)) / pow(10.0, precision);
}

int check_precision_loss(double a, double b, int precision) {
    double diff = fabs(a - b);
    return diff > pow(10.0, precision);
}

measurement* allocate_measurements(size_t num) {
    measurement* measurements = (measurement*)malloc(num * sizeof(measurement));
    if (!measurements) return NULL;

    for (size_t i = 0; i < num; ++i) {
        init_measurement(&measurements[i], "");
    }

    return measurements;
}

void free_measurements(measurement* measurements, size_t num) {
