            exit(EXIT_FAILURE);
        }
        keys[i] = i;
        offsets[i + OFFSET_MIN] = (long)(offsets[OFFSET_MIN] + sizeof(Record));
        records[i] = record;

        pthread_create(&threads[i], NULL, serialize, &records[i]);
    }

    for (int i = 0; i < record_count; ++i) {
        pthread_join(threads[i], NULL);
    }

    fclose(file);

    for (int i = 0; i < record_count; ++i) {
        destroy_record(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}
