    snprintf(log->destination_ip, sizeof(log->destination_ip), "%.3f%.3f%.3f%.3f",
             ((double)rand() / RAND_MAX), ((double)rand() / RAND_MAX),
             ((double)rand() / RAND_MAX), ((double)rand() / RAND_MAX));
