void error(const char* message) {
    fprintf(stderr, "%s\n", message);
}

int allocate_logs() {
    if (num_logs >= MAX_LOGS) {
        error("Error: Cannot allocate more logs. Maximum limit reached.");
        return -1;
    }
    return num_logs;
}

void sort_logs(Log* logs, int size) {
    qsort(logs, size, sizeof(Log), (int (*)(const void*, const void*))compare);
}

int compare(const void* a, const void* b) {
    return ((Log*)a)->timestamp - ((Log*)b)->timestamp;
}

void filter_logs(Log* logs, int size, int min_packet_length, int max_packet_length, int protocol, int flags) {
    int filtered_count = 0;
    for (int i = 0; i < size; ++i) {
        if ((logs[i].packet_length >= min_packet_length && logs[i].packet_length <= max_packet_length) &&
            (protocol == -1 || logs[i].protocol == protocol) &&
            (flags == -1 || (logs[i].flags & flags) == flags)) {
            logs[filtered_count++] = logs[i];
        }
    }
    num_logs = filtered_count;
}

void deallocate_logs() {
    free(logs);
    logs = NULL;
    num_logs = 0;
}

int main() {
