@Slf4j
public class ImageProcessingPipeline {
    private static final int MAX_THREADS = 10;
    private static final int TIMEOUT_MILLIS = 5000;
    private static final double CACHE_LOAD_FACTOR = 0.75;
    private static final int CACHE_MAX_SIZE = 1000;
    private static final Path CONFIG_FILE = Resources.getResource("config.yaml").toAbsolutePath();

    private final ExecutorService executor;
    private final Cache<String, Mat> imageCache;

    public ImageProcessingPipeline() {
        executor = Executors.newFixedThreadPool(MAX_THREADS);
        imageCache = CacheBuilder.newBuilder()
                .maximumSize(CACHE_MAX_SIZE)
                .concurrencyLevel(MAX_THREADS)
                .removalListener((key, value, cause) -> log.info("Evicted image from cache: {}", key))
                .build(new CacheLoader<String, Mat>() {
                    @Override
                    public Mat load(String key) throws Exception {
                        return processImage(key);
                    }
                });
    }

    private Mat processImage(String key) {
        // Load configuration settings from YAML file
        // ...

        // Read the original image
        Mat src = Imgcodecs.imread(key);

        // Apply transformations
        List<Mat> transformations = new ArrayList<>();
        // ...
        for (Mat transformation : transformations) {
            Imgproc.warpAffine(src, transformation, src.size());
            src = transformation;
        }

        return src;
    }

    public void processImages(List<String> imagePaths) {
        AtomicInteger completedTasks = new AtomicInteger(0);
        CompletionService<Mat> completionService = new ExecutorCompletionService<>(executor);

        for (String imagePath : imagePaths) {
            Future<Mat> future = completionService.submit(new Callable<Mat>() {
                @Override
                public Mat call() throws Exception {
                    return processImage(imagePath);
                }
            });
            completionService.take().get(); // Wait for the current task to complete
            completedTasks.incrementAndGet();
        }

        while (completedTasks.get() < imagePaths.size()) {
            Future<Mat> future = completionService.take();
            Mat result;
            try {
                result = future.get();
            } catch (Exception e) {
                log.error("Error processing image: {}", e.getMessage());
                continue;
            }
            imageCache.put(imagePath, result); // Cache the processed image
        }
    }
}
```

This implementation uses OpenCV for image processing and Google Guava's `CacheBuilder` for caching images. It also includes a simple thread pool for concurrently processing multiple images. The configuration management and performance optimization aspects are not fully implemented in this example, but you can extend the code to include those features as needed.']

