#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct ComplexDataNode {
    double value;
    char* str;
    struct ComplexDataNode* next;
} ComplexDataNode;

ComplexDataNode* create_node(double value, const char* str) {
    ComplexDataNode* node = (ComplexDataNode*)aligned_alloc(sizeof(ComplexDataNode), alignof(double));
    node->value = value;
    node->str = strdup(str);
    node->next = NULL;
    return node;
}

void insert_node(ComplexDataNode** head, ComplexDataNode* node) {
    if (*head == NULL) {
        *head = node;
    } else {
        ComplexDataNode* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
}

ComplexDataNode* find_node_by_index(ComplexDataNode* head, size_t index) {
    ComplexDataNode* current = head;
    for (size_t i = 0; i < index && current != NULL; ++i) {
        current = current->next;
    }
    return current;
}

ComplexDataNode* find_node_by_value(ComplexDataNode* head, double value) {
    ComplexDataNode* current = head;
    while (current != NULL) {
        if (current->value == value) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void remove_node(ComplexDataNode** head, ComplexDataNode* node) {
    if (*head == node) {
        *head = node->next;
    } else {
        ComplexDataNode* current = *head;
        while (current->next != node) {
            current = current->next;
        }
        current->next = node->next;
    }
    free(node->str);
    free(node);
}

void traverse_list(ComplexDataNode* head, void (*func)(ComplexDataNode*)) {
    ComplexDataNode* current = head;
    while (current != NULL) {
        func(current);
        current = current->next;
    }
}

void serialize_list(const ComplexDataNode* head, FILE* file) {
    ComplexDataNode* current = const_cast<ComplexDataNode*>(head);
    while (current != NULL) {
        fwrite(&current->value, sizeof(double), 1, file);
        size_t str_len = strlen(current->str);
        fwrite(&str_len, sizeof(size_t), 1, file);
        fwrite(current->str, sizeof(char), str_len + 1, file);
        current = current->next;
    }
}
```

