const int MAX_RECORDS = 100000;
const int MIN_RECORDS = 100;
const int MAX_RANDOM_VALUE = 1000000;
const int NUM_THREADS = 4;

std::vector<long> offsets;
std::vector<int> keys;
std::vector<struct Record> records;

