std::mt19937 gen(rd());

void allocateAndInit() {
    long maxOffset = std::next_after(offsets.size(), MAX_OFFSET);
    int maxKeys = std::min(MAX_KEYS, static_cast<int>(maxOffset));
    offsets.resize(maxOffset);
    keys.resize(maxKeys);
}

void populateRecords() {
    std::uniform_int_distribution<> distr(0, MAX_RANDOM_VALUE);
    std::vector<int> usedValues;

    for (auto& record : records) {
        int value = -1;
        do {
            value = distr(gen);
        } while (std::find(usedValues.begin(), usedValues.end(), value) != usedValues.end());

        usedValues.push_back(value);
        record.value = value;
    }
}

void serialize() {
    std::ofstream file("data.txt");
    if (!file.is_open()) {
        std::cerr << "Error opening file" << std::endl;
        return;
    }

    for (const auto& record : records) {
        std::ostringstream ss;
        ss << record.value;
        file << ss.str() << "\n";
    }
}

void deserialize() {
    std::ifstream file("data.txt");
    if (!file.is_open()) {
        std::cerr << "Error opening file" << std::endl;
        return;
    }

    std::string line;
    int index = 0;
    while (std::getline(file, line)) {
        records[index].value = std::stoi(line);
        ++index;
    }
}

