typedef struct Record {
    int key;
    long offset;
    int value;
} Record;

Record* init_arrays(size_t max_records, size_t alignment, size_t min_value, size_t max_value, bool free_all) {
    long *offsets = (long*) malloc(max_records * sizeof(long));
    if (!offsets) return NULL;
    int *keys = (int*) aligned_alloc(alignment, max_records * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    Record *records = (Record*) aligned_alloc(alignment, max_records * sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < max_records; ++i) {
        offsets[i] = i;
        keys[i] = i;
        records[i].key = keys[i];
        records[i].offset = offsets[i];
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    if (free_all) {
        free(records);
        free(keys);
        free(offsets);
    }

    return records;
}
