#include <random>
#include <string>
#include <thread>
#include <mutex>
#include <atomic>
#include <new>

struct DataRecord {
    int key;
    double value;
    std::string data;
    long offset;
    int linkedKey;
};

class DataManager {
public:
    DataManager(size_t maxRecords, size_t recordSize, size_t bufferSize)
        : _maxRecords(maxRecords), _recordSize(recordSize), _bufferSize(bufferSize),
          _records(_records.data(), _records.capacity() * _recordSize),
          _offsets(_offsets.data(), _offsets.capacity()),
          _keys(_keys.data(), _keys.capacity()),
          _buffer(_buffer.data(), _buffer.capacity() * bufferSize) {
        std::fill_n(_offsets.data(), maxRecords, 0);
        std::fill_n(_keys.data(), maxRecords, 0);
    }

    void addRecord(int key, double value, const std::string& data) {
        if (_records.size() == _records.capacity()) {
            resize();
        }

        DataRecord* record = &_records[_records.size()];
        new (record) DataRecord{key, value, data, _offsets[_records.size()], key};
        _keys[_records.size()] = key;
        _offsets[_records.size()] = _offsets[_records.size() - 1] + _recordSize;
        _records.emplace_back();
    }

    void populateRandom(size_t count) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 100);

        for (size_t i = 0; i < count; ++i) {
            addRecord(dis(gen), dis(gen), generateRandomString(10));
        }
    }

    void freeAll() {
        _records.clear();
        _offsets.clear();
        _keys.clear();
        _buffer.clear();
    }

private:
    void resize() {
        auto newCapacity = _records.capacity() * 2;
        std::vector<DataRecord> newRecords(_records.data(), _records.data() + _records.size());
        _records.resize(newCapacity);
        std::copy(newRecords.begin(), newRecords.end(), _records.begin() + _records.size() - newRecords.size());
    }

    std::string generateRandomString(size_t length) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(32, 126); // ASCII printable characters

        std::string result(length, 0);
        for (auto& c : result) {
            c = static_cast<char>(dis(gen));
        }
        return result;
    }

    std::vector<DataRecord> _records;
    std::vector<long> _offsets;
    std::vector<int> _keys;
    std::vector<char> _buffer;
    size_t _maxRecords;
    size_t _recordSize;
    size_t _bufferSize;
};

// Thread-safe function to add records asynchronously
void addRecordAsync(DataManager& manager, int key, double value, const std::string& data) {
    std::lock_guard<std::mutex> lock(manager.mutex);
    manager.addRecord(key, value, data);
}

int main() {
    DataManager manager(1000000, sizeof(DataRecord), 1024 * 1024); // 1M records, 1GB buffer
    std::mutex managerMutex;
    std::vector<std::thread> threads;

    for (size_t i = 0; i < 10; ++i) {
        threads.emplace_back(addRecordAsync, std::ref(manager), i * 10000, rand() % 100, generateRandomString(10));
    }

    for (auto& thread : threads) {
        thread.join();
    }

    manager.populateRandom(100000); // Populate remaining records with random data

    // ... other code to process the data ...

    manager.freeAll();
}
```

