#include <iostream>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <memory>

struct DataEntry {
    int key;
    long offset;
    std::unique_ptr<char[]> str_buf;
};

struct Node {
    DataEntry entry;
    std::unique_ptr<Node> next;
};

std::unique_ptr<Node> create_node(const DataEntry& data) {
    auto node = std::make_unique<Node>();
    node->entry = data;
    return node;
}

void init_data_entries(int num_entries, int min_key, int max_key, long offset, size_t str_buf_capacity, void (*error_callback)(const char* message)) {
    std::vector<DataEntry> entries;
    std::unique_ptr<Node> head(new Node());
    std::unique_ptr<Node> current = head.get();

    for (int i = 0; i < num_entries; ++i) {
        auto data = DataEntry{rand() % (max_key - min_key + 1) + min_key, offset * i, std::make_unique<char[]>(str_buf_capacity + 1)};
        current->entry = data;
        current->str_buf->at(str_buf_capacity) = '\0'; // Ensure null-terminated

        if (current->next.get() == nullptr && i < num_entries - 1) {
            current->next.reset(new Node());
            current = current->next.get();
        }
    }

    if (!error_callback) return;

    for (const auto& entry : entries) {
        try {
            // Convert integer to string and store in the buffer
            std::sprintf(entry.str_buf.get(), "%ld", entry.key);
        } catch (...) {
            error_callback(("Error converting integer to string for key: " + std::to_string(entry.key)).c_str());
            break;
        }
    }
}
