typedef struct Record {
    int value;
} Record;

void init_rand(unsigned long seed);
int get_random_int(int min, int max);

Record* create_record_array(size_t size) {
    Record *records = malloc(sizeof(Record) * size);
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < size; ++i) {
        records[i].value = get_random_int(1, INT32_MAX);
    }

    return records;
}

int* create_key_array(size_t size) {
    int *keys = malloc(sizeof(int) * size);
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys.\n");
        exit(EXIT_FAILURE);
    }

    init_rand(time(NULL)); // Initialize random number generator with current time

    for (size_t i = 0; i < size; ++i) {
        int key = get_random_int(1, INT32_MAX);
        int found = 0;

        for (size_t j = 0; j < i; ++j) {
            if (keys[j] == key) {
                --i; // Re-loop to find a unique key
                found = 1;
                break;
            }
        }

        if (!found) keys[i] = key;
    }

    return keys;
}

long* create_offset_array(size_t size) {
    long *offsets = malloc(sizeof(long) * size);
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        exit(EXIT_FAILURE);
    }

    return offsets;
}

void resize_record_array(Record **records, size_t new_size) {
    Record *new_records = realloc(*records, sizeof(Record) * new_size);
    if (!new_records) {
        fprintf(stderr, "Failed to reallocate memory for records.\n");
        exit(EXIT_FAILURE);
    }

    *records = new_records;
}

void cleanup(Record **records, int *keys, long *offsets) {
    free(*records);
    free(keys);
    free(offsets);
}

void init_rand(unsigned long seed) {
    srand(seed);
}

int get_random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

Record* create_data_structures(size_t num_offsets, size_t num_keys, size_t num_records) {
    long *offsets = create_offset_array(num_offsets);
    int *keys = create_key_array(num_keys);
    Record *records = create_record_array(num_records);

    if (num_records > num_keys) {
        fprintf(stderr, "Error: Number of records exceeds the number of keys.\n");
        cleanup(&offsets, &keys, &records);
        exit(EXIT_FAILURE);
    }

    return records;
}
