#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <limits.h>

typedef struct Record {
    int value;
    size_t key_len;
    char key[1]; // dynamic array, size determined by key_len
} Record;

Record* create_records(size_t max_records, size_t max_key_len, size_t max_total_length) {
    size_t total_length = 0;
    Record *records = NULL;

    srand(time(NULL)); // seed random number generator

    for (size_t i = 0; i < max_records; ++i) {
        size_t key_len = rand() % max_key_len + 1;
        if (total_length + key_len > max_total_length) {
            fprintf(stderr, "Error: Total buffer size exceeded.\n");
            free(records);
            return NULL;
        }

        records = realloc(records, sizeof(Record) * (i + 1));
        if (!records) {
            perror("Memory allocation failure.");
            return NULL;
        }

        Record* current_record = &records[i];
        current_record->key_len = key_len;
        current_record->value = 0; // initialize value to zero

        total_length += key_len + sizeof(Record);

        for (size_t j = 1; j <= key_len; ++j) {
            current_record->key[j] = rand() % 128; // generate random ASCII character
        }
    }

    return records;
}
