int loadAndInitializeData(Config* config) {
    json_t* root = NULL;
    FILE* file = fopen(config->file_path, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", config->file_path);
        return -1;
    }

    size_t length = 0;
    ssize_t read = json_loadf(file, &root, 0, &length);
    if (read < 0) {
        fprintf(stderr, "Failed to parse JSON file: %s\n", config->file_path);
        fclose(file);
        return -1;
    }
    fclose(file);

    json_array_t* array = json_array(root);
    int num_items = json_array_size(array);
    if (num_items != config->num_records) {
        fprintf(stderr, "Unexpected number of items in JSON file: %d\n", num_items);
        json_decref(root);
        return -1;
    }

    long* offsets = malloc(sizeof(long) * (num_items + 1));
    int* keys = malloc(sizeof(int) * num_items);
    Record* records = malloc(sizeof(Record) * num_items);

    for (int i = 0; i < num_items; ++i) {
        json_t* item = json_array_get(array, i);
        if (!json_is_object(item)) {
            fprintf(stderr, "Invalid JSON object at index %d\n", i);
            free(offsets);
            free(keys);
            free(records);
            json_decref(root);
            return -1;
        }

        json_object_foreach(item, key, value) {
            if (strcmp(key->string, "value") == 0) {
                records[i].value = json_integer_value(value);
            } else if (strcmp(key->string, "offset") == 0) {
                offsets[i] = json_integer_value(value);
            } else if (strcmp(key->string, "key") == 0) {
                keys[i] = json_integer_value(value);
            }
        }
    }

    offsets[num_items] = num_items * sizeof(Record);

    // Implement a random number generator here using the specified range.
    // For example, you can use the C library's rand() function:
    // records[i].value = rand() % (config->max_value - config->min_value + 1) + config->min_value;

    json_decref(root);
    return num_items;
}
