int read_config(char *path, long *offsets, int *keys, size_t *size) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) return 1; // error opening file

    struct stat st;
    fstat(fd, &st);
    if (st.st_size == 0) {
        close(fd);
        return 2; // empty file
    }

    offsets = malloc(st.st_size);
    if (!offsets) {
        close(fd);
        return 3; // memory allocation failure
    }

    int read = read(fd, offsets, st.st_size);
    if (read != st.st_size) {
        free(offsets);
        close(fd);
        return 4; // read error
    }

    *size = st.st_size / sizeof(long);
    *keys = malloc(*size * sizeof(int));
    if (!*keys) {
        free(offsets);
        close(fd);
        return 5; // memory allocation failure for keys
    }

    // pseudo-random number generator to populate keys array
    for (size_t i = 0; i < *size; ++i) {
        (*keys)[i] = rand();
    }

    close(fd);
    return 0; // success
}
