4. Serialization and deserialization:

```c
#include <stdio.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>

void serialize(char *path, long *offsets, int *keys, size_t size) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    if (fd == -1) return; // error opening file

    mmap(NULL, size * sizeof(long) + size * sizeof(int), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    memcpy(mmap_addr, offsets, size * sizeof(long));
    memcpy(mmap_addr + size * sizeof(long), keys, size * sizeof(int));

    close(fd);
}

void deserialize(char *path, long *offsets, int *keys, size_t *size) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) return; // error opening file

    struct stat st;
    fstat(fd, &st);
    if (st.st_size < 2 * sizeof(long) + 2 * sizeof(int)) {
        close(fd);
        return; // invalid file size
    }

    mmap_addr = mmap(NULL, st.st_size, PROT_READ, MAP_SHARED, fd, 0);
    memcpy(offsets, mmap_addr, size * sizeof(long));
    memcpy(keys, mmap_addr + size * sizeof(long), size * sizeof(int));

    close(fd);
}
```

