[' Here's a C code implementation that addresses the given programming task:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct data_point {
    double value;
    char* str;
    int id;
    struct data_point* next;
} DataPoint;

DataPoint* create_data_point(double value, const char* str) {
    DataPoint* dp = (DataPoint*)malloc(sizeof(DataPoint));
    if (!dp) return NULL;

    dp->value = value;
    dp->str = strdup(str);
    if (!dp->str) {
        free(dp);
        return NULL;
    }

    dp->id = rand() % 100 + 1; // Random integer within range (1, 100)
    dp->next = NULL;

    return dp;
}

void append_to_list(DataPoint** head, DataPoint* new_data_point) {
    if (!*head) {
        *head = new_data_point;
        return;
    }

    DataPoint* current = *head;
    while (current->next) current = current->next;
    current->next = new_data_point;
}

void delete_from_list(DataPoint** head, int id) {
    if (!*head) return;

    DataPoint* current = *head;
    DataPoint* previous = NULL;

    while (current && current->id == id) {
        previous = current;
        current = current->next;
        free(previous->str);
        free(previous);
        if (!current) break;
        previous = current;
    }

    if (previous) previous->next = current;
}

DataPoint* create_and_populate_list(int size, double min_value, double max_value) {
    srand(time(NULL));
    DataPoint* head = NULL;

    for (int i = 0; i < size; ++i) {
        char str[100];
        sprintf(str, "String %d", i);
        append_to_list(&head, create_data_point(min_value + rand() * (max_value - min_value), str));
    }

    return head;
}
```

This code defines a `DataPoint` structure and functions to manage the linked list of these data points. The `create_data_point` function dynamically allocates memory for each data point, including the string pointer, and initializes it with the given values. The `append_to_list` and `delete_from_list` functions handle insertions and deletions in the linked list optimized for performance.

The `create_and_populate_list` function creates a list of data points with random values within a specified range, which can be used to test the functionality of the other functions.']

