Record* init_records(size_t n, size_t m, size_t k, size_t p, long max_offset, int key_range_start, int key_range_end, int value_range_start, int value_range_end, size_t q) {
    Record *records = (Record *)malloc(q * sizeof(Record));
    if (!records) {
