```cpp
#include <iostream>
#include <vector>
#include <list>
#include <mutex>
#include <random>
#include <thread>
#include <atomic>

struct Node {
    char buffer[1024];
    int value;
};

struct Transaction {
    Node* node;
    std::string id;
    long timestamp;
    // metadata
};

struct Batch {
    std::list<Transaction> transactions;
    size_t count;
};

std::mutex mtx;
std::atomic<size_t> nextId(0);
std::default_random_engine generator;
std::uniform_int_distribution<int> distribution(1, 100000);

void generateTransaction(Batch& batch, size_t index) {
    std::lock_guard<std::mutex> lock(mtx);
    auto transaction = new Transaction{};
    transaction->id = "T" + std::to_string(nextId++);
    Node* node = new Node;
    node->value = distribution(generator);
    strcpy(node->buffer, transaction->id.c_str());
    transaction->node = node;
    batch.transactions.push_back(*transaction);
    batch.count++;
}

void populateBatches(std::vector<Batch>& batches, size_t numTransactions, size_t numBatches) {
    std::vector<std::thread> threads;
    for (size_t i = 0; i < numThreads; ++i) {
        threads.emplace_back([&batches, numTransactions]() {
            for (size_t j = 0; j < numBatches; ++j) {
                Batch& batch = batches[j];
                for (size_t k = 0; k < numTransactions / numThreads; ++k) {
                    generateTransaction(batch, k);
                }
            }
        });
    }
    threads.back().join();
}
```

This code creates a `Node`, `Transaction`, and `Batch` data structures to represent the complex data model. The `generateTransaction()` function handles memory allocation for nodes and transactions, ensuring that each transaction's node buffer is initialized with a unique string identifier based on its index in the transaction array. The integer value in each node is set to a randomly generated number within a specified range.

The `populateBatches()` function creates multiple threads to populate batches concurrently, using a mutex to synchronize access to shared resources (the nextId counter and the list of transactions). This helps prevent race conditions and deadlocks.

