void InitializeBatches(size_t numTransactions, size_t batchSize, int minValue, int maxValue, RandomValueGenerator* rng) {
    // Allocate memory for node array
    struct Node* nodes = (struct Node*)malloc(numTransactions * sizeof(struct Node));
    if (!nodes) {
        fprintf(stderr, "Failed to allocate memory for nodes\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for transaction array
    struct Transaction* transactions = (struct Transaction*)malloc(numTransactions * sizeof(struct Transaction));
    if (!transactions) {
        fprintf(stderr, "Failed to allocate memory for transactions\n");
        free(nodes);
        exit(EXIT_FAILURE);
    }

    // Allocate memory for batch list head and current batch
    struct Batch* head = (struct Batch*)malloc(sizeof(struct Batch));
    struct Batch* currentBatch = head;

