        // Set transaction's node and timestamp
        transactions[i].node = &nodes[i];
        transactions[i].timestamp = time(NULL);

        // If current batch is full, create a new one
        if (currentBatch->count == batchSize) {
            currentBatch->transactions = realloc(currentBatch->transactions, sizeof(struct Transaction)*batchSize*2);
            currentBatch->count *= 2;
        }

        // Add transaction to the current batch
        currentBatch->transactions[currentBatch->count++] = transactions[i];
    }

    // Initialize random values for each transaction's integer value
    for (size_t i = 0; i < numTransactions; ++i) {
        transactions[i].node->value = rng->generateRandom(minValue, maxValue);
    }
}
