    public void compressAndArchive(String inputDirectoryPath, String outputZipFilePath) throws IOException {
        // Compress each file in the input directory using the appropriate algorithm based on size and performance requirements
        List<Path> files = Files.list(Paths.get(inputDirectoryPath)).collect(Collectors.toList());
        for (Path file : files) {
            String fileName = file.getFileName().toString();
            if (!Files.isDirectory(file)) {
                byte[] data = Files.readAllBytes(file);
                String algorithm = selectCompressionAlgorithm(data.length);
                byte[] compressedData = compressionManager.compress(data, algorithm);
                // Save the compressed file to a temporary location
                Path tempFile = Files.createTempFile("compressed_", ".gz");
                Files.write(tempFile, compressedData);
            }
        }

        // Archive all compressed files in the input directory and save the archive to the output ZIP file path
        ZipOutputStream zipOutputStream = new ZipOutputStream(new FileOutputStream(outputZipFilePath));
        for (Path file : files) {
            if (!Files.isDirectory(file)) {
                Path tempFile = Files.createTempFile("compressed_", ".gz");
                Files.move(tempFile, file.resolveSibling(fileName.replaceAll(".+\\.(.+)", "_" + fileName)));
                zipOutputStream.putNextEntry(new ZipEntry(fileName));
                try (InputStream inputStream = new FileInputStream(tempFile.toFile())) {
                    byte[] buffer = new byte[1024];
                    int bytesRead;
                    while ((bytesRead = inputStream.read(buffer)) != -1) {
                        zipOutputStream.write(buffer, 0, bytesRead);
                    }
                }
                Files.deleteIfExists(tempFile);
            }
        }
        zipOutputStream.finish();
        zipOutputStream.closeEntry();
        zipOutputStream.close();
    }

