[' Here's a C++ implementation using std::vector for dynamic memory management and avoiding common pitfalls such as integer overflow and data corruption in multi-threaded environments. The code uses std::random_device, std::uniform_int_distribution, and std::mutex for generating unique random numbers and synchronization.

```cpp
#include <iostream>
#include <vector>
#include <random>
#include <mutex>
#include <thread>
#include <atomic>

struct Record {
    int value;
};

std::mutex mtx;
std::atomic<bool> is_initialized(false);
std::random_device rd;
std::uniform_int_distribution<> dist;

void generateUniqueRandomNumbers() {
    std::vector<Record> records;
    records.reserve(num_records);

    dist = std::uniform_int_distribution<>(min_value, max_value);
    std::set<int> uniqueValues;

    while (records.size() < num_records && !is_initialized) {
        int randomValue = dist(rd);
        if (uniqueValues.insert(randomValue).second) {
            records.emplace_back();
            records.back().value = randomValue;
        }
    }

    if (!is_initialized) {
        std::cerr << "Failed to initialize records due to insufficient unique values." << std::endl;
        for (auto& offsets : offsetsVector) {
            delete[] offsets;
        }
        for (auto& keys : keysVector) {
            delete[] keys;
        }
        delete[] records.data();
        is_initialized = false;
        return;
    }

    is_initialized = true;
}

void* initRecords(int min_value, int max_value, size_t num_records) {
    this_thread::yield(); // Yield to other threads before initializing.

    std::lock_guard<std::mutex> lock(mtx);

    if (is_initialized) {
        return records.data();
    }

    offsetsVector.resize(num_records + 1);
    keysVector.resize(num_records);
    records.reserve(num_records);

    dist = std::uniform_int_distribution<>(min_value, max_value);

    for (size_t i = 0; i < num_records + 1; ++i) {
        offsetsVector[i] = new long[i];
    }

    std::thread generateThread(generateUniqueRandomNumbers);
    generateThread.detach();

    return nullptr;
}

std::vector<long> offsetsVector;
std::vector<int> keysVector;

void cleanup() {
    if (is_initialized) {
        for (auto& offsets : offsetsVector) {
            delete[] offsets;
        }
        for (auto& keys : keysVector) {
            delete[] keys;
        }
        delete[] records.data();
        is_initialized = false;
    }
}
```

This implementation uses a separate thread to generate unique random numbers and ensures that the function is thread-safe by using a mutex for synchronization. The `initRecords()` function returns a null pointer initially, and once the records are initialized, it returns a pointer to the first element of the `record` array. The cleanup process frees all allocated memory upon completion.']

