class AsyncReducer {
  constructor(concurrency, throttleTime) {
    this.queue = [];
    this.concurrency = concurrency || 4;
    this.throttleTime = throttleTime || 100;
    this.results = new Map();
  }

  async reduce(array, initialValue, callback) {
    if (this.queue.length >= this.concurrency) await this.processQueue();

    const result = this.results.get(array) || array;
    const index = result.findIndex(item => Array.isArray(item));

    if (index !== -1) result[index] = await callback(result[index], ...array.slice(index));
    else result.push(await callback(initialValue, ...array));

    this.results.set(array, result);
    this.queue.push(array);
  }

  async processQueue() {
    while (this.queue.length > 0) {
      const array = this.queue.shift();
      await new Promise((resolve) => setTimeout(resolve, this.throttleTime));
      await this.reduce(array);
    }
  }
}
```

