    Node* node;
    time_t timestamp;
    // metadata specific to your application
} Transaction;

typedef struct {
    Transaction* transactions;
    size_t count;
} Batch;

void generate_unique_id(char* buffer, size_t index) {
    snprintf(buffer, sizeof(buffer), "transaction_%zu", index);
}

Node* create_node() {
    Node* node = (Node*) malloc(sizeof(Node));
    if (!node) return NULL;
    return node;
}

void destroy_node(Node** node) {
    free(*node);
    *node = NULL;
}

Batch* create_batch(size_t capacity) {
    Batch* batch = (Batch*) malloc(sizeof(Batch));
    if (!batch) return NULL;

    batch->transactions = (Transaction*) calloc(capacity, sizeof(Transaction));
    if (!batch->transactions) {
        free(batch);
        return NULL;
    }

    return batch;
}

void destroy_batch(Batch** batch) {
    for (size_t i = 0; i < (*batch)->count; ++i) {
        Transaction* transaction = &(*batch)->transactions[i];
        destroy_node(&transaction->node);
    }

    free((*batch)->transactions);
    free(*batch);
    *batch = NULL;
}

void populate_batch(Batch** batch, size_t capacity) {
    if (!*batch || (*batch)->count >= capacity) return;

    for (size_t i = 0; i < capacity; ++i) {
        Node* node = create_node();
        if (!node) break;

        generate_unique_id(node->buffer, i);
        node->value = rand() % 10000 + 1; // random number within range 1-10000

        Transaction* transaction = &((*batch)->transactions[i]);
        transaction->node = node;
        transaction->timestamp = time(NULL);
    }

    (*batch)->count = capacity;
}
```

