#include <time.h>
#include <pthread.h>

typedef struct {
    double value;
    int id;
    char* str;
} data_t;

void generate_random(double* num, int min, int max) {
    *num = (rand() % (max - min + 1)) + min;
}

char* generate_string(int length) {
    char* str = (char*)malloc(length * sizeof(char));
    for (int i = 0; i < length; ++i) {
        str[i] = rand() % 26 + 'a'; // ASCII lowercase letters
    }
    str[length] = '\0';
    return str;
}

void* init_element(void* arg) {
    data_t* element = (data_t*)arg;
    generate_random(&element->value, 0, 1);
    element->id = rand() % 10000 + 1; // Random integer between 1 and 10,000
    element->str = generate_string(rand() % 50 + 10);
    return NULL;
}

void init_structures(data_t** floats, data_t** chars, data_t** datas, int num_elements) {
    pthread_t* threads = (pthread_t*)malloc(num_elements * 3 * sizeof(pthread_t));

    for (int i = 0; i < num_elements; ++i) {
        floats[i] = malloc(sizeof(data_t));
        chars[i] = malloc(sizeof(data_t));
        datas[i] = malloc(sizeof(data_t));
    }

    for (int i = 0; i < num_elements; ++i) {
        pthread_create(&threads[3 * i], NULL, init_element, floats[i]);
        pthread_create(&threads[3 * i + 1], NULL, init_element, chars[i]);
        pthread_create(&threads[3 * i + 2], NULL, init_element, datas[i]);
    }

    for (int i = 0; i < num_elements * 3; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(threads);
}

void free_memory(data_t** floats, data_t** chars, data_t** datas, int num_elements) {
    for (int i = 0; i < num_elements; ++i) {
        free(floats[i]);
        free(chars[i]);
        free(datas[i]);
    }
}
