void* allocate_and_init(size_t size, size_t element_size) {
    void *ptr = malloc(size * element_size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    memset(ptr, 0, size * element_size);
    return ptr;
}

void generate_unique_values(void *data, size_t size, size_t element_size) {
    int *keys = data;
    long *offsets = (long *)((char *)data + sizeof(int) * size);
    for (size_t i = 0; i < size; ++i) {
        keys[i] = rand() % MAX_INT;
        offsets[i] = i * element_size;
    }
}

void serialize(const char *filename, void *data, size_t size, size_t element_size) {
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    memcpy((char *)data, MAP_FAILED, size);
    msync(data, size, MS_SYNC);
    close(fd);
}

void deserialize(const char *filename, void **data, size_t *size, size_t element_size) {
    int fd = open(filename, O_RDONLY, 0);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    void *mapped_data = mmap(NULL, *size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (mapped_data == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    *data = mapped_data;
    *size *= element_size;
}

