public class ConfigGenerator {
    private static final Logger LOGGER = LoggerFactory.getLogger(ConfigGenerator.class);

    public static void main(String[] args) {
        if (args.length != 3) {
            System.err.println("Usage: java ConfigGenerator <directory> <configFileName> <outputZipFile>");
            return;
        }

        String directory = args[0];
        String configFileName = args[1];
        String outputZipFile = args[2];

        Path dirPath = Paths.get(directory);
        try {
            if (!Files.exists(dirPath)) {
                Files.createDirectory(dirPath);
            }

            Map<String, String> configData = new HashMap<>(); // Populate with data fetched from external sources
            generateConfigFile(Paths.get(directory, configFileName), configData);

            ZipOutputStream zipOut = new ZipOutputStream(new FileOutputStream(outputZipFile));
            try {
                ZipUtil.packDirectory(dirPath, zipOut, "");
            } finally {
                if (zipOut != null) {
                    zipOut.close();
                }
            }
        } catch (IOException e) {
            LOGGER.error("Error occurred while generating configuration or ZIP file", e);
        }

        try {
            Files.deleteIfExists(Paths.get(directory, configFileName));
        } catch (IOException e) {
            LOGGER.warn("Failed to delete temporary configuration file: {}", configFileName, e);
        }
    }

    private static void generateConfigFile(Path path, Map<String, String> data) throws IOException {
        try (BufferedWriter writer = Files.newBufferedWriter(path)) {
            for (Map.Entry<String, String> entry : data.entrySet()) {
                writer.write(entry.getKey() + "=" + entry.getValue());
                writer.newLine();
            }
        }
    }
}
```

