[' Here's a simplified C program that meets your requirements. I've used the `getopt` library for command-line argument parsing and `stdlib` for memory management. The logging is done using the `printf` function, which is a basic approach. For a more robust logging framework, consider using libraries like `log4cplus`, `spdlog`, or `boost::log`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <getopt.h>

struct entry {
    uint32_t key;
    uint64_t offset;
};

void log(const char *message) {
    printf("%s\n", message);
}

void die(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

struct entry *init_entries(size_t size, uint32_t min, uint32_t max) {
    struct entry *entries = malloc(sizeof(struct entry) * size);
    if (!entries) die("Memory allocation failure");

    for (size_t i = 0; i < size; ++i) {
        entries[i].key = rand() % (max - min + 1) + min;
        entries[i].offset = rand();
    }

    return entries;
}

void read_config(const char *filename, struct entry **entries, size_t *num_entries) {
    FILE *file = fopen(filename, "r");
    if (!file) die("Failed to open configuration file");

    char line[1024];
    size_t num_valid_entries = 0;

    while (fgets(line, sizeof(line), file)) {
        char *token = strtok(line, " \t\n");
        if (!token) continue;

        uint32_t key;
        uint64_t offset;
        sscanf(token, "%u", &key);
        if (sscanf(NULL, "%llu", &offset) != 1) {
            log("Invalid entry: %s\n", line);
            continue;
        }

        struct entry *new_entry = realloc(*entries, sizeof(struct entry) * ++*num_entries);
        if (!new_entry) die("Memory allocation failure");
        new_entry->key = key;
        new_entry->offset = offset;
        *entries = new_entry;
    }

    fclose(file);
    *num_entries -= num_valid_entries % BUFSIZ; // Ensure proper alignment
}

int main(int argc, char **argv) {
    int opt;
    const char *config_filename = NULL;
    const char *destination_dir = ".";

    static struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"version", no_argument, 0, 'v'},
        {"dest", required_argument, 0, 'd'},
        {0, 0, 0, 0}
    };

    while ((opt = getopt_long(argc, argv, "hvd:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'h':
                printf("Usage: %s [OPTIONS] CONFIG_FILE\n", argv[0]);
                printf("\t-h --help          Display this help message and exit.\n");
                printf("\t-v --version        Print version information and exit.\n");
                printf("\t-d --dest=DIR        Set the destination directory for output files.\n");
                exit(EXIT_SUCCESS);
            case 'v':
                log("Version: 1.0\n");
                exit(EXIT_SUCCESS);
            case 'd':
                destination_dir = optarg;
                break;
            case '?':
                if (isprint(optopt)) log("Unknown option `-%c'.\n", optopt);
                else log("Unknown option character `\\x%x'.\n", optopt);
                exit(EXIT_FAILURE);
        }
    }

    if (optind < argc) config_filename = argv[optind];
    if (!config_filename) die("No configuration file provided");

    struct entry *entries;
    size_t num_entries = 0;
    read_config(config_filename, &entries, &num_entries);

    // Continue with processing the entries...
}
```']

