async fn fetch_config(api_url: &str, validate_cert: bool) -> Result<Value, reqwest::Error> {
    let client = Client::builder()
        .timeout(Duration::from_secs(10))
        .build()?;

    let request = RequestBuilder::get(Url::parse(api_url).unwrap())
        .header("Accept", "application/json")
        .build();

