}

void add_to_pool(pool* pool, element* element) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count < pool->capacity) {
        pool->elements[pool->count++] = element;
    } else {
        fprintf(stderr, "Pool is full\n");
    }
    pthread_mutex_unlock(&pool->lock);
}

element* get_from_pool(pool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count > 0) {
        element* element = &pool->elements[--pool->count];
        return element;
    } else {
        fprintf(stderr, "Pool is empty\n");
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

void free_pool(pool* pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        free_element(pool->elements[i]);
    }
    free(pool->elements);
    pthread_mutex_destroy(&pool->lock);
}
