} Record;

struct HashTable {
    size_t capacity;
    size_t count;
    Record* table;
};

void init_hash_table(struct HashTable* table, size_t capacity) {
    if (capacity < 4 || capacity > UINT32_MAX / sizeof(Record)) {
        fprintf(stderr, "Invalid hash table capacity\n");
        exit(EXIT_FAILURE);
    }

    table->capacity = capacity;
    table->count = 0;
    table->table = calloc(capacity, sizeof(Record));
}

uint64_t hash(const Record* record) {
    uint64_t hash = 5381;
    const char* key = (const char*)&record->value;

    for (size_t i = 0; i < sizeof(Record); ++i) {
        hash = ((hash << 5) + hash) + key[i]; /* hash * 33 + c */
    }

    return hash % table->capacity;
}

bool add_record(struct HashTable* table, const Record* record) {
    size_t index = hash(record);

    for (Record* current = table->table + index; current != table->table + table->capacity; current++) {
        if (!current->hash || current->hash == record->hash && current->value == record->value) {
            return false;
        }
        if (!current->hash) {
            *current = *record;
            current->hash = record->hash;
            table->count++;
            return true;
        }
    }

    // Handle overflow or underflow here by adjusting the hash table capacity and rehashing records.

    return false;
}

void free_record(Record* record) {
    free(record);
}

void free_hash_table(struct HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Record* current = table->table + i;
        if (current && current->value) {
            free_record(current);
        }
    }
    free(table->table);
}
