template <typename T>
class MemoryPool {
public:
    MemoryPool(size_t blockSize, size_t numBlocks) : _blockSize(blockSize), _numBlocks(numBlocks), _freeList(nullptr) {}

    T* allocate() {
        if (_freeList == nullptr) {
            _extend();
        }
        T* result = _freeList;
        _freeList = _freeList->next;
        return result;
