```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct Node {
    struct Node* next;
    int value;
    bool circular_ref;
} Node;

typedef struct Item {
    int key;
    Node* node;
} Item;

Node* create_node(int value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    new_node->value = value;
    new_node->next = NULL;
    new_node->circular_ref = false;
    return new_node;
}

void link_nodes(Node* current, Node* next) {
    if (current && next) {
        if (!current->next) {
            current->next = next;
        } else if (next != current) {
            Node* temp = current->next;
            while (temp && temp != current) {
                temp = temp->next;
            }
            if (!temp) {
                current->next = next;
            }
        }
    }
}

Item* create_item(int key) {
    Item* new_item = (Item*)malloc(sizeof(Item));
    if (!new_item) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    new_item->key = key;
    new_item->node = create_node(key);
    return new_item;
}

void populate_items(Item** items, int size, int* values) {
    for (int i = 0; i < size; ++i) {
        if (!items[i]) {
            items[i] = create_item(values[i]);
        }
        Node* current_node = items[i]->node;
        for (int j = 0; j < i; ++j) {
            if (j != i && items[j]) {
                link_nodes(current_node, items[j]->node);
            }
        }
    }
}
```

