    int value;
};

bool allocateAndInitRecords(size_t num_records, void* buffer, size_t buffer_size, std::vector<int>& keys, std::vector<int>& offsets, std::vector<Record>& records) {
    if (buffer_size < num_records * RECORD_SIZE) {
        return false;
