    char* data = static_cast<char*>(buffer);
    auto aligned_keys = reinterpret_cast<int*>(std::align(ALIGNMENT, sizeof(int), data));
    auto aligned_offsets = aligned_keys + keys.size();
    auto aligned_records = aligned_offsets + offsets.size();

    std::unordered_map<int, bool> key_map;

    for (size_t i = 0; i < num_records; ++i) {
        Record& record = records[i];
