#define MEASUREMENTS_MIN 10
#define MEASUREMENTS_MAX 10000
#define CHAR_ARRAY_SIZE 64
#define PRECISION 0.000001 // Precision threshold

void* aligned_malloc(size_t size, size_t alignment) {
    void *ptr = malloc(size + alignment);
    if (ptr != NULL) {
        uintptr_t aligned_ptr = (uintptr_t)ptr + alignment - (uintptr_t)ptr % alignment;
        memmove(aligned_ptr, ptr, size);
        return aligned_ptr;
    }
    return NULL;
}

void init_arrays(float* float_array, char** char_array, measurement* measurements, size_t float_size, size_t char_size, size_t measurements_size) {
    if (float_size < FLOAT_ARRAY_MIN || float_size > FLOAT_ARRAY_MAX) {
        fprintf(stderr, "Invalid float array size\n");
        exit(1);
    }

    float_array = aligned_malloc(float_size * sizeof(float), 64); // Align to cache line boundary

    for (size_t i = 0; i < float_size; ++i) {
        float_array[i] = 0.0f;
    }

    if (char_size < CHAR_ARRAY_SIZE || char_size % sizeof(char) != sizeof(char)) {
        fprintf(stderr, "Invalid char array size\n");
        exit(1);
    }

    char_array = malloc(char_size * sizeof(char*));
    for (size_t i = 0; i < char_size; ++i) {
        char_array[i] = aligned_malloc(CHAR_ARRAY_SIZE, sizeof(char));
        memset(char_array[i], 0, CHAR_ARRAY_SIZE);
    }

    if (measurements_size < MEASUREMENTS_MIN || measurements_size > MEASUREMENTS_MAX) {
        fprintf(stderr, "Invalid measurements size\n");
        exit(1);
    }

    measurements = malloc(measurements_size * sizeof(measurement));
    for (size_t i = 0; i < measurements_size; ++i) {
        measurements[i].value = 0.0;
        strcpy(measurements[i].unit, "");
        measurements[i].timestamp = 0;
    }
}

