uint64_t hash(const char* str) {
    uint64_t hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % (UINT64_MAX / sizeof(int));
}

void set_record_values(record* records, size_t num_records, int min_value, int max_value) {
