        geom[i].value = min + rand() / (RAND_MAX / (max - min));
        strcpy(geom[i].buffer, str);
    }
}

void resize_geometries(geometries* geoms, int new_capacity) {
    if (new_capacity <= geoms->size) {
        fprintf(stderr, "Error: New capacity must be greater than the current size\n");
        return;
    }

    geometry* temp = (geometry*)realloc(geoms->data, new_capacity * sizeof(geometry));
    if (!temp) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }
    geoms->data = temp;
    geoms->capacity = new_capacity;
}

void free_geometries(geometries* geoms) {
    free(geoms->data);
    geoms->size = 0;
    geoms->capacity = 0;
}
