```java
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.regex.Pattern;
import java.util.concurrent.ConcurrentHashMap;

public class HashUtil {
    private static final ConcurrentHashMap<String, byte[]> cache = new ConcurrentHashMap<>();
    private static final Pattern NON_ALPHANUMERIC = Pattern.compile("[^A-Za-z0-9]");

    public static byte[] hash(String input, String algorithm) throws Exception {
        // Logging and validation omitted for brevity
        String processedInput = NON_ALPHANUMERIC.matcher(input).replaceAll("");
        if (cache.containsKey(processedInput)) {
            return cache.get(processedInput);
        }

        MessageDigest digest = MessageDigest.getInstance(algorithm);
        digest.update(processedInput.getBytes(StandardCharsets.UTF_8));
        byte[] result = digest.digest();
        cache.putIfAbsent(processedInput, result);
        return result;
    }
}
```

