#include <iostream>
#include <memory>
#include <mutex>
#include <new>
#include <string>
#include <vector>
#include <cstdlib>

struct Element {
    double value;
    std::string str;
    int integer;

    Element(double v, const std::string& s, int i) : value(v), str(s), integer(i) {}
};

class Cache {
public:
    struct Node {
        Element data;
        std::unique_ptr<Node> next;
        std::unique_ptr<char[]> str;

        Node(Element&& d, std::unique_ptr<Node> n) : data(std::move(d)), next(std::move(n)) {}
    };

    void insert(const Element& element) {
        std::lock_guard<std::mutex> lock(m_);

        auto it = head_.get();
        while (it && it->data.value > element.value) it = it->next.get();

        auto newNode = std::make_unique<Node>(std::move(element), std::move(it->next));
        if (!head_) head_ = std::move(newNode);
        else it->next = std::move(newNode);
    }

    Element* find(double value) {
        std::lock_guard<std::mutex> lock(m_);

        auto it = head_.get();
        while (it && it->data.value < value) it = it->next.get();
        return it ? &it->data : nullptr;
    }

private:
    std::unique_ptr<Node> head_;
    std::mutex m_;
};

void log(const char* message, ...) {
    // Implement logging system here
}

int main() {
    Cache cache;

    // Insert elements into the cache
    for (size_t i = 0; i < 1000; ++i) {
        auto element = Element(i * 0.1, std::to_string(i), i);
        cache.insert(element);
    }

    // Find and log elements from the cache
    for (size_t i = 0; i < 1000; ++i) {
        auto it = cache.find(i * 0.1);
        if (it) log("Found element: value={}, str={}, integer={}\n", it->value, it->str.c_str(), it->integer);
    }

    return 0;
}
```

