void* mem_alloc(struct memory_pool* pool, size_t size) {
    if (size > pool->capacity) {
        void* new_pool = realloc(pool->pool, size * 2);
        if (!new_pool) return NULL;
        pool->capacity *= 2;
        pool->pool = new_pool;
    }
    return pool->pool + pool->allocated;
}

void mem_free(struct memory_pool* pool, void* ptr) {
    pool->allocated -= (size_t)(ptr - pool->pool);
}

data_item* create_data_item() {
    data_item* item = (data_item*)mem_alloc(&g_memory_pool, sizeof(data_item));
    if (!item) return NULL;

    item->timestamp = time(NULL);
    item->status_code = DEFAULT_STATUS_CODE;
    item->data = (char*)mem_alloc(&g_memory_pool, MAX_STRING_LENGTH + 1);
    if (!item->data) {
        free(item);
        return NULL;
    }
