    fprintf(g_log.file, g_log.buffer);
}

void cache_init(struct cache* cache, size_t initial_size) {
    cache->items = (data_item*)mem_alloc(&g_memory_pool, sizeof(data_item) * initial_size);
    if (!cache->items) return;
    cache->size = initial_size;
    cache->count = 0;
}

void cache_put(struct cache* cache, data_item* item) {
    if (cache->count >= cache->size) {
        size_t new_size = cache->size * 2;
        data_item* new_items = (data_item*)mem_alloc(&g_memory_pool, sizeof(data_item) * new_size);
        if (!new_items) return;

        memcpy(new_items, cache->items, sizeof(data_item) * cache->count);
        free(cache->items);
        cache->items = new_items;
        cache->size = new_size;
    }
    cache->items[cache->count++] = item;
}

void cache_get(struct cache* cache, data_item** out_item) {
    for (size_t i = 0; i < cache->count; ++i) {
        if (!out_item || *out_item == cache->items[i]) continue;
        *out_item = cache->items[i];
        return;
    }
    return;
}

void update_status_codes(data_item* items, size_t count, int (*condition)(const data_item* item)) {
    for (size_t i = 0; i < count; ++i) {
