```cpp
#include <iostream>
#include <vector>
#include <cstdlib>
#include <ctime>
#include <cstring>
#include <sys/mman.h>
#include <sys/resource.h>

// Define record and config structures
struct Record {
    int value;
    long offset;
    int key;
    short index;
};

struct Config {
    int min_value;
    int max_value;
    int transformation_function(int value);
};

// Custom malloc function for aligned memory allocation
void* aligned_malloc(size_t size, size_t alignment) {
    void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (ptr == MAP_FAILED) {
        std::cerr << "Failed to allocate memory" << std::endl;
        exit(EXIT_FAILURE);
    }

    size_t new_size = ((size + alignment - 1) / alignment) * alignment;
    char* aligned_ptr = static_cast<char*>(ptr);
    if (realloc(aligned_ptr, new_size) == NULL) {
        std::cerr << "Failed to reallocate memory" << std::endl;
        exit(EXIT_FAILURE);
    }

    return aligned_ptr;
}

// Custom free function for aligned memory deallocation
void aligned_free(void* ptr) {
    if (munmap(ptr, sizeof(char)) == -1) {
        std::cerr << "Failed to free memory" << std::endl;
        exit(EXIT_FAILURE);
    }
}

// Function to initialize the required arrays and perform transformations
void init_and_transform(int max_records, int config_limit, bool free_all, Config* config) {
    long* offsets = static_cast<long*>(aligned_malloc(max_records * sizeof(long), 64));
    int* keys = static_cast<int*>(aligned_malloc(max_records * sizeof(int), 64));
    short* indices = static_cast<short*>(aligned_malloc((max_records + 1) * sizeof(short), 16));
    Record* records = static_cast<Record*>(aligned_malloc(max_records * sizeof(Record), 64));
    Config* configs = static_cast<Config*>(aligned_malloc(config_limit * sizeof(Config), 64));

    // Initialize offset, key, and index arrays
    for (int i = 0; i < max_records; ++i) {
        indices[i] = static_cast<short>(i);
    }

    // Initialize record array with random int values
    std::srand(std::time(nullptr));
    for (int i = 0; i < max_records; ++i) {
        records[i].value = std::rand() % config->max_value + config->min_value;
    }

    // Initialize config array with default values or user-provided configurations
    for (int i = 0; i < config_limit; ++i) {
        configs[i].min_value = 0;
        configs[i].max_value = 100;
        configs[i].transformation_function = [](int value) { return value * 2; };
    }

    // Perform transformations on each record's int value based on its corresponding key, index, and configuration parameters
    for (int i = 0; i < max_records; ++i) {
        Record& record = records[indices[i]];
        Config& config = configs[record.key];
        record.value = config.transformation_function(record.value);
    }

    if (free_all) {
        aligned_free(offsets);
        aligned_free(keys);
        aligned_free(indices);
        aligned_free(records);
        aligned_free(configs);
    }
}

int main() {
    int max_records = 10;
    int config_limit = 5;
    bool free_all = false;

    Config config{2, 100, [](int value) { return value * 3; }};

    init_and_transform(max_records, config_limit, free_all, &config);

    // Print transformed records for debugging purposes
    for (int i = 0; i < max_records; ++i) {
        std::cout << "Record[" << i << "].value: " << records[i].value << std::endl;
    }

    return 0;
}
```

