```c
typedef struct {
    void* data;
    size_t size;
    struct mem_pool* next;
} mem_block;

struct mem_pool {
    mem_block head, tail;
    size_t block_size;
};

void init_mem_pool(struct mem_pool* pool, size_t block_size) {
    pool->head.data = NULL;
    pool->tail.data = NULL;
    pool->head.next = &pool->tail;
    pool->block_size = block_size;
}

mem_block* alloc_from_pool(struct mem_pool* pool) {
    if (pool->head.next != &pool->tail) {
        mem_block* block = pool->head.next;
        pool->head.next = block->next;
        block->next = NULL;
        return block;
    }
    return NULL;
}

void free_to_pool(struct mem_pool* pool, void* data) {
    mem_block* block = (mem_block*)malloc(sizeof(mem_block));
    block->data = data;
    block->size = 0; // Set size to zero for easier tracking
    block->next = pool->head.next;
    pool->head.next = block;
}
