        if (isPrime(i)) primes.push_back(i);
    }

    keys.resize(keys.size(), 0);
    std::list<int> availablePrimes(primes.begin(), primes.end());

    for (int i = 0; i < keys.size(); ++i) {
        if (availablePrimes.empty()) {
