    if (list->size == 0) {
        list->head->next = new_node;
        new_node->prev = list->head;
        list->tail = new_node;
    } else {
        new_node->prev = list->tail;
        list->tail->next = new_node;
        list->tail = new_node;
        list->tail->next->prev = new_node;
    }

    list->size++;
    unlock(list);
}

void delete_node(List* list, Node* node) {
