struct MemoryPool {
    void* data;
    size_t capacity;
    size_t allocated;
};

void* mempool_alloc(struct MemoryPool* pool, size_t size) {
    if (pool->allocated + size > pool->capacity) {
        pool->data = realloc(pool->data, pool->capacity * 2);
        pool->capacity *= 2;
    }

    void* result = pool->data + pool->allocated;
    pool->allocated += size;
    return result;
}

void mempool_free(struct MemoryPool* pool, void* ptr) {
    pool->allocated -= (ptr - pool->data);
}

struct MemoryPool mempool = {NULL, 0};

