        int retries = 3;
        while (retries > 0) {
            sleep(pow(2, retries - 1));

            if (convertJpegToPdf(inputFilePath, outputFilePath)) {
                // Log success and close log file
                storeLogs("Conversion successful", time(NULL));
                fclose(logFile);
                return 0;
            }

            retries--;
