#include <stdio.h>
#include <stdlib.h>
#include <ffi.h>

typedef struct {
    void *ptr;
    ffi_cif cif;
} ffi_state_t;

void init_ffi(const char *js_file) {
    FILE *fp = fopen(js_file, "r");
    if (!fp) {
        perror("Error opening JS file");
        exit(1);
    }

    size_t len;
    char *js_code = malloc(len + 1);
    fseek(fp, 0, SEEK_END);
    len = ftell(fp);
    rewind(fp);
    fread(js_code, 1, len, fp);
    js_code[len] = '\0';
    fclose(fp);

    ffi_state_t *ffi_state = malloc(sizeof(ffi_state_t));
    ffi_cif *cif = &ffi_state->cif;

    ffi_prep_cif(cif, FFI_DEFAULT_ABI, 0, NULL, NULL, NULL, NULL);
    ffi_parse_source(cif, js_code, len, NULL);

    void *js_module = ffi_load("node", NULL);
    if (!js_module) {
        perror("Error loading Node.js module");
        exit(1);
    }

    ffi_state->ptr = ffi_get_closure(cif, js_module);
}

void call_js_function(ffi_state_t *ffi_state, const char *name, void **args, size_t arg_count) {
    ffi_call(*ffi_state->cif, ffi_state->ptr, args, arg_count);
}
