void init_data(int num_records, int min_key, int max_key, long* offsets, int* keys, Record** records) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    *offsets = malloc((num_records + 1) * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        exit(EXIT_FAILURE);
    }

    *keys = malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    *records = malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(*keys);
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&mutex);
        while ((*keys)[i] != 0 && (*keys)[i] < min_key || (*keys)[i] > max_key) {
            pthread_mutex_unlock(&mutex);
            usleep(100);
            pthread_mutex_lock(&mutex);
        }
        (*keys)[i] = min_key + i;
        (*offsets)[i + 1] = (*offsets)[i] + sizeof(Record) * i;
        (*records)[i].key = (*keys)[i];
        (*records)[i].offset = (*offsets)[i];
        pthread_mutex_unlock(&mutex);
    }
}
