        exit(EXIT_FAILURE);
    }
    memset(*data, 0, vertex_count * element_size);
}

void serialize(const char* file, void* data, size_t element_size, int vertex_count) {
    FILE* fp = fopen(file, "wb");
    if (!fp) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(data, element_size, vertex_count, fp);
    fclose(fp);
}

void deserialize(const char* file, void* data, size_t element_size, int* vertex_count) {
    FILE* fp = fopen(file, "rb");
    if (!fp) {
        perror("Failed to open file for reading");
        return;
    }

    fseek(fp, 0, SEEK_END);
    *vertex_count = ftell(fp) / element_size;
    rewind(fp);

    fread(data, element_size, *vertex_count, fp);
    fclose(fp);
}

