#include <time.h>

typedef struct Record {
    int value;
} Record;

void* init_long_array(size_t size, size_t lower_bound, size_t upper_bound) {
    long *arr = malloc((size + sizeof(long) - 1) & ~(sizeof(long) - 1)); // Align for cache locality
    if (!arr) return NULL;

    for (size_t i = lower_bound; i < size; ++i) {
        arr[i] = (long)i; // Ensure no overflow
        if (arr[i] < lower_bound || arr[i] >= upper_bound) {
            free(arr);
            return NULL;
        }
    }

    return arr;
}

void* init_int_array(size_t size, size_t lower_bound, size_t upper_bound) {
    int *arr = malloc((size + sizeof(int) - 1) & ~(sizeof(int) - 1)); // Align for cache locality
    if (!arr) return NULL;

    for (size_t i = lower_bound; i < size; ++i) {
        arr[i] = (int)i; // Ensure no overflow
        if (arr[i] < lower_bound || arr[i] >= upper_bound) {
            free(arr);
            return NULL;
        }
    }

    return arr;
}

void* init_record_array(size_t size, size_t num_records, size_t lower_bound, size_t upper_bound) {
    Record *arr = malloc(num_records * sizeof(Record));
    if (!arr) return NULL;

    pthread_t threads[num_records];
    for (size_t i = 0; i < num_records; ++i) {
        arr[i].value = lower_bound + i; // Ensure no overflow
        pthread_create(&threads[i], NULL, [](void* arg) {
            srand((unsigned int)arg);
            while (arr[(size_t)arg].value < upper_bound) arr[(size_t)arg].value = rand() % (upper_bound - lower_bound + 1) + lower_bound;
            return NULL;
        }, (void*)i);
    }

    for (size_t i = 0; i < num_records; ++i) pthread_join(threads[i], NULL);

    return arr;
}
```

