constexpr size_t MAX_ARRAY_SIZE = 100000;
constexpr size_t MAX_RECORDS = 100000;
constexpr int MIN_VALUE = 0;
constexpr int MAX_VALUE = 100;
constexpr float PRECISION_FACTOR = 0.01f; // Adjust based on data volatility and system load

std::vector<long> offsets(MAX_ARRAY_SIZE);
std::vector<int> keys(MAX_RECORDS);
std::vector<float> precisions(MAX_RECORDS);
std::vector<Record> records(MAX_RECORDS);

struct Record {
    int value;
    long timestamp;
    float precision;
};

std::mutex mtx;
std::atomic<size_t> recordIndex{0};
std::atomic<size_t> uniqueValues{0};
std::vector<Record> cache;

void setValue(size_t index) {
    int value;
    do {
        value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
    } while (std::find(keys.begin(), keys.end(), value) != keys.end && uniqueValues < MAX_RECORDS);

    if (uniqueValues >= MAX_RECORDS) {
        PRECISION_FACTOR *= 2.0f; // Adjust precision to generate more unique values
    }

    uniqueValues++;

    std::lock_guard<std::mutex> lock(mtx);
    keys[recordIndex] = value;
    records[recordIndex].value = value;
    records[recordIndex].timestamp = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();
    records[recordIndex].precision = PRECISION_FACTOR;
    offsets[recordIndex] = sizeof(long) * recordIndex + sizeof(int) * recordIndex + sizeof(float) * recordIndex;
    recordIndex++;
}

void serialize() {
    std::ofstream file("records.dat", std::ios::binary | std::ios::trunc);
    if (!file.is_open()) {
        std::cerr << "Error opening file" << std::endl;
        return;
    }

    for (const auto& record : records) {
        std::stringstream ss;
        ss << offsets[recordIndex - 1] << ','
           << record.value << ','
           << record.timestamp << ','
           << record.precision << '\n';
        file << ss.str();
    }
}

void deserialize() {
    std::ifstream file("records.dat", std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Error opening file" << std::endl;
        return;
    }

    Record record;
    size_t offset = 0;
    while (file >> offset) {
        file >> record.value >> record.timestamp >> record.precision;
        // Add appropriate synchronization here to maintain data consistency during deserialization
        records[recordIndex++] = record;
        offsets[recordIndex - 1] = offset;
    }
}
```

