    RedBlackTree(size_t maxNodes, size_t threshold) : root(nullptr), maxNodes_(maxNodes), threshold_(threshold) {}

    void* operator new(std::size_t size) {
        void* ptr = ::operator new(size);
        if (mem_usage_ + size > threshold_) {
