        fprintf(stderr, "Invalid size or data per entry\n");
        return NULL;
    }

    readings = malloc(sizeof(float) * size * data_per_entry);
    if (!readings) {
        fprintf(stderr, "Memory allocation for readings failed\n");
        goto cleanup;
    }

    timestamps = malloc(sizeof(time_t) * size);
    if (!timestamps) {
        fprintf(stderr, "Memory allocation for timestamps failed\n");
        free(readings);
        goto cleanup;
    }

    sensor_data_array = malloc(sizeof(sensor_data) * size);
    if (!sensor_data_array) {
        fprintf(stderr, "Memory allocation for sensor data failed\n");
        free(timestamps);
        free(readings);
        goto cleanup;
    }

    for (size_t i = 0; i < size; ++i) {
        for (size_t j = 0; j < data_per_entry; ++j) {
            validate_timestamp(timestamps[i], start, end);
            sensor_data_array[i].timestamp = timestamps[i];
            sensor_data_array[i].reading = readings[i * data_per_entry + j];
