[" Here's a simplified implementation of the multi-tiered data structure in C, focusing on the key aspects you've mentioned. Note that this is a basic version and may require further optimization for specific use cases.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    size_t max_capacity;
    size_t current_size;
    size_t max_string_length;
    int *allowed_status_codes;
    size_t allowed_status_codes_count;
    struct entry **content;
} multi_tiered_data_structure;

typedef struct {
    char string[256];
    int status;
} entry;

multi_tiered_data_structure *create(size_t initial_capacity) {
    multi_tiered_data_structure *mds = malloc(sizeof(multi_tiered_data_structure));
    mds->max_capacity = initial_capacity;
    mds->current_size = 0;
    mds->max_string_length = 256;
    mds->allowed_status_codes = calloc(10, sizeof(int)); // Example: Allowing 10 status codes
    mds->allowed_status_codes_count = 10;
    mds->content = malloc(initial_capacity * sizeof(entry*));
    return mds;
}

void insert(multi_tiered_data_structure *mds, const char *string, int status) {
    if (mds->current_size >= mds->max_capacity) {
        mds->max_capacity *= 2;
        mds->content = realloc(mds->content, mds->max_capacity * sizeof(entry*));
    }

    int hash = MurmurHash3_x64_128(string, strlen(string), 0) % mds->max_capacity;

    for (size_t i = 0; i < mds->max_capacity; ++i) {
        if (!mds->content[hash ^ i]) {
            mds->content[hash ^ i] = malloc(sizeof(entry));
            strcpy(mds->content[hash ^ i]->string, string);
            mds->content[hash ^ i]->status = status;
            ++mds->current_size;
            break;
        }
    }
}

entry *find_by_index(multi_tiered_data_structure *mds, size_t index) {
    if (index >= mds->current_size) return NULL;
    return mds->content[index];
}

entry *find_by_string(multi_tiered_data_structure *mds, const char *string) {
    int hash = MurmurHash3_x64_128(string, strlen(string), 0) % mds->max_capacity;

    for (size_t i = 0; i < mds->max_capacity; ++i) {
        if (!mds->content[hash ^ i]) continue;
        if (strcmp(mds->content[hash ^ i]->string, string) == 0) return mds->content[hash ^ i];
    }
    return NULL;
}

void destroy(multi_tiered_data_structure *mds) {
    for (size_t i = 0; i < mds->max_capacity; ++i) {
        if (!mds->content[i]) continue;
        free(mds->content[i]);
    }
    free(mds->content);
    free(mds->allowed_status_codes);
    free(mds);
}
```

This code creates a multi-tiered data structure with the specified requirements. It uses MurmurHash for hashing, exponential growth when resizing the content block, and simple indexing for fast lookups. The destroy function safely deallocates all memory when the data structure is no longer needed."]

[" Here's a C++ code implementation using a custom memory pool for managing dynamic memory allocation efficiently. The code uses `std::vector` for arrays of 'int' keys and 'long' offset values, and a `std::list` for the record objects to minimize memory fragmentation.

```cpp
#include <iostream>
#include <vector>
#include <list>
#include <new>
#include <cstdlib>

struct Record {
    int value;
    long offset;
    int key;
};

class MemoryPool {
public:
    MemoryPool(size_t recordSize) : _recordSize(recordSize), _freeList(), _usedMemory(0) {}

    Record* allocate() {
        if (_freeList.empty()) {
            auto newBlock = static_cast<Record*>(::operator new(getAllocatedSize()));
            _freeList.splice(_freeList.end(), std::list<Record*>());
            for (auto i = 0; i < _blockSize; ++i)
                _freeList.back()->value = 0;
            _usedMemory += getAllocatedSize();
        }
        auto result = _freeList.front();
        _freeList.pop_front();
        return result;
    }

    void deallocate(Record* record) {
        record->value = 0;
        _freeList.splice(_freeList.end(), std::list<Record*>(), record);
        _usedMemory -= getAllocatedSize();
    }

private:
    size_t getAllocatedSize() const { return _recordSize * _blockSize; }
    size_t _recordSize;
    size_t _blockSize = 1024; // Adjust this value to control the block size
    std::list<Record*> _freeList;
    size_t _usedMemory = 0;
};

void processRecords(const MemoryPool& pool, const std::vector<long>& offsets, const std::vector<int>& keys, std::vector<Record>& records) {
    for (size_t i = 0; i < offsets.size(); ++i) {
        auto record = pool.allocate();
        record->offset = offsets[i];
        record->key = keys[i];
        records[record->offset] = *record;
    }
}

void freeRecords(MemoryPool& pool, const std::vector<Record>& records) {
    for (const auto& record : records)
        pool.deallocate(&record);
}
```

In the provided code, `MemoryPool` is a custom memory pool class that manages reusable memory blocks efficiently. The `processRecords` function processes large-scale records using the memory pool, and the `freeRecords` function frees previously allocated memory when necessary.

You can adjust the block size in the MemoryPool constructor to control the trade-off between performance and resource usage. This implementation minimizes the impact on other components by reducing frequent allocations and handling potential growth in data size gracefully."]

