    printf("Service stopped with log message: %s\n", record->log_message);
    pthread_mutex_unlock(&record->lock);
    free(record->log_message);
    free(record);
    return NULL;
}

void start_service(Record* record) {
    pthread_t thread_id;
    if (num_records < max_records && pthread_create(&thread_id, NULL, service_routine, record)) {
        fprintf(stderr, "Failed to create thread\n");
    } else {
        records[num_records++] = record;
    }
}

void stop_service(size_t index) {
    if (index < num_records) {
        pthread_mutex_lock(&records_lock);
        Record* record = &records[index];
        start_service(record); // simulate restarting the service
        pthread_mutex_unlock(&records_lock);
    } else {
        fprintf(stderr, "Requested index out of bounds\n");
    }
}
