#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    double value;
    char* str;
    struct Node* prev;
    struct Node* next;
} Node;

Node* create_node(double value, const char* str) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    node->value = value;
    size_t len = strlen(str) + 1;
    node->str = (char*)malloc(len * sizeof(char));
    if (!node->str) {
        free(node);
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    memcpy(node->str, str, len);
    node->prev = NULL;
    node->next = NULL;
    return node;
}

void free_node(Node* node) {
    if (node) {
        free(node->str);
        free(node);
    }
}

void insert_after(Node* current, Node* new_node) {
    if (!current || !new_node) return;

    new_node->prev = current;
    new_node->next = current->next;

    if (current->next) current->next->prev = new_node;
    current->next = new_node;
}

void remove_node(Node* node) {
    if (!node || !node->prev || !node->next) return;

    node->prev->next = node->next;
    node->next->prev = node->prev;
    free_node(node);
}

void traverse(Node* head) {
    for (Node* current = head; current != NULL; current = current->next) {
        printf("Value: %.2f, String: %s\n", current->value, current->str);
    }
}

// Implement sorting functions and concurrent access management here.
```

