import java.util.concurrent.*;
import java.time.*;

public class UserSession {
    private final AtomicLong lastActiveTimestamp;

    public UserSession() {
        this.lastActiveTimestamp = new AtomicLong(System.currentTimeMillis());
    }

    public long getLastActiveTimestamp() {
        return lastActiveTimestamp.get();
    }

    public void updateLastActiveTimestamp(long timestamp) {
        lastActiveTimestamp.compareAndSet(this.lastActiveTimestamp.get(), System.currentTimeMillis() - timestamp);
    }
}

public class SessionManager {
    private final ConcurrentHashMap<String, UserSession> userSessions;

    public SessionManager() {
        this.userSessions = new ConcurrentHashMap<>();
    }

    public void trackActivity(String sessionID, long timestamp, boolean track) {
        UserSession userSession = userSessions.get(sessionID);

        if (track && userSession != null) {
            userSession.updateLastActiveTimestamp(timestamp);
        } else if (!userSessions.containsKey(sessionID)) {
            // No session found, do nothing
        }
    }
}
