class CustomMemoryPool {
public:
    void* allocate(size_t size) {
        if (freeList.empty()) {
            auto newBlock = operator new(headerSize + size);
            new (static_cast<char*>(newBlock) + headerSize) Header{freeList};
            freeList.push_back({size, newBlock + headerSize});
        }
        auto block = freeList.back();
        freeList.pop_back();
        return static_cast<char*>(block.second) + headerSize;
    }

    void deallocate(void* ptr, size_t size) {
        auto newHeader = reinterpret_cast<Header*>(static_cast<char*>(ptr) - headerSize);
        new (newHeader) Header{freeList};
        freeList.push_back({size, static_cast<char*>(ptr) - headerSize});
    }

private:
    struct Header {
        size_t size;
        Header* next;
    };

    std::vector<std::pair<size_t, void*>> freeList;
