// Custom hash function with good distribution and low collision rate
uint32_t hash(const void* key) {
    const uint32_t prime = 31;
    uint32_t hash = 0;
    const char* k = (const char*)key;

    for (size_t i = 0; i < strlen(k); ++i) {
        hash = (hash * prime + k[i]) & ((1ULL << 32) - 1);
    }

    return hash;
}

// Custom memory pool for small allocations
typedef struct MemBlock {
    size_t size;
    char* data;
    struct MemBlock* next;
} MemBlock;

MemBlock* mem_pool = NULL;

void* mem_alloc(size_t size) {
    if (size <= 64 * 1024) { // Max string length per record is 64KB
        MemBlock* block = mem_pool;

        if (!block) {
            block = malloc(sizeof(MemBlock));
            if (!block) return NULL;
            block->size = 0;
            block->next = mem_pool;
            mem_pool = block;
        }

        if (block->size == 0) {
            block->data = malloc(size);
            if (!block->data) return NULL;
            block->size = size;
            return block->data;
        }

        void* result = &((char*)block->data)[block->size];
        block->size += size;
        return result;
    }

    return malloc(size);
}

void mem_free(void* ptr) {
    if (ptr >= mem_pool && ptr < mem_pool->data + mem_pool->size) {
        MemBlock* block = mem_pool;
        block->size -= (uintptr_t)ptr - ((uintptr_t)block->data);
        if (block->size == 0) {
            free(block->data);
            mem_pool = block->next;
            free(block);
        }
