void mempool_init(struct MemPool *pool, size_t capacity) {
    pool->head.data = malloc(capacity);
    pool->tail.data = pool->head.data;
    pool->head.next = &pool->tail;
    pool->tail.next = &pool->head;
    pool->capacity = capacity;
}

MemBlock *mempool_alloc(struct MemPool *pool, size_t size) {
    if (size > pool->capacity) {
