```cpp
#include <iostream>
#include <vector>
#include <unordered_set>
#include <cstdlib>
#include <ctime>
#include <mutex>
#include <memory>

struct Point {
    int x;
    float y;
};

class MemoryManager {
private:
    std::vector<double> doubles;
    std::vector<std::string> strings;
    std::vector<Point> points;
    std::unordered_set<float> uniqueYs;
    std::mutex mtx;
    size_t totalMemory = 0;
    static constexpr size_t maxMemory = 10 * 1024 * 1024; // 10 MB

public:
    MemoryManager() {
        srand(time(nullptr));
    }

    void allocateDoubles(size_t count) {
        if (totalMemory + sizeof(double) * count > maxMemory) {
            std::cerr << "Error: Insufficient memory for doubles allocation." << std::endl;
            return;
        }
        doubles.resize(doubles.size() + count);
        totalMemory += sizeof(double) * count;
    }

    void allocateStrings(size_t count, size_t maxLength) {
        if (totalMemory + sizeof(char) * (count * maxLength)) > maxMemory) {
            std::cerr << "Error: Insufficient memory for strings allocation." << std::endl;
            return;
        }
        strings.resize(strings.size() + count);
        for (auto& str : strings) {
            str.resize(maxLength);
        }
        totalMemory += sizeof(char) * (count * maxLength);
    }

    void allocatePoints(size_t count) {
        if (totalMemory + sizeof(Point) * count > maxMemory) {
            std::cerr << "Error: Insufficient memory for points allocation." << std::endl;
            return;
        }
        points.resize(points.size() + count);
        totalMemory += sizeof(Point) * count;
    }

    void populatePoints(size_t count, float minY, float maxY) {
        std::unique_lock<std::mutex> lock(mtx);
        for (auto& point : points) {
            point.y = minY + static_cast<float>(rand()) / RAND_MAX * (maxY - minY);
            while (uniqueYs.count(point.y)) {
                point.y = minY + static_cast<float>(rand()) / RAND_MAX * (maxY - minY);
            }
            uniqueYs.insert(point.y);
        }
    }

    void deallocate() {
        doubles.clear();
        strings.clear();
        points.clear();
        uniqueYs.clear();
        totalMemory = 0;
    }
};
```

