    int event_type;
    char message[256];
} Event;

struct Node {
    Event event;
    struct Node* next;
};

static struct Node* timestamps = NULL;
static struct Node* events = NULL;
static size_t capacity = 0;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static FILE* logfile = NULL;

void log(const char* message) {
    if (logfile) {
        fprintf(logfile, "%s\n", message);
        fflush(logfile);
    }
}

void resize_arrays(size_t new_capacity) {
    struct Node* current = timestamps;
    struct Node** new_timestamps = malloc(new_capacity * sizeof(struct Node*));
    struct Node** new_events = malloc(new_capacity * sizeof(struct Node*));

    for (size_t i = 0; i < capacity && current != NULL; ++i) {
        new_timestamps[i] = current;
        new_events[i] = current->next;
        current = current->next;
    }

    free(timestamps);
    free(events);
    timestamps = new_timestamps;
    events = new_events;
    capacity = new_capacity;
}

void add_event(Event event) {
    pthread_mutex_lock(&lock);

    if (capacity == 0) {
        resize_arrays(16);
    }

    struct Node* current = timestamps[capacity - 1];
    current->event = event;
    events[capacity - 1] = malloc(sizeof(struct Node));
    events[capacity - 1]->next = NULL;
    events[capacity - 1]->event = event;
    ++capacity;

    log(asctime(ctime(&event.timestamp)));
    log(fmt("Event type: %d, Message: %s", event.event_type, event.message));

    pthread_mutex_unlock(&lock);
}

void init_logging(const char* filename) {
    logfile = fopen(filename, "w");
}
```

This code defines a linked list for each array (timestamps and events), with the ability to resize them when needed. The `add_event()` function is thread-safe due to the use of a mutex lock. A logging mechanism is also included, which writes event details to a specified log file.

Using a linked list for dynamic resizing has some trade-offs compared to other data structures like resizable arrays:

1. Memory Overhead: Linked lists have higher memory overhead due to the need for additional pointers to store next nodes.
2. Cache Locality: Accessing elements in a linked list can be less cache-friendly because of the irregular memory access pattern.
3. Ease of Implementation: Linked lists are generally easier to implement and extend, as they don't require reallocating large blocks of memory when resizing.']

