[" Here's a simplified version of the requested C function that addresses some of the given requirements. Due to the complexity and scope of the task, I've focused on implementing key features while keeping the code concise and readable.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    double value;
    char* str;
    size_t ref_count;
} Item;

typedef struct HashNode {
    Item item;
    struct HashNode* next;
} HashNode;

typedef struct {
    unsigned long capacity;
    unsigned long count;
    HashNode** table;
    pthread_mutex_t mutex;
} DynamicList;

DynamicList* dynamic_list_create(unsigned long capacity) {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->capacity = capacity;
    list->count = 0;
    list->table = calloc(capacity, sizeof(HashNode*));
    if (!list->table) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void dynamic_list_destroy(DynamicList* list) {
    for (unsigned long i = 0; i < list->capacity; ++i) {
        HashNode* node = list->table[i];
        while (node) {
            HashNode* next = node->next;
            free(node->item.str);
            free(node);
            node = next;
        }
    }

    free(list->table);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

unsigned long hash(const char* str) {
    unsigned long hash = 5381;
    for (size_t i = 0; str[i]; ++i)
        hash = ((hash << 5) + hash) + str[i]; /* hash * 33 + c */
    return hash % list->capacity;
}

Item* dynamic_list_get(DynamicList* list, const char* key) {
    unsigned long index = hash(key) % list->capacity;
    pthread_mutex_lock(&list->mutex);

    HashNode* node = list->table[index];
    while (node) {
        if (!strcmp(node->item.str, key)) {
            ++node->item.ref_count;
            pthread_mutex_unlock(&list->mutex);
            return &node->item;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void dynamic_list_put(DynamicList* list, Item item) {
    unsigned long index = hash(item.str) % list->capacity;
    pthread_mutex_lock(&list->mutex);

    HashNode** slot = &list->table[index];
    HashNode* node = malloc(sizeof(HashNode));
    if (!node) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    node->item = item;
    node->next = *slot;
    *slot = node;
    ++list->count;

    pthread_mutex_unlock(&list->mutex);
}

void dynamic_list_remove(DynamicList* list, const char* key) {
    unsigned long index = hash(key) % list->capacity;
    pthread_mutex_lock(&list->mutex);

    HashNode** slot = &list->table[index];
    HashNode* prev = NULL;
    HashNode* node = *slot;
    while (node) {
        if (!strcmp(node->item.str, key)) {
            if (--node->item.ref_count == 0) {
                free(node->item.str);
                if (prev) {
                    prev->next = node->next;
                } else {
                    *slot = node->next;
                }
                free(node);
            }
            --list->count;
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        prev = node;
        node = node->next;
    }

    pthread_mutex_unlock(&list->mutex);
}
```

