import java.io.*;
import java.util.*;

public class TiffParser {
    private static final int BYTE_SIZE = 8;

    public struct Record {
        public int value;
    }

    public long[] fileOffsets(long fileSize) {
        long offsetCount = fileSize / BYTE_SIZE;
        if (offsetCount * BYTE_SIZE != fileSize) {
            throw new IllegalArgumentException("Potential integer overflow in calculating file offsets.");
        }
        long[] offsets = new long[(int) offsetCount];
        for (int i = 0; i < offsetCount; ++i) {
            offsets[i] = i * BYTE_SIZE;
        }
        return offsets;
    }

    public int[] keys(int keyCount) {
        if (keyCount <= 0) {
            throw new IllegalArgumentException("Key count must be greater than zero.");
        }
        int[] keys = new int[keyCount];
        for (int i = 0; i < keyCount; ++i) {
            keys[i] = i + 1; // Assuming keys are numbered starting from 1.
        }
        return keys;
    }

    public Record[] records(int recordCount, int minValue, int maxValue) {
        if (recordCount <= 0 || minValue >= maxValue) {
            throw new IllegalArgumentException("Invalid parameters for creating records.");
        }
        Record[] records = new Record[recordCount];
        Random random = new Random();
        for (int i = 0; i < recordCount; ++i) {
            records[i] = new Record();
            records[i].value = minValue + random.nextInt(maxValue - minValue);
        }
        return records;
    }
}
```

