#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <random>
#include <cassert>

struct Record {
    int* ptr;
    long file_offset;
    int key;
};

std::mutex mtx;
constexpr size_t MAX_FILE_OFFSET = 1000000;
constexpr size_t MAX_KEY = 100000;
constexpr size_t MAX_RECORDS = 1000000;

std::vector<long> file_offsets;
std::vector<int> keys;
std::vector<Record> records;

void allocate_and_initialize(size_t num) {
    assert(num <= MAX_RECORDS);

    std::unique_ptr<Record[]> temp_records(new Record[num]);

    std::mt19937 gen(std::random_device{}());
    std::uniform_int_distribution<> distr_key(0, MAX_KEY - 1);
    std::uniform_int_distribution<> distr_ptr(0, std::numeric_limits<int>::max() / 2 * std::numeric_limits<int>::max());

    mtx.lock();

    for (size_t i = 0; i < num; ++i) {
        long file_offset = file_offsets.empty() ? 0 : file_offsets.back() + 1;
        assert(file_offset <= MAX_FILE_OFFSET);
        file_offsets.push_back(file_offset);

        int key = distr_key(gen);
        assert(std::find(keys.begin(), keys.end(), key) == keys.end());
        keys.push_back(key);

        temp_records[i].file_offset = file_offset;
        temp_records[i].key = key;
        temp_records[i].ptr = new int(distr_ptr(gen));
    }

    mtx.unlock();

    records.insert(records.end(), temp_records.get(), temp_records.get() + num);
}

std::pair<Record*, size_t> create_record_array(size_t num) {
    allocate_and_initialize(num);
    return std::make_pair(records.data(), records.size());
}
