Dataset* create_dataset(size_t max_records, size_t record_size, size_t memory_limit_kb) {
    // Calculate the total memory required for the dataset
    size_t total_memory = (sizeof(long) * max_records + sizeof(int) * max_records + sizeof(Record) * max_records);

    // Allocate memory pool and records array
    void* memory_pool = malloc(total_memory + memory_limit_kb * 1024);
    Dataset* dataset = (Dataset*)memory_pool;
    dataset->capacity = max_records;
    dataset->size = 0;

    // Initialize other fields
    dataset->offsets = (long*)((char*)dataset + sizeof(Dataset) + total_memory);
    dataset->keys = (int*)((char*)dataset->offsets + sizeof(long) * max_records);
    dataset->records = (Record*)((char*)dataset->keys + sizeof(int) * max_records);

    // Set default string and memory limit
    memcpy(dataset->default_string, DEFAULT_STRING, MAX_DEFAULT_STRING_LENGTH);
    dataset->memory_limit = memory_limit_kb * 1024;

    return dataset;
}
```

3. Add a record to the dataset:

```c
void add_record(Dataset* dataset, int key, int value, const char* buffer) {
    // Check if there is enough memory available
    if (dataset->size + 1 >= dataset->capacity) {
        fprintf(stderr, "Error: Memory limit exceeded\n");
        return;
    }

    // Validate input and allocate memory for the record
    Record* record = &dataset->records[dataset->size];
    if (!buffer || strlen(buffer) > MAX_BUFFER_LENGTH) {
        fprintf(stderr, "Error: Invalid input\n");
        return;
    }
    record->value = value;
    record->buffer = malloc(strlen(buffer) + 1);
    strcpy(record->buffer, buffer);

    // Update offsets and keys arrays
    dataset->offsets[dataset->size] = (long)(char*)record - (long)dataset->records;
    dataset->keys[dataset->size] = key;
    dataset->size++;
}
```

4. Clear a dataset:

```c
void clear_dataset(Dataset* dataset) {
    for (size_t i = 0; i < dataset->size; ++i) {
        free(dataset->records[i].buffer);
    }
    dataset->size = 0;
}
