    webconfig_path: String,
}

type Sites = Arc<Mutex<HashMap<String, SiteConfig>>>;
type PendingSites = Arc<Mutex<VecDeque<SiteConfig>>>;

async fn validate_and_add_site(site: &SiteConfig, sites: &mut Sites) {
    if !sites.contains_key(&site.site_name) {
        sites.insert(site.site_name.clone(), site.clone());
    } else {
        error!("Duplicate site found: {}", site.site_name);
    }
}

async fn check_webconfig_exists(path: &Path) -> Result<(), std::io::Error> {
    let mut file = File::options().follow_links(true).open(path)?;
    file.seek(std::io::SeekFrom::Start(0))?;
    Ok(())
}

async fn start_site(config: &SiteConfig) {
    let command = Command::new("your-web-server")
        .arg(config.webconfig_path.as_str())
        .spawn()
        .expect("Failed to spawn process");

    // Log the started site and handle notifying existing connections of changes
}

async fn reconfigure(sites: &mut Sites, pending_sites: &mut PendingSites) {
    let mut sites_guard = sites.lock().await;
    let mut pending_sites_guard = pending_sites.lock().await;

    while let Some(site) = pending_sites_guard.pop_front() {
        if check_webconfig_exists(&Path::new(&site.webconfig_path)).await.is_ok() {
            validate_and_add_site(&site, sites_guard).await;
            start_site(&site);
        } else {
            error!("Missing web.config file for site: {}", site.site_name);
        }
    }
}

async fn log_to_external_service(log_entry: &str) {
