}

async fn main() {
    let sites = Arc::new(Mutex::new(HashMap::new()));
    let pending_sites = Arc::new(Mutex::new(VecDeque::new()));

    // Add initial sites here

    tokio::spawn(reconfigure(&mut *sites, &mut *pending_sites));

    // Handle incoming configuration changes and log them
    while let Ok(log_entry) = read_line() {
        log_to_external_service(&log_entry).await;
        if let Some(site) = parse_config(&log_entry) {
            pending_sites.lock().await.push_back(site);
        } else {
            debug!("Invalid configuration entry: {}", log_entry);
        }
    }
}
