```

2. Insert a new `Node`:

```c
void insert_node(Node** head, const char* key) {
    if (*head == NULL || strcmp((*head)->key, key) > 0) {
        Node* node = malloc(sizeof(Node));
        memcpy(node->key, key, sizeof(node->key));
        node->ref_count = 1;
        node->next = *head;
        *head = node;
    } else {
        Node* current = *head;
        while (current->next != NULL && strcmp(current->next->key, key) < 0) {
            current = current->next;
        }
        Node* node = malloc(sizeof(Node));
        memcpy(node->key, key, sizeof(node->key));
        node->ref_count = 1;
        node->next = current->next;
        current->next = node;
    }
}
```

3. Remove a `Node`:

```c
void remove_node(Node** head, const char* key) {
    if (*head != NULL && strcmp((*head)->key, key) == 0) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp);
        return;
    }
    Node* current = *head;
    while (current->next != NULL && strcmp(current->next->key, key) != 0) {
        current = current->next;
    }
    if (current->next != NULL) {
        Node* temp = current->next;
        current->next = current->next->next;
        free(temp);
    }
}
