int init_data_structures(int* public_keys, int* private_keys, RSA** rsa_public, RSA** rsa_private, Message** messages, size_t num_messages, size_t max_public_keys, size_t max_private_keys) {
    if (max_public_keys < 1 || max_private_keys < 1) return -1; // Invalid bounds
    if (num_messages > max_messages) return -2; // Invalid number of messages

    public_keys = calloc(max_public_keys, sizeof(int));
    private_keys = calloc(max_private_keys, sizeof(int));
    rsa_public = calloc(max_private_keys, sizeof(RSA*));
    rsa_private = calloc(max_private_keys, sizeof(RSA*));
