    for (size_t i = 0; i < num_messages; ++i) {
        messages[i] = malloc(sizeof(Message));
        if (!messages[i]) return -3; // Allocation failure
        generate_random_string(messages[i]->buffer, rand() % 64 + 1); // Generate random string within 1-64 bytes
        messages[i]->length = strlen(messages[i]->buffer);
