```c
#include <openssl/pem.h>
#include <stdio.h>

void rsa_encrypt(RSA* rsa, const char* plaintext, char* ciphertext) {
    BIO* bio = BIO_new_mem_buf(plaintext, -1); // Create a memory buffer for the plaintext
    BUF_MEM* bptr;                            // Pointer to the memory buffer

    if (!bio || !BIO_ctrl_pending(bio, BIO_CTRL_D_WRITE, 0, NULL)) {
        fprintf(stderr, "Error creating BIO\n");
        return;
    }

    PEM_write_ Bio_NO_HEADER(bio, rsa); // Write the RSA-encrypted data to the buffer
    bptr = (BUF_MEM*)BIO_get_mem_ptr(bio); // Get a pointer to the encrypted data in the buffer
    strcpy(ciphertext, bptr->data);         // Copy the encrypted data to the output buffer
}

void* deserialize_message(const char* serialized) {
    BIO* bio = BIO_new_mem_buf((char*)serialized, -1); // Create a memory buffer for the serialized data
    BUF_MEM* bptr;                                     // Pointer to the memory buffer

    if (!bio || !BIO_ctrl_pending(bio, BIO_CTRL_D_READ, 0, NULL)) {
        fprintf(stderr, "Error creating BIO\n");
        return NULL;
    }

    PEM_read_ Bio_NO_HEADER(bio, NULL, NULL, NULL); // Read the serialized data and create a new Message structure
    bptr = (BUF_MEM*)BIO_get_mem_ptr(bio);           // Get a pointer to the deserialized data in the buffer
    Message* message = malloc(sizeof(Message));      // Allocate memory for the new Message structure
    if (!message) return NULL;                       // Allocation failure

    strcpy(message->buffer, bptr->data);              // Copy the deserialized data to the new Message's buffer
    message->length = strlen(message->buffer);        // Set the new Message's length
    return message;
