```cpp
#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <cstdint>
#include <random>
#include <mutex>
#include <fstream>
#include <sstream>

constexpr size_t MAX_ARRAY_SIZE = 10000;
constexpr size_t MAX_RECORDS = 1000;
constexpr int MIN_KEY = -1000;
constexpr int MAX_KEY = 1000;
constexpr int MIN_VALUE = -1000000;
constexpr int MAX_VALUE = 1000000;

struct Record {
    int value;
    std::string str;
};

std::mutex mtx;
std::unordered_map<int, bool> uniqueValues;

long* allocateOffsets(size_t size) {
    if (size > MAX_ARRAY_SIZE || size < 0) {
        throw std::invalid_argument("Invalid array size");
    }
    long* offsets = new long[size];
    for (long i = 0; i < size; ++i) {
        offsets[i] = -1; // initialize to an invalid index
    }
    return offsets;
}

int* allocateKeys(size_t size) {
    if (size > MAX_ARRAY_SIZE || size < 0) {
        throw std::invalid_argument("Invalid array size");
    }
    int* keys = new int[size];
    for (int i = 0; i < size; ++i) {
        keys[i] = MIN_KEY; // initialize to a valid but minimal index
    }
    return keys;
}

Record* allocateRecords(size_t numRecords) {
    if (numRecords > MAX_RECORDS || numRecords < 0) {
        throw std::invalid_argument("Invalid number of records");
    }
    Record* records = new Record[numRecords];
    for (size_t i = 0; i < numRecords; ++i) {
        records[i].value = -1; // initialize to an invalid value
        records[i].str.clear(); // initialize to an empty string
    }
    return records;
}

void deallocate(Record* records, long* offsets, int* keys) {
    delete[] records;
    delete[] offsets;
    delete[] keys;
}

int getNextKey(int* keys, size_t size) {
    std::lock_guard<std::mutex> lock(mtx);
    for (size_t i = 0; i < size; ++i) {
        if (keys[i] >= MAX_KEY) {
            keys[i] = MIN_KEY;
            break;
        }
        if (!uniqueValues.count(keys[i])) {
            uniqueValues[keys[i]] = true;
            return i;
        }
    }
    throw std::runtime_error("No available key found");
}

void setRecordValue(Record* records, size_t numRecords, long* offsets, int key) {
    if (key < MIN_KEY || key >= static_cast<int>(numRecords)) {
        throw std::invalid_argument("Invalid index");
    }
    if (offsets[key] != -1) {
        throw std::runtime_error("Duplicate key found");
    }
    offsets[key] = static_cast<long>(records - reinterpret_cast<Record*>(0));
}

void serialize(const Record* records, size_t numRecords, const char* filename) {
    std::ofstream file(filename);
    if (!file.is_open()) {
        throw std::runtime_error("Could not open file for writing");
    }
    for (size_t i = 0; i < numRecords; ++i) {
        file << records[i].value << ',' << records[i].str << '\n';
    }
}

void deserialize(Record* records, size_t numRecords, const char* filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        throw std::runtime_error("Could not open file for reading");
    }
    size_t i = 0;
    std::string line;
    while (std::getline(file, line)) {
        std::istringstream iss(line);
        int value;
        std::string str;
        iss >> value >> str;
        records[i].value = value;
        records[i].str = str;
        ++i;
    }
}
```

