    if (size < lower_bound || size > upper_bound) {
        fprintf(stderr, "Invalid array size\n");
        exit(EXIT_FAILURE);
    }
}

void* aligned_malloc(size_t size, size_t alignment) {
    void *ptr = malloc(size + alignment);
    if (ptr != NULL) {
        char *aligned_ptr = (char *)((uintptr_t)ptr & ~(alignment - 1));
        memmove(aligned_ptr, ptr, size);
        free(ptr);
        return aligned_ptr;
    }
    return NULL;
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_arrays(long *offsets, int keys[], size_t size) {
    check_bounds(size, 10, INT_MAX);
    offsets = aligned_malloc(sizeof(long) * size, sizeof(long));
    keys = (int *)aligned_malloc(sizeof(int) * size, sizeof(int));
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = -i;
        keys[i] = i;
    }
}

void init_records(Record *records, size_t num_records, size_t size) {
    check_bounds(num_records, 0, INT_MAX);
    check_bounds(size, 1, INT_MAX);
    records = (Record *)aligned_malloc(sizeof(Record) * num_records, sizeof(Record));
    for (size_t i = 0; i < num_records; ++i) {
        records[i].key = -i;
        strcpy(records[i].str, "");
        records[i].value = rand() % size;
    }
}

int custom_hash(const void *data) {
    const Record *record = (const Record *)data;
    return record->key ^ hash(record->str);
}

unsigned long long hash(const char *str) {
    unsigned long long hash = 5381;
    for (size_t i = 0; str[i] != '\0'; ++i) {
        hash = ((hash << 5) + hash) + str[i]; /* hash * 33 + c */
    }
    return hash;
}

int unique(const void *a, const void *b) {
    const Record *record_a = (const Record *)a;
    const Record *record_b = (const Record *)b;
    return record_a->value != record_b->value;
}

void deinit() {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    pthread_t threads[10];
    long *offsets = NULL;
    int keys[10] = {0};
    Record *records = NULL;
    size_t size = 10;
    size_t num_records = 20;

    init_arrays(offsets, keys, size);
    init_records(records, num_records, size);

    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % size;
        for (size_t j = 0; j < i; ++j) {
