constexpr size_t MAX_ARRAY_SIZE = 100000;
constexpr size_t MAX_RECORDS = 1000000;
constexpr int MIN_VALUE = 0;
constexpr int MAX_VALUE = 100;

struct Record {
    int value;
};

std::vector<long> offsets(size_t size) {
    if (size > MAX_ARRAY_SIZE || size < 1)
        throw std::invalid_argument("Array size out of bounds");

    std::vector<long> v(size);
    return v;
}

std::vector<int> keys(size_t size) {
    if (size > MAX_ARRAY_SIZE || size < 1)
        throw std::invalid_argument("Array size out of bounds");

    std::vector<int> v(size);
    return v;
}

std::vector<Record> records(size_t num_records) {
    if (num_records > MAX_RECORDS || num_records < 1)
        throw std::invalid_argument("Number of records out of bounds");

    std::vector<Record> v(num_records);
    return v;
}

std::unordered_set<int> unique_values;

void set_record_value(Record& record, int value) {
    if (unique_values.find(value) != unique_values.end())
        throw std::runtime_error("Duplicate value encountered");

    unique_values.insert(value);
    record.value = value;
}

void fill_records(std::vector<Record>& records) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(MIN_VALUE, MAX_VALUE);

    for (auto& record : records) {
        int value = dis(gen);
        set_record_value(record, value);
    }
}

void serialize(const std::vector<Record>& records, const char* filename) {
    std::ofstream file(filename, std::ios::binary | std::ios::trunc);
    if (!file.is_open())
        throw std::runtime_error("Failed to open output file");

    file.write((char*)&records.size(), sizeof(size_t));
    for (const auto& record : records) {
        file.write((char*)&record, sizeof(Record));
    }
}

std::vector<Record> deserialize(const char* filename) {
    std::ifstream file(filename, std::ios::binary);
    if (!file.is_open())
        throw std::runtime_error("Failed to open input file");

    size_t num_records;
    file.read((char*)&num_records, sizeof(size_t));
    std::vector<Record> v(num_records);

    for (auto& record : v) {
        file.read((char*)&record, sizeof(Record));
    }

    return v;
}
```

