            httpRequestMessage.RequestUri = new Uri($"https://api.example.com/user/{userId}");
            httpRequestMessage.Headers.Authorization = new AuthenticationHeaderValue("Bearer", decryptedPassword);

            var response = _httpClient.SendAsync(httpRequestMessage).Result;
            if (!response.IsSuccessStatusCode)
                throw new Exception($"Unexpected status code: {response.StatusCode}");

            return JsonConvert.DeserializeObject<UserData>(await response.Content.ReadAsStringAsync());
        }
    }

    private bool IsValidResponse(UserData userData)
    {
        if (string.IsNullOrEmpty(userData.Email) || string.IsNullOrEmpty(userData.PhoneNumber))
            return false;

        return true;
    }

    private byte[] ReadStateObjectNonBlocking()
    {
