        {
            using (var fileStream = File.OpenRead("state.json"))
                return fileStream.ToArray();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error reading state object: {ex}");
            return null;
        }
    }

    private void EvictCacheIfNeeded()
    {
        if (_cache.Count > _maxCacheCapacity)
        {
            var firstKey = _cache.First().Key;
