public class StringProcessor {
    private static final Logger LOGGER = Logger.getLogger(StringProcessor.class.getName());

    public byte[] process(String input, Transformation transformation, HashingAlgorithm algorithm) throws Exception {
        long startTime = System.currentTimeMillis();
        String cleanedInput = input.replaceAll("[^a-zA-Z0-9]", "");
        String transformedInput = transformation.apply(cleanedInput);
        byte[] hashedResult = MessageDigest.getInstance(algorithm.getName()).digest(transformedInput.getBytes(StandardCharsets.UTF_8));
