#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct DataItem {
    char* name;
    double value;
    struct DataItem* next;
} DataItem;

DataItem* create_list(int size, int* error) {
    if (size <= 0 || size > INT_MAX / sizeof(DataItem)) {
        *error = 1;
        return NULL;
    }

    DataItem* head = malloc(sizeof(DataItem));
    if (!head) {
        *error = 2;
        return NULL;
    }
    head->next = NULL;

    for (int i = 1; i < size; ++i) {
        DataItem* node = malloc(sizeof(DataItem));
        if (!node) {
            free_list(head, error);
            return NULL;
        }
        node->next = head->next;
        head->next = node;
    }

    return head;
}

void insert_dataitem(DataItem** list, DataItem* new_node) {
    if (!list || !new_node) return;

    DataItem* current = *list;
    if (!current->next) {
        current->next = new_node;
        return;
    }

    DataItem* prev = current;
    while (current && strcmp(current->name, new_node->name) < 0) {
        prev = current;
        current = current->next;
    }

    if (!prev->next) {
        prev->next = new_node;
    } else {
        new_node->next = current;
        prev->next = new_node;
    }
}

double sum_values(DataItem* list) {
    double total = 0.0;
    for (DataItem* node = list->next; node; node = node->next) {
        total += node->value;
    }
    return total;
}

void free_list(DataItem* head, int* error) {
    if (!head) return;

    for (DataItem* current = head->next; current; ) {
        DataItem* next = current->next;
        free(current->name);
        free(current);
        current = next;
    }
    free(head);
}
```

