        : _data(new DataRecord[initialCapacity]), _keys(_keys.begin(), _data + initialCapacity),
          _offsets(_offsets.begin(), _data + initialCapacity), _freeIndices(_freeIndices.begin(), _data + initialCapacity),
          _compressionLevel(compressionLevel) {
        alignMemory(_data, initialCapacity * sizeof(DataRecord), alignment);
    }

    ~DynamicStorageSystem() { freeAll(); }

    void addRecord(const DataRecord& record) {
        if (_freeIndices.empty()) resize();
        auto it = std::min_element(_freeIndices.begin(), _freeIndices.end());
        auto index = *it;
        _data[index] = record;
        _keys[_data[index].key] = index;
        _offsets[_data[index].offset] = _offsets.size();
        _freeIndices.erase(it);
    }

    DataRecord& getRecord(int key) {
        auto it = _keys.find(key);
        if (it == _keys.end()) throw std::runtime_error("Key not found");
        return _data[it->second];
    }

    void freeAll() {
        if (_freeAllFlag) {
            for (auto& record : _data) {
                if (!_freeIndices.contains(&record)) {
                    _keys[_record.key] = -1;
                    _offsets[_record.offset] = -1;
                    _freeIndices.push_back(&record);
                }
            }
        }
    }

    void setFreeAllFlag(bool flag) { _freeAllFlag = flag; }

private:
    std::vector<DataRecord>* _data;
    std::vector<int> _keys, _offsets, _freeIndices;
    int _compressionLevel;
    bool _freeAllFlag = false;

    void resize() {
        auto newCapacity = _data->size() * 2;
        alignMemory(_data, newCapacity * sizeof(DataRecord), alignment);
        _keys.resize(_keys.size() + (newCapacity - _data->size()));
        _offsets.resize(_offsets.size() + (newCapacity - _data->size()));
        _freeIndices.resize(_freeIndices.size() + (newCapacity - _data->size()));
    }

    static void alignMemory(void* ptr, size_t size, size_t alignment) {
        // Implement memory alignment strategy here
    }
};
```

