#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char* message;
    int status_code;
} event;

void validate(char* str, size_t len) {
    if (!str || len == 0) {
        fprintf(stderr, "Invalid string\n");
        exit(EXIT_FAILURE);
    }
}

void validate_time(char* time_str) {
    size_t len = strlen(time_str);
    if (len > 32) { // Max length for timestamp including '\0'
        fprintf(stderr, "Invalid timestamp format\n");
        exit(EXIT_FAILURE);
    }
}

void validate_status_code(int status_code, int min, int max) {
    if (status_code < min || status_code > max) {
        fprintf(stderr, "Invalid status code: %d\n", status_code);
        exit(EXIT_FAILURE);
    }
}

void* reallocate(void* ptr, size_t current_size, size_t new_size) {
    void* result = realloc(ptr, new_size);
    if (!result && new_size > current_size) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return result;
}

event* generate_event(char** timestamps, size_t* timestamp_capacity, char** events, size_t* event_capacity) {
    time_t now = time(NULL);
    struct tm* tm_now = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    size_t timestamp_len = strlen(timestamp) + 1;
    validate(timestamp, timestamp_len);
    validate_time(timestamp);

    char* new_timestamp = realloc(*timestamps, *timestamp_capacity * sizeof(char) * (timestamp_len));
    if (!new_timestamp) {
        return NULL;
    }
    memcpy(*timestamps, timestamp, timestamp_len * sizeof(char));
    (*timestamps) += timestamp_len;
    *timestamp_capacity += timestamp_len;

    int status_code = rand() % 100 + 1; // Generate a random status code between 1 and 100
    validate_status_code(status_code, 1, 100);

    char* event_message = calloc(256, sizeof(char)); // Preallocate enough space for the message and timestamp combined
    strcat(event_message, timestamp);
    strcat(event_message, " - Event ");
    int event_message_len = strlen(event_message);

    char* events_list[100] = {"Event 1", "Event 2", /* ... */ "Event 100"}; // Predefined list of event descriptions
    int index = rand() % 100;
    validate(events_list[index], strlen(events_list[index]) + 1);
    strcat(event_message, events_list[index]);

    char* new_event = realloc(*events, *event_capacity * sizeof(char) * (event_message_len + sizeof(int)));
    if (!new_event) {
        free(event_message);
        return NULL;
    }
    memcpy(*events, event_message, event_message_len * sizeof(char));
    (*events) += event_message_len;
    (*events) += sizeof(int);
    *event_capacity += event_message_len + sizeof(int);

    event* result = (event*)(*events - sizeof(int));
    result->status_code = status_code;
    result->message = event_message;

    return result;
}

void free_memory(char** timestamps, size_t timestamp_capacity, char** events, size_t event_capacity) {
    for (size_t i = 0; i < *timestamp_capacity; ++i) {
        free(*timestamps++);
    }
    free(*timestamps);

    for (size_t i = 0; i < *event_capacity / sizeof(char); i += sizeof(int) + strlen(*events[i]) + 1) {
        event* event_ptr = (event*)(&(*events[i]));
        free(event_ptr->message);
    }
    free(*events);
}

void example_usage() {
    size_t initial_capacity = 1024; // Initial capacity for both arrays
    char* timestamps = malloc(initial_capacity * sizeof(char));
    char* events = malloc(initial_capacity * sizeof(char));

    event* event = generate_event(&timestamps, &initial_capacity, &events, &initial_capacity);
    if (!event) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    printf("Generated event:\n");
    printf("Timestamp: %s\n", *timestamps);
    printf("Status code: %d\n", event->status_code);
    printf("Message: %s\n", event->message);

    free_memory(&timestamps, initial_capacity, &events, initial_capacity);
}
