                break;
            case 'V':
                max_file_size = strtoll(optarg, NULL, 10);
                break;
            case 'm':
                strcpy(encoding, optarg);
                break;
            default:
                fprintf(stderr, "Invalid option\n");
                return 1;
        }
    }

    if (optind < argc) {
        input_file = argv[optind];
    }

    if (!input_file || !output_dir || !encoding) {
        fprintf(stderr, "Missing required arguments\n");
        return 1;
    }

    struct stat st;
    if (stat(input_file, &st) == -1) {
        perror("Error while getting file stats");
        return 1;
    }

    int fd = open(input_file, O_RDONLY);
    if (fd == -1) {
        perror("Error while opening the file");
        return 1;
    }

    struct data data;
    data.file_size = st.st_size;
    data.mapped_file = mmap(NULL, data.file_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (data.mapped_file == MAP_FAILED) {
        perror("Error while memory mapping the file");
        close(fd);
        return 1;
    }

    strncpy(data.encoding, encoding, sizeof(data.encoding));

    off_t processed = 0;
    off_t total = data.file_size;

    for (off_t i = 0; i < total; i += data.file_size / 4) { // Adjust chunk size as needed
        struct data *chunk = &data + (i / (data.file_size / 4));
        chunk->file_offset = i;
        chunk->file_size = data.file_size > max_file_size ? max_file_size - processed : data.file_size - processed;
        if (chunk->file_size == 0) break;

        pthread_create(&threads[i / (data.file_size / 4)], NULL, process_data, chunk);
        processed += chunk->file_size;
    }

    for (int i = 0; i < (data.file_size > max_file_size ? data.file_size / max_file_size : 1); i++) {
        pthread_join(threads[i], NULL);
    }

    munmap(data.mapped_file, data.file_size);
    close(fd);

    // Save the output here based on the processed data and rules

    return 0;
}
