class ThemeCacheManager {
    private val themeDirectory: File
    private val themeBitmapPool: BitmapPool
    private val themeLoader: ThemeLoader
    private val lruCache: LRUCache<String, Bitmap>
    private val logger: Logger

    init {
        // Initialize theme directory if not set previously and validate its existence and writability.
        // Handle external changes to the directory and respond accordingly.
        themeDirectory = getThemeDirectory()

        // Initialize bitmap pool for efficient recycling of theme bitmaps.
        themeBitmapPool = BitmapPool()

        // Initialize theme loader that fetches themes from an external API, parses PNG files, and handles caching.
        themeLoader = ThemeLoader(themeDirectory, themeBitmapPool)

        // Initialize LRU cache for storing theme bitmaps based on their usage frequency.
        lruCache = LRUCache(maxSize = MAX_CACHE_SIZE)

        // Initialize logger to track cache hits, misses, bitmap recycling, and theme updates.
        logger = Logger()
    }

    fun getTheme(themeId: String): Bitmap? {
        // Check if the theme is already in the cache.
        val cachedTheme = lruCache.get(themeId)
        if (cachedTheme != null) return cachedTheme

        // If not found, fetch and parse the theme from the external API, then store it in the cache.
        val fetchedTheme = themeLoader.loadTheme(themeId)
        if (fetchedTheme == null) return null

        lruCache.put(themeId, fetchedTheme)
        return fetchedTheme
    }

    fun invalidateThemes() {
        // Invalidate all themes in the cache upon user preference changes.
        lruCache.evictAll()
    }

    // Other functions for managing theme caching, such as eviction policy optimization, monitoring cache performance, etc.
}
```

