#include <boost/serialization/vector.hpp>
#include <boost/serialization/list.hpp>
#include <boost/serialization/unordered_map.hpp>
#include <boost/serialization/utility.hpp>
#include <boost/archive/binary_iarchive.hpp>
#include <boost/archive/binary_oarchive.hpp>

struct Record {
    int value;

    friend class boost::serialization::access;

    template<class Archive>
    void serialize(Archive& ar, const unsigned int version) {
        ar & value;
    }
};

class CustomAllocator {
public:
    CustomAllocator() : data_(nullptr), size_(0), capacity_(0) {}

    ~CustomAllocator() { free(data_); }

    void allocate(size_t n, size_t s) {
        if (capacity_ < n) {
            auto new_data = static_cast<Record*>(realloc(data_, n * sizeof(Record)));
            if (!new_data) throw std::bad_alloc();
            data_ = new_data;
            capacity_ = n;
        }
    }

    void deallocate(Record* p, size_t n) {
        free(p);
    }

    Record* allocate() {
        if (size_ < capacity_) {
            ++size_;
            return &data_[size_ - 1];
        }
        throw std::bad_alloc();
    }

    void deallocate(Record* p) {
        --size_;
    }

private:
    Record* data_;
    size_t size_, capacity_;
};

void manipulateAndSerializeData(std::list<std::string> records, const std::string& key1, const std::string& key2) {
    using namespace boost::serialization;

    CustomAllocator allocator;
    std::vector<Record, CustomAllocator> data(allocator);
    std::unordered_map<int, Record*> index;

    int recordCount = 0;
    for (const auto& record : records) {
        if (recordCount >= 1_000_000) break;

        // Validate the number of records against specified limits
        if (recordCount >= data.size()) throw std::runtime_error("Too many records");

        Record* r = &data[recordCount];
        r->value = recordCount + 1;
        index[r->value] = r;
        ++recordCount;
    }

    // Validate the number of records against specified limits
    if (recordCount != data.size()) throw std::runtime_error("Not enough records");

    // Set each record's int field to a unique random value within a given range
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, 100);

    for (auto& r : data) {
        if (index.find(r.value) != index.end()) continue; // Avoid duplicates

        r.value = dis(gen);
        index[r.value] = &r;
    }

    std::ofstream file("output.bin", std::ios::binary | std::ios::out);
    if (!file) throw std::runtime_error("Failed to open output file");

    {
        boost::archive::binary_oarchive oa(file);
        oa & make_nvp("records", data);
    }
}
