    fn new(options: &HashMap<String, String>) -> Result<Self, Box<dyn std::error::Error>> {
        let headers = options.get("headers").map(|h| serde_json::from_str(h).unwrap());
        let timeout = options.get("timeout").and_then(|t| Duration::from_str(t).ok());
        let auth = options.get("auth");
