            .timeout(*timeout)
            .headers(headers.as_ref().unwrap_or(&HashMap::new()))
            .danger_accept_invalid_certs(!tls_validate)
            .build()?;

        if let Some(auth) = auth {
            let (id, secret) = serde_json::from_str(auth).unwrap();
            let auth = reqwest::http::header::Authorization::Basic((id, secret));
            client.default_headers().insert(auth);
        }

        Ok(HttpClient { client })
    }

    fn get(&self, url: &str) -> Result<Response, Box<dyn std::error::Error>> {
        self.client.get(url).send()
    }
