[" Here's the code for the requested functions:

```javascript
function processStringWithLimit(str, limit, position) {
  const suffix = '*'; // Replace this with your desired suffix
  let result = '';

  switch (position) {
    case 'start':
      result = str.slice(0, limit) + suffix;
      break;
    case 'middle':
      if (str.length <= limit) result = str.slice(0, limit) + suffix;
      break;
    case 'end':
      if (str.length <= limit + suffix.length) result = str.slice(0, str.length - suffix.length) + suffix;
      break;
  }

  return result;
}

function recursiveDomTraversal(node, selector, callback, depth = 1, visitedNodes = new Set()) {
  if (node === null || node.nodeType !== Node.ELEMENT_NODE) return;

  const matchesSelector = (node, selector) => node.matches ? node.matches(selector) : node.webkitMatchesSelector || node.mozMatchesSelector ? node.webkitMatchesSelector(selector) || node.mozMatchesSelector(selector) : false;

  if (!visitedNodes.has(node.toString())) {
    visitedNodes.add(node.toString());

    if (matchesSelector(node, selector)) {
      callback(node, depth);
    }

    const children = Array.from(node.children);
    for (let child of children) {
      recursiveDomTraversal(child, selector, callback, depth + 1, visitedNodes);
    }
  }
}
```"]

