#include <boost/serialization/access.hpp>
#include <boost/serialization/nvp.hpp>
#include <boost/serialization/vector.hpp>
#include <boost/serialization/utility.hpp>

struct Record {
    int value;
    friend class boost::serialization::access;

    template<class Archive>
    void serialize(Archive & ar, const unsigned int version) {
        ar & value;
    }
};

std::mutex mtx;

void manage_memory(int max_longs, int max_ints, int max_records, int min_records, int range_min, int range_max) {
    long* offsets = new long[max_longs];
    int* keys = new int[max_ints];
    Record* records = nullptr;
    int num_records = 0;

    // Validate sizes and allocate memory for records
    if (num_records < min_records || num_records > max_records) {
        std::cerr << "Invalid number of records. Allocating " << max_records << " records." << std::endl;
        records = new Record[max_records];
        num_records = max_records;
    } else {
        records = new Record[num_records];
    }

    // Initialize offsets and keys arrays
    long offset = 0;
    for (int i = 0; i < max_ints; ++i) {
        keys[i] = i + offset;
        if (offset + (long)(num_records * sizeof(Record)) > max_longs) {
            std::cerr << "Memory limit exceeded. Adjusting array sizes." << std::endl;
            --max_ints;
            break;
        }
        offset += sizeof(Record);
    }

    // Set unique random values for records and handle collisions using chaining
    std::vector<std::vector<Record>> record_chain(range_max - range_min + 1);
    for (int i = 0; i < num_records; ++i) {
        int key = keys[rand() % max_ints];
        mtx.lock();
        if (std::find(record_chain[key].begin(), record_chain[key].end(), records[i]) == record_chain[key].end()) {
            records[i].value = key;
            record_chain[key].push_back(records[i]);
        } else {
            ++key;
            while (std::find(record_chain[key].begin(), record_chain[key].end(), records[i]) != record_chain[key].end()) {
                ++key;
            }
            records[i].value = key;
            mtx.unlock();
            mtx.lock();
            record_chain[key].push_back(records[i]);
        }
        mtx.unlock();
    }

    // Serialize and save the data to a file
    std::ofstream file("data.bin", std::ios::binary);
    boost::serialization::serialize(file, BOOST_SERIALIZATION_NVP("records", records, num_records));
    file.close();
}
```

This code initializes two arrays for long offsets and int keys, allocates memory for record structures, sets unique random values for each record using a chaining-based collision resolution strategy, and serializes the data to a binary file. It also uses a mutex to ensure data consistency during concurrent access. However, it does not handle memory deallocation, different I/O patterns, or locking strategies optimization. You can further develop this code based on your specific requirements.']

[' Here's a simplified implementation of a dynamic list (doubly-linked list) in C, which meets the requirements you've specified. This code does not include error handling or edge cases for brevity but can be expanded upon as needed.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Entry {
    double value;
    char* identifier;
    struct Entry* next;
    struct Entry* prev;
} Entry;

Entry* create_entry(char* identifier) {
    Entry* new_entry = (Entry*)malloc(sizeof(Entry));
    new_entry->identifier = strdup(identifier);
    new_entry->value = 0.0;
    new_entry->next = NULL;
    new_entry->prev = NULL;
    return new_entry;
}

void init_list(Entry** head) {
    srand(time(NULL));
    *head = create_entry((char*)malloc(sizeof(char) * 16));
    (*head)->identifier[0] = '\0';
    (*head)->next = NULL;
    (*head)->prev = NULL;
}

void insert_after(Entry* current, Entry* new_entry) {
    if (current == NULL || new_entry == NULL) return;

    new_entry->next = current->next;
    new_entry->prev = current;

    if (current->next != NULL)
        current->next->prev = new_entry;

    current->next = new_entry;
}

void delete_entry(Entry* entry) {
    if (entry == NULL || entry->next == NULL && entry->prev == NULL) return;

    if (entry->next != NULL)
        entry->next->prev = entry->prev;

    if (entry->prev != NULL)
        entry->prev->next = entry->next;

    free(entry->identifier);
    free(entry);
}

void populate_values(Entry* head, int min, int max, int count) {
    for (int i = 1; i < count + 1; ++i) {
        Entry* current = head->next;
        if (current == NULL) break;
        current->value = rand() % (max - min + 1) + min;
        current = current->next;
    }
}

void print_list(Entry* head) {
    for (Entry* current = head->next; current != NULL; current = current->next) {
        printf("Identifier: %s, Value: %.2f\n", current->identifier, current->value);
    }
}
```

