    char* request_id = json_object_get_string(json_object_object_get(json_response, "request_id"));
    add_to_hash_table(hash_table, request_id, entry);

    return NULL;
}

void calculate_average_response_time(const char* user) {
    int sum = 0;
    int count = 0;
    pthread_mutex_lock(&hash_table->lock);
    for (int i = 0; i < hash_table->size; ++i) {
        RequestCacheEntry* entry = hash_table->entries[i];
        if (entry && strcmp(entry->request_id, user) == 0) {
            sum += entry->response_time;
            ++count;
        }
    }
    pthread_mutex_unlock(&hash_table->lock);

    if (count > 0) {
        double average = (double)sum / count;
        printf("Average response time for user %s: %.2f ms\n", user, average);
    }
}

