#include <ctime>
#include <mutex>
#include <unordered_map>

struct Entry {
    double value;
    std::string id;
    long offset;

    Entry(double v, const std::string& i, long o) : value(v), id(i), offset(o) {}
};

std::mutex mtx;
std::unordered_map<std::string, size_t> uniqueIds;
std::vector<Entry> entries;
std::vector<long> offsets;

size_t generateId(size_t min = 10, size_t max = 1e7) {
    std::mt19937 gen(time(nullptr));
    std::uniform_int_distribution<> dis(min, max);
    return dis(gen);
}

void addEntry(double value, long offset) {
    mtx.lock();
    auto id = generateId() + std::to_string(offset);
    while (uniqueIds.find(id) != uniqueIds.end()) {
        id = generateId();
    }
    uniqueIds[id] = entries.size();
    entries.push_back({value, id, offset});
    offsets.push_back(offset);
    mtx.unlock();
}

void freeMemory() {
    for (auto& entry : entries) {
        delete[] const_cast<char*>(entry.id.c_str());
    }
    entries.clear();
    offsets.clear();
    uniqueIds.clear();
}
```

This code creates an `Entry` structure to hold the data, a hash map for storing unique identifiers, and vectors for dynamic memory allocation of entries and file offsets. The `addEntry()` function generates a unique identifier, adds the entry to the corresponding vector, and updates the hash map. The `freeMemory()` function frees all allocated memory when called.

For real-time or near-real-time processing, consider using lock-free data structures, asynchronous processing, or batch processing with pipelining for improved performance in high-load scenarios. Additionally, you may want to explore integrating an existing database system or API for efficient data retrieval and storage."]

