#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
};

void initializeDataStructure(long* offsets, int* keys, struct Record** records, size_t size) {
    if (size == 0) return;

    offsets = realloc(offsets, sizeof(long) * (size + 1));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        exit(EXIT_FAILURE);
    }

    keys = realloc(keys, sizeof(int) * size);
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys.\n");
        free(offsets);
        exit(EXIT_FAILURE);
    }

    records = malloc(sizeof(struct Record*) * size);
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        free(keys);
        free(offsets);
        exit(EXIT_FAILURE);
    }

    offsets[0] = 0;
    for (size_t i = 1; i <= size; ++i) {
        offsets[i] = offsets[i - 1] + sizeof(int) + sizeof(struct Record);
        records[i - 1] = (struct Record*)(offsets[i]);
    }

    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        records[i]->value = rand() % 100;
    }
}
```

