```java
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.ConcurrentMap;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.LinkedList;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class InvoiceSummary {
    private final InventoryManagementSystem inventory;
    private final PaymentGatewayApi paymentGateway;
    private final Deque<BigDecimal> cache;
    private final ConcurrentMap<UUID, LocalDateTime> lastUpdatedCache;
    private final Lock lock = new ReentrantLock();

    public InvoiceSummary(InventoryManagementSystem inventory, PaymentGatewayApi paymentGateway) {
        this.inventory = inventory;
        this.paymentGateway = paymentGateway;
        this.cache = new LinkedList<>();
        this.lastUpdatedCache = new LinkedHashMap<>(128, 0.75f, 16);
    }

    public BigDecimal generateInvoiceSummary(Order order) {
        lock.lock();
        try {
            BigDecimal total = BigDecimal.ZERO;
            for (OrderItem item : order.getItems()) {
                ProductDetails details = inventory.getProductDetails(item.getId());
                if (details != null && isValidProductDetails(details, item)) {
                    LocalDateTime lastUpdated = lastUpdatedCache.getOrDefault(item.getId(), LocalDateTime.MIN);
                    if (LocalDateTime.now().isAfter(lastUpdated.plusMinutes(5))) {
                        details = inventory.refreshProductDetails(item.getId());
                        lastUpdatedCache.put(item.getId(), LocalDateTime.now());
                    }
                    total = total.add(item.getQuantity().multiply(details.getPrice()));
                } else {
                    System.out.println("Invalid product details or discrepancies between order items and inventory records.");
                }
            }

            BigDecimal calculatedTotal = total.setScale(2, BigDecimal.ROUND_HALF_UP);
            if (calculatedTotal.compareTo(paymentGateway.validateTransactionAmount(calculatedTotal)) != 0) {
                System.out.println("Invoice total does not match the calculated amount.");
                return null;
            }

            cache.addLast(calculatedTotal);
            if (cache.size() > 128) {
                cache.removeFirst();
            }

            String invoiceReference = UUID.randomUUID().toString() + LocalDateTime.now().toString();
            System.out.println("Invoice generated with reference: " + invoiceReference);
            return calculatedTotal;
        } finally {
            lock.unlock();
        }
    }

    private boolean isValidProductDetails(ProductDetails details, OrderItem item) {
        // Implement your validation logic here
        return true;
    }
}
```

This implementation includes the following:

