typedef struct {
    int width;
    int height;
    int color_space;
    int orientation;
    char exif[256]; // EXIF metadata as a string
    // Add more fields as needed
} report_t;

report_t processJPEGImage(const char *filename) {
    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *infile = fopen(filename, "rb");
    JSAMPARRAY buffer;
    int num_components;
    int i;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);
    jpeg_stdio_init(&cinfo, infile);

    jpeg_read_header(&cinfo, TRUE);
    num_components = cinfo.num_components;

    cinfo.out_color_space = JCS_RGB; // Assuming RGB color space for simplicity

    jpeg_start_decompress(&cinfo);

    buffer = (*cinfo.mem->alloc_sarray)
        ((j_common_ptr)&cinfo, JPOOL_IMAGE, cinfo.output_width * cinfo.output_height * num_components, 1);

    for (i = 0; i < cinfo.output_height; ++i) {
        jpeg_read_scanlines(&cinfo, buffer, 1);
    }

    report_t report = {
        .width = cinfo.output_width,
        .height = cinfo.output_height,
        .color_space = cinfo.out_color_space,
        .orientation = cinfo.orientation,
    };

    // Extract EXIF metadata using libjpeg-turbo's jpeg_read_appnk_segment function or another library if needed
    // ...

    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);
    fclose(infile);

    return report;
}
```

