const fs = require('fs');
const path = require('path');
const readline = require('readline');
const zlib = require('zlib');
const axios = require('axios');
const q = require('q');
const chokidar = require('chokidar');
const { promisify } = require('util');
const storageBackend = require('./storage-backend'); // Customizable storage backend module
const analyticsService = require('./analytics-service'); // Third-party analytics service module

// Configuration object
const config = {
  directoryPath: '',
  compressionAlgorithm: 'gzip',
  storageBackend,
  dataSegmentCriteria: { size: 1048576, time: 60000 },
  maxConcurrentProcesses: 10,
  retryCount: 3,
  retryInterval: 1000,
};

// Read directory and process files asynchronously
const readDir = promisify(fs.readdir);
const stat = promisify(fs.stat);
const readdirp = chokidar.watch(config.directoryPath, { persistent: true });

let concurrentProcesses = 0;

reedirp
  .on('add', async (file) => {
    if (!path.extname(file).match(/^(.bin)$/)) return; // Only process binary files

    try {
      const stats = await stat(path.join(config.directoryPath, file));
      if (stats.isDirectory()) return; // Skip directories

      if (concurrentProcesses < config.maxConcurrentProcesses) {
        concurrentProcesses++;
        processFile(file);
      } else {
        readdirp.on('unlink', async (removedFile) => {
          if (removedFile === file) {
            concurrentProcesses--;
            processFile(file);
          }
        });
      }
    } catch (error) {
      console.error(`Error reading file ${file}:`, error);
    }
  })
  .on('error', (error) => console.error('Watcher error:', error));

async function processFile(file) {
  try {
    const metadata = await retrieveMetadata(file);
    const compressedData = compressData(metadata, file);
    await storeData(compressedData, file);
    await analyzeData(metadata, compressedData);
    fs.unlinkSync(path.join(config.directoryPath, file)); // Delete original file after processing
  } catch (error) {
    console.error(`Error processing file ${file}:`, error);
  } finally {
    concurrentProcesses--;
  }
}

async function retrieveMetadata(file) {
  const metadata = await axios.get(`${METADATA_API_URL}/${file}`).catch((error) => {
    console.error(`Error retrieving metadata for file ${file}:`, error);
    return null;
  });
  return metadata.data;
}

function compressData(metadata, file) {
  const inputStream = fs.createReadStream(path.join(config.directoryPath, file));
  const outputStream = zlib.createGzip();
  const rl = readline.createInterface({ input: inputStream, output: outputStream });
  return new Promise((resolve) => {
    rl.on('end', () => resolve(outputStream.toString('base64')));
  });
}

async function storeData(data, file) {
  await storageBackend.store(data, file);
}

async function analyzeData(metadata, data) {
  await analyticsService.analyze(metadata, data);
}
```

