class MemoryManager {
public:
    MemoryManager(size_t numRecords, size_t powerOfTwoOffsetSize, std::ostream& logStream)
        : numRecords_(numRecords), powerOfTwoOffsetSize_(powerOfTwoOffsetSize),
          offsets_(powerOfTwoOffsetSize_, 0), keys_(), records_(), logStream_(logStream) {}

    void initialize() {
        if (numRecords_ > std::pow(2, powerOfTwoOffsetSize_) / sizeof(long)) {
            throw std::runtime_error("Requested number of records exceeds available memory");
        }

        srand(time(nullptr));
        float totalWeight = 0.0f;

        keys_.reserve(numRecords_);
        for (size_t i = 0; i < numRecords_; ++i) {
            int key;
            do {
                key = hashFunction_(i);
            } while (keys_.count(key) > 0);
            keys_[key] = i;
            totalWeight += 1.0f / numRecords_;
        }

        records_.resize(numRecords_);
        for (size_t i = 0; i < numRecords_; ++i) {
            records_[i].offset = offsets_[i];
            records_[i].key = keys_[i];
            records_[i].weight = totalWeight * rand() / RAND_MAX;
        }
    }

    Record& getRecord(size_t index) {
        if (index >= numRecords_) {
            throw std::runtime_error("Index out of range");
        }
        return records_[index];
    }

    void sort(bool byWeight = true) {
        if (byWeight) {
            std::sort(records_.begin(), records_.end(), [](const Record& a, const Record& b) {
                return a.weight > b.weight;
            });
        } else {
            // Implement sorting by key or combined weight and key here
        }
    }

    void logMemoryUsage() {
        std::ofstream logFile("memory_usage.log", std::ios::app);
        if (logFile.is_open()) {
            logFile << "Memory usage:\n";
            logFile << "  Offsets: " << offsets_.size() * sizeof(long) << "\n";
            logFile << "  Keys: " << keys_.size() * sizeof(int) << "\n";
            logFile << "  Records: " << records_.size() * sizeof(Record) << "\n";
            logFile.close();
        } else {
            logStream_ << "Failed to open memory_usage.log for writing\n";
        }
    }

private:
    size_t hashFunction_(size_t key) const {
        // Implement a simple hash function here, such as FNV-1a or Jenkins hash
        unsigned int hash = 2166136261u;
        for (char c : std::to_string(key)) {
            hash ^= static_cast<unsigned char>(c);
            for (size_t i = 0; i < 4; ++i) {
                hash += (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24);
            }
        }
        return static_cast<size_t>(hash);
    }

    size_t numRecords_;
    size_t powerOfTwoOffsetSize_;
    std::vector<long> offsets_;
    std::unordered_map<int, size_t> keys_;
    std::vector<Record> records_;
    std::ostream& logStream_;
};
