function generateFooters(scripts, userRole) {
    const footers = document.getElementsByTagName('footer')[0];

    if (userRole !== 'admin' && scripts.some((script) => script.key === 'adminScript')) {
        return; // Hide admin scripts for non-administrators
    }

    const footerScripts = scripts.filter((script) => script.key).map((script) => {
