        self.user_id = user_id
        self.amount = amount
        self.timestamp = timestamp

class TimeWindow:
    def __init__(self, start: float, end: float):
        self.start = start
        self.end = end

class TransactionProcessor:
    def __init__(self, blacklist: List[int], time_windows: List[TimeWindow], external_service):
        self.blacklist = set(blacklist)
        self.time_windows = {tw.start: tw for tw in time_windows}
        self.external_service = external_service
        self.transactions_by_user = defaultdict(lambda: ([], [], 0))
        self.priority_queue = []

    def add_transaction(self, transaction: Transaction):
        if transaction.user_id not in self.blacklist:
            user_data = self.transactions_by_user[transaction.user_id]
            user_data[0].append(transaction)
            user_data[1].append(transaction.timestamp)
            user_data[2] += transaction.amount
            heapq.heappush(self.priority_queue, (transaction.timestamp, user_data[1], user_data))

    def process_transactions(self):
        while self.priority_queue:
            _, timestamps, user_data = heapq.heappop(self.priority_queue)
            start_time = time.monotonic()
            aggregated_amount = user_data[2]
            for tw_start in sorted(reversed(list(self.time_windows.keys()))):
                if tw_start > timestamps[-1]:
                    break
                tw = self.time_windows[tw_start]
                if tw.start <= timestamps[-1] < tw.end:
