void grow(int* size, int max_size) {
    if (*size >= max_size) return;
    *size *= 2;
}

void init_offsets() {
    grow(&offset_size, 1024);
    records = realloc(records, offset_size * sizeof(int));
}

void init_keys() {
    grow(&key_size, 1024);
    records = realloc(records, key_size * sizeof(int));
}

Record* allocate_record() {
    if (num_records >= 512) return NULL;
    grow(&num_records, 512);
    records = realloc(records, num_records * sizeof(Record));
    Record* record = &records[num_records - 1];
    record->value = malloc(8); // Allocate 8 bytes for long value
    if (!record->value) return NULL;
    return record;
}

void set_random_value(Record* record, uint64_t min, uint64_t max) {
    *((uint64_t*)record->value) = (rand() % (max - min + 1)) + min;
}

void free_records() {
    for (int i = num_records - 1; i >= 0; --i) {
        free(records[i].value);
        records[i].value = NULL;
    }
    free(records);
    records = NULL;
}

