    interval: u64,
}

async fn handle_error<E>(result: Result<(), E>) -> Result<(), E> {
    match result {
        Ok(_) => Ok(()),
        Err(e) => {
            tracing::error!("Error occurred: {}", e);
            Err(e)
        }
    }
}

async fn generate_statistics() -> Result<(), String> {
    let tracer = trace::Tracer::new("my_service", "1.0.0");
    global::set_tracer(tracer);

    let service_name = Opt::from_args().service;
    let output_file = Opt::from_args().output;
    let log_level = Opt::from_args().log_level;
    let interval = Interval::new(Duration::from_millis(Opt::from_args().interval));

    let mut metrics_recorder = metrics::warp_exporter::new(8080).unwrap();

    let mut span = tracer.start_span("generate_statistics", service_name);
    span.set_attribute("output_file", &output_file);

    let start_time = SystemTime::now().duration_since(UNIX_EPOCH).unwrap();

    loop {
        // Collect performance data here
        let elapsed = interval.next().await?;

        let end_time = SystemTime::now().duration_since(start_time).unwrap();
        let total_elapsed = end_time.as_secs() as f64 + elapsed.as_secs_f64() / 1000.0;

