                requests = metrics.requests,
                avg_response_time = metrics.avg_response_time,
                error_percentage = metrics.error_percentage,
                "Performance warning: Duration exceeded 60 seconds"
            );
        }

        // Save the metrics to the output file
        save_metrics_to_file(&output_file, &metrics)?;

        span.set_attribute("elapsed", &total_elapsed.to_string());
    }
}

fn main() {
    let subscriber = tracing_subscriber::fmt::layer().with_filter(tracing_subscriber::Filter::from_level(log_level));
