#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

typedef struct {
    int key;
    int index;
    int config;
} Config;

void* init_arrays(int max_records, int max_configs, int alignment, int min_value, int max_value) {
    long *offset = (long*)aligned_alloc(alignment, sizeof(long)*(max_records-1));
    int *key = malloc(sizeof(int)*max_records);
    short *index = malloc(sizeof(short)*max_records);
    Record *record = calloc(max_records, sizeof(Record));
    Config *config = malloc(sizeof(Config)*max_configs);

    for (int i = 0; i < max_records-1; ++i) {
        offset[i] = i;
    }

    for (int i = 0; i < max_records; ++i) {
        key[i] = i;
        index[i] = (short)i;
        record[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Initialize config array with placeholder values
    for (int i = 0; i < max_configs; ++i) {
        config[i] = (Config){i, -1, -1};
    }

    return offset;
}

void transform_records(void* data, int max_records, Config* config) {
    long *offset = data;
    Record *record = (Record*)calloc(max_records, sizeof(Record));

    for (int i = 0; i < max_records; ++i) {
        int key = *(int*)((char*)offset + sizeof(long)*index[(int)data]);
        short index2 = *(short*)((char*)offset + sizeof(long)*key);
        Config config2 = config[index2];

        record[i].value += config2.config;
    }

    // Free old records and copy new ones
    free(record);
}
```

