[' Here's a simplified version of the requested function in C, focusing on the core requirements. This code does not include all the features you've mentioned but serves as a starting point for further development.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <sys/resource.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    pid_t pid;
    double cpu_usage;
    long memory_usage;
} ChildProcess;

struct logging_config {
    char *log_service;
    int log_interval;
};

struct resource_limits {
    double cpu_threshold;
    long memory_limit;
};

ChildProcess* create_child_process(const char *command) {
    pid_t pid = fork();

    if (pid == -1) {
        perror("Fork failed");
        return NULL;
    } else if (pid == 0) { // Child process
        execlp(command, command, NULL);
        perror("Execlp failed");
        exit(EXIT_FAILURE);
    }

    return (ChildProcess*) malloc(sizeof(ChildProcess));
}

void monitor_resource_usage(ChildProcess *cp) {
    rusage usage;
    getrusage(RUSAGE_CHILDREN, &usage);

    double cpu_usage = usage.ru_utime.tv.sec + usage.ru_stime.tv.sec;
    long memory_usage = usage.ru_maxrss * getpagesize();

    cp->cpu_usage = cpu_usage;
    cp->memory_usage = memory_usage;
}

int check_resource_limits(ChildProcess *cp, struct resource_limits limits) {
    static int cpu_consecutive_overloads = 0;
    static int memory_consecutive_overloads = 0;

    if (cp->cpu_usage > limits.cpu_threshold && ++cpu_consecutive_overloads >= 4) {
        return 0;
    } else if (cp->memory_usage > limits.memory_limit && ++memory_consecutive_overloads >= 3) {
        return 0;
    }

    cpu_consecutive_overloads = memory_consecutive_overloads = 0;
    return 1;
}

void log_resource_usage(const ChildProcess *cp, struct logging_config config) {
    // Implement logging to the specified service with the given interval.
}

int execute_command_in_background(const char *command, struct resource_limits limits, struct logging_config config) {
    ChildProcess *cp = create_child_process(command);

    if (!cp) {
        return 0;
    }

    monitor_resource_usage(cp);

    while (check_resource_limits(cp, limits)) {
        sleep(1);
        monitor_resource_usage(cp);
    }

    waitpid(cp->pid, NULL, 0);
