    std::queue<std::function<void()>> m_tasks;
    std::mutex m_taskMutex;

    void processTasks();
};

struct Vertex {
    std::string uuid;
    std::vector<Edge> edges;
};

struct Edge {
    std::string src, dest;
};

void SandeshClient::addVertex(const std::string& metadataIp) {
    auto vertex = createVertex();
    m_vertices[metadataIp] = vertex;
    m_tasks.emplace([this, metadataIp, vertex]() { processAddVertex(metadataIp, vertex); });
}

void SandeshClient::addEdge(const std::string& src, const std::string& dest) {
    auto itrSrc = m_vertices.find(src);
    auto itrDest = m_vertices.find(dest);

    if (itrSrc != m_vertices.end() && itrDest != m_vertices.end()) {
        itrSrc->second.edges.push_back({src, dest});
        itrDest->second.edges.push_back({dest, src});
        m_tasks.emplace([this, src, dest]() { processAddEdge(src, dest); });
    }
}

void SandeshClient::processTasks() {
    std::unique_lock<std::mutex> lock(m_taskMutex);
    while (!m_tasks.empty()) {
        auto task = m_tasks.front();
        m_tasks.pop();
        lock.unlock();
        std::thread(task).detach();
        lock.lock();
    }
}

// Implement processAddVertex, processAddEdge, createVertex, and other necessary functions
