#include <cstdlib>
#include <ctime>

void MemoryManager::initialize(size_t offsetsSize, size_t keysSize) {
    rng_.seed(static_cast<unsigned int>(std::time(0)));
    offsets_.resize(offsetsSize);
    for (auto& offset : offsets_) {
        offset = -1;
    }
    measurements_.clear();
}

Measurement* MemoryManager::allocateMeasurement() {
    int key;
    do {
        key = rng_() % keysSize;
    } while (measurements_.find(key) != measurements_.end());

    long offset = findFreeOffset();
    if (offset == -1) {
        throw std::runtime_error("Out of memory");
    }

    Measurement* measurement = new Measurement(offset, key, generateRandomString());
    measurements_[key] = measurement;
    return measurement;
}

void MemoryManager::deallocateMeasurement(Measurement* measurement) {
    int key = measurement->getKey();
    offsets_[measurement->getOffset()] = -1;
    measurements_.erase(key);
    delete measurement;
}

long MemoryManager::findFreeOffset() {
    for (size_t i = 0; i < offsets_.size(); ++i) {
        if (offsets_[i] == -1) {
            return i;
        }
    }
    return -1;
}

std::string MemoryManager::generateRandomString() {
