import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;
import com.fasterxml.jackson.databind.*;
import okhttp3.*;

enum Task {
    TASK1(1, 500),
    TASK2(2, 1000),
    // Add more tasks as needed
    ;

    private final int priority;
    private final long interval;

    Task(int priority, long interval) {
        this.priority = priority;
        this.interval = interval;
    }

    public int getPriority() {
        return priority;
    }

    public long getInterval() {
        return interval;
    }
}

class TaskData {
    private final Queue<Task> tasks;
    private final Map<Task, Long> nextExecutionTimes;
    private final Lock lock;

    public TaskData() {
        this.tasks = new PriorityQueue<>(Arrays.asList(Task.values()), Comparator.comparingInt(Task::getPriority));
        this.nextExecutionTimes = new HashMap<>();
        this.lock = new ReentrantLock();
    }

    public void addTask(Task task) {
        lock.lock();
        try {
            tasks.add(task);
            nextExecutionTimes.put(task, System.currentTimeMillis() + task.getInterval());
        } finally {
            lock.unlock();
        }
    }

    public Task pollTask() throws InterruptedException {
        lock.lock();
        try {
            long currentTime = System.currentTimeMillis();
            for (Task task : tasks) {
                if (nextExecutionTimes.get(task) <= currentTime) {
                    Task polledTask = tasks.poll();
                    nextExecutionTimes.remove(polledTask);
                    long newInterval = polledTask.getInterval();
                    if (newInterval > 0) {
                        nextExecutionTimes.put(polledTask, currentTime + newInterval);
                    }
                    return polledTask;
                }
            }
            return null;
        } finally {
            lock.unlock();
        }
    }
}

class ResourceScheduler implements Runnable {
    private final TaskData taskData;
    private final ExecutorService executor;
    private final OkHttpClient httpClient;

    public ResourceScheduler(TaskData taskData, ExecutorService executor, OkHttpClient httpClient) {
        this.taskData = taskData;
        this.executor = executor;
        this.httpClient = httpClient;
    }

    @Override
    public void run() {
        while (true) {
            Task task = null;
            try {
                task = taskData.pollTask();
                if (task != null) {
                    executor.submit(() -> executeTask(task));
                }
            } catch (InterruptedException e) {
                // Handle interruptions gracefully
            }
        }
    }

    private void executeTask(Task task) {
        // Implement task execution logic here
    }
}
```

