    int min_value, max_value;

public:
    DataStructure(unsigned long size, int min_value, int max_value)
        : size(size), min_value(min_value), max_value(max_value) {
        if (size == 0 || min_value <= 0 || max_value <= 0) {
            throw std::invalid_argument("Invalid input");
        }

        offsets.resize(size);
        keys.resize(size / 2);
        records.resize(size);

        for (long i = 0; i < size; ++i) {
            offsets[i] = i;
        }

        for (int i = 0; i < size / 2; ++i) {
            keys[i] = i * 2;
        }
    }

    void set_values() {
        srand(time(nullptr));

        for (unsigned long i = 0; i < size; ++i) {
            records[offsets[i]].value = rand() % (max_value - min_value + 1) + min_value;
        }
    }

    Record& get_record(int key) {
        std::lock_guard<std::mutex> lock(mtx);

        for (unsigned long i = 0; i < size; ++i) {
            if (keys[i] == key) {
                return records[offsets[i]];
            }
        }

        throw std::out_of_range("Key not found");
    }

    ~DataStructure() {
        offsets.clear();
        keys.clear();
        records.clear();
