using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Newtonsoft.Json;
using NLog;
using Observable = Rx.Observable;

public class PerformanceDataAggregator
{
    private readonly Logger _logger;
    private readonly ConcurrentDictionary<string, IMetricSource> _sources;
    private readonly ConcurrentQueue<PerformanceMetric> _buffer;
    private readonly TimeSpan _aggregationInterval;
    private readonly AggregationStrategy _aggregationStrategy;
    private readonly int _alertThreshold;
    private readonly string _storageBackend;
    private readonly Observable.Subject<PerformanceMetric> _output;

    public PerformanceDataAggregator(
        Logger logger,
        ConcurrentDictionary<string, IMetricSource> sources,
        TimeSpan aggregationInterval,
        AggregationStrategy aggregationStrategy,
        int alertThreshold,
        string storageBackend)
    {
        _logger = logger;
        _sources = sources;
        _aggregationInterval = aggregationInterval;
        _aggregationStrategy = aggregregationStrategy;
        _alertThreshold = alertThreshold;
        _storageBackend = storageBackend;
        _buffer = new ConcurrentQueue<PerformanceMetric>();
        _output = Observable.Create<PerformanceMetric>(observer =>
        {
            observer.OnNext(GetAggregatedData());
            return () => { };
        });

        var backpressureThreshold = CalculateBackpressureThreshold();
        var cancellationTokenSource = new CancellationTokenSource();

        Observable.Merge(_sources.Values)
            .BufferTime(aggregationInterval, aggregationInterval)
            .Where(buffer => buffer.Count() > backpressureThreshold)
            .Subscribe(buffer =>
            {
                _buffer.EnqueueRange(buffer);
                CheckForAlerts();
            });

        var processingTask = Observable.FromEnumerable(_buffer)
            .Throttle(TimeSpan.FromMilliseconds(100))
            .Subscribe(metric => ProcessMetric(metric));

        Task.Run(() =>
        {
            while (!cancellationTokenSource.IsCancellationRequested)
            {
                if (_buffer.Count > backpressureThreshold)
                {
                    cancellationTokenSource.Cancel();
                }

                Thread.Sleep(_aggregationInterval);
                _output.OnNext(GetAggregatedData());
            }
        }, cancellationTokenSource.Token);
    }

    private PerformanceMetric GetAggregatedData()
    {
        var aggregatedData = _aggregationStrategy.Aggregate(_buffer.ToList());
        if (aggregatedData.IsAlertTriggered)
        {
            _logger.Warn($"Performance alert triggered: {JsonConvert.SerializeObject(aggregatedData)}");
        }

        StoreMetrics(_buffer.ToList());
        _buffer.Clear();
        return aggregatedData;
    }

    private void CheckForAlerts()
    {
        var currentAggregate = GetAggregatedData();
        if (currentAggregate.Value > _alertThreshold)
        {
            _logger.Warn($"Performance alert triggered: {JsonConvert.SerializeObject(currentAggregate)}");
        }
    }

    private void ProcessMetric(PerformanceMetric metric)
    {
