[' Here's a C++ implementation that addresses your requirements using the Standard Template Library (STL) and some modern C++ features:

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <random>
#include <thread>
#include <mutex>

struct Record {
    std::string data;
    double numeric;
};

class SimplifiedDatabase {
public:
    SimplifiedDatabase(size_t max_rows, size_t max_string_length)
        : max_rows_(max_rows), max_string_length_(max_string_length),
          primaryKeys_(max_rows_, -1), foreignKeys_(), records_() {}

    void* init() {
        if (foreignKeys_.empty()) {
            for (size_t i = 0; i < max_rows_; ++i) {
                foreignKeys_[i] = i;
            }
            std::shuffle(foreignKeys_.begin(), foreignKeys_.end(), std::mt19937{std::random_device{}()});
        }

        for (auto& record : records_) {
            record.data.resize(std::uniform_int_distribution<size_t>(1, max_string_length_).operator()(rng));
            record.numeric = std::uniform_real_distribution<double>{0.0, 1.0}.operator()(rng);
        }

        if (!checkIntegrity()) {
            return nullptr;
        }

        return &primaryKeys_[0];
    }

    void resize(size_t newSize) {
        if (newSize > max_rows_) {
            throw std::runtime_error("Cannot increase the number of rows beyond the maximum limit.");
        }

        auto oldRecords = std::move(records_);
        records_.resize(newSize);
        for (size_t i = 0; i < newSize && i < oldRecords.size(); ++i) {
            records_[i] = std::move(oldRecords[i]);
        }
        max_rows_ = newSize;
    }

    void cleanup() {
        primaryKeys_.clear();
        foreignKeys_.clear();
        records_.clear();
    }

private:
    bool checkIntegrity() const {
        std::mutex mtx;
        std::unordered_map<int, size_t> foreignKeyMap;
        for (size_t i = 0; i < max_rows_; ++i) {
            if (foreignKeys_[i] >= max_rows_) {
                return false;
            }
            if (foreignKeyMap.find(foreignKeys_[i]) != foreignKeyMap.end()) {
                return false;
            }
            foreignKeyMap[i] = i;
        }
        return true;
    }

    size_t max_rows_;
    size_t max_string_length_;
    std::vector<long> primaryKeys_;
    std::vector<int> foreignKeys_;
    std::vector<Record> records_;
    std::mt11213b rng; // Mersenne Twister PRNG for generating random numbers
};
```

