const int MAX_CAPACITY = 15000;
std::vector<int> data;
std::map<std::string, int> fieldMap;
std::mutex mtx;

void handleField(const std::string& name, const std::function<int(const std::string&)>& callback) {
    std::lock_guard<std::mutex> lock(mtx);
    if (fieldMap.find(name) != fieldMap.end()) {
        int id = fieldMap[name];
        data[id] = callback(name);
        // Send message to parent window with updated value
    } else {
        BOOST_LOG_TRIVIAL(info) << "Field not found: " << name;
    }
}

void processInput(const std::string& input, const std::vector<std::string>& fieldNames, int resourceId, const std::string& url) {
    std::istringstream iss(input);
    int num;
    while (iss >> num) {
        if (data.size() >= MAX_CAPACITY) {
            data.resize(MAX_CAPACITY);
        }
        data.push_back(num);
        std::sort(data.begin(), data.end(), std::greater<int>());

        for (const auto& fieldName : fieldNames) {
            handleField(fieldName, [=](const std::string& name) -> int { return num; });
        }
    }
}

void exportData() {
    std::ofstream file("data.csv");
    if (file.is_open()) {
        for (const auto& num : data) {
            file << num << ",";
        }
        file.close();
    } else {
        BOOST_LOG_TRIVIAL(error) << "Failed to open data file";
    }
}
