        records[i].str = malloc(strlen(str) + 1);
        if (!records[i].str) {
            free(records);
            return NULL;
        }
        strcpy(records[i].str, str);
    }

    pthread_key_delete(key);
    return records;
}

// Function to deallocate memory and handle memory leaks
