unsigned long hash(const char *str, unsigned long len) {
    unsigned long hash = 5381;
    for (int i = 0; i < len; ++i)
        hash = ((hash << 5) + hash) + str[i]; /* hash * 33 + c */
    return hash % 10000000;
}

int find_empty_slot(Record* table, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_lock(&mutex);
        if (!table[i].key) {
            pthread_mutex_unlock(&mutex);
            return i;
        }
        pthread_mutex_unlock(&mutex);
    }
    return -1;
}

void resize_hash_table(Record* table, size_t current_size, size_t new_size) {
    Record* new_table = (Record*)realloc(table, new_size * sizeof(Record));
    if (!new_table) return;
    memcpy(new_table + current_size, table, current_size * sizeof(Record));
    free(table);
    table = new_table;
}
