        while (it != keys.end() && *it == key) {
            key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
            it = std::find(keys.begin(), keys.end(), key);
        }
    }

    std::mt19937 gen(std::random_device{}());
    for (auto& record : records) {
        record.value = rand() % (MAX_RECORD_VALUE - MIN_RECORD_VALUE + 1) + MIN_RECORD_VALUE;
        mtx.lock();
        auto it = std::find(records.begin(), records.end(), record);
        while (it != records.end() && it->value == record.value) {
            record.value = rand() % (MAX_RECORD_VALUE - MIN_RECORD_VALUE + 1) + MIN_RECORD_VALUE;
            it = std::find(records.begin(), records.end(), record);
        }
        mtx.unlock();
    }
}

void serialize(const std::vector<Record>& records, std::ostream& out) {
    for (const auto& record : records) {
        out << record.value << '\n';
    }
}

std::vector<Record> deserialize(std::istream& in) {
    std::vector<Record> result;
    Record record;
    while (in >> record.value) {
        result.push_back(record);
    }
    return result;
}
