#include <iostream>
#include <vector>
#include <cstdlib>
#include <ctime>
#include <stdexcept>
#include <memory>
#include <functional>
#include <string>

struct Record {
    int value;
};

class MemoryPool {
public:
    MemoryPool(size_t blockSize) : _blockSize(blockSize), _freeList(nullptr) {}

    void* allocate() {
        if (_freeList == nullptr) {
            _blocks.emplace_back(std::make_unique<char[]>(_blockSize));
            _freeList = _blocks.back().get();
        }

        auto result = _freeList;
        _freeList += _blockSize;
        return result;
    }

    void deallocate(void* ptr) {
        if (ptr >= _freeList) {
            throw std::runtime_error("Trying to free memory beyond the end of the block");
        }
        _freeList = static_cast<char*>(ptr);
    }

private:
    size_t _blockSize;
    std::vector<std::unique_ptr<char[]>> _blocks;
    char* _freeList;
};

class LoggingSystem {
public:
    void log(const std::string& message) {
        std::cout << "Log: " << message << std::endl;
    }
};

void fillRecordsWithRandomValues(MemoryPool& pool, std::vector<Record>& records, int minValue, int maxValue) {
    for (auto& record : records) {
        auto* data = static_cast<int*>(pool.allocate());
        *data = rand() % (maxValue - minValue + 1) + minValue;
        record.value = *data;
        pool.deallocate(data);
    }
}

void service(MemoryPool& pool, LoggingSystem& log, std::vector<Record>& records, int operationCount, int minDelay, int maxDelay) {
    for (int i = 0; i < operationCount; ++i) {
        std::this_thread::sleep_for(std::chrono::milliseconds(rand() % (maxDelay - minDelay + 1) + minDelay));

        if (i % 2 == 0) {
            log.log("Service started");
            fillRecordsWithRandomValues(pool, records, 0, 100);
        } else {
            log.log("Service stopped");
        }
    }
}

int main() {
    srand(time(nullptr));

    MemoryPool pool(sizeof(int));
    std::vector<Record> records;
    LoggingSystem log;

    fillRecordsWithRandomValues(pool, records, 0, 100);

    const int operationCount = 10;
    const int minDelay = 500;
    const int maxDelay = 2000;

    service(pool, log, records, operationCount, minDelay, maxDelay);

    return 0;
}
