import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.Collections;
import java.util.Random;
import java.util.stream.IntStream;

public class RecordManager {
    private static final int MIN_SIZE = 16;
    private static final int MAX_SIZE = 1024;
    private static final int CAPACITY = 16;

    private Object[] entries;
    private long[] offsets;
    private int[] keys;
    private int numEntries;
    private int capacity;
    private int minSize;
    private int maxSize;
    private Random random;

    public RecordManager() {
        this.capacity = CAPACITY;
        this.minSize = MIN_SIZE;
        this.maxSize = MAX_SIZE;
        this.entries = new Object[capacity];
        this.offsets = new long[capacity];
        this.keys = new int[capacity];
        this.numEntries = 0;
        this.random = new Random();

        for (int i = 0; i < capacity; ++i) {
            entries[i] = Arrays.copyOf(new byte[minSize], minSize);
            offsets[i] = -1;
            keys[i] = -1;
        }
    }

    public void destroy() {
        for (int i = 0; i < numEntries; ++i) {
            entries[i] = null;
        }
        Arrays.fill(entries, null);
        Arrays.fill(offsets, -1);
        Arrays.fill(keys, -1);
    }

    public void generateUniqueRecords(int minValue, int maxValue) {
        while (numEntries < capacity) {
            int key = random.nextInt(maxValue - minValue + 1) + minValue;
            if (findKeyIndex(key) == -1) {
                offsets[numEntries] = numEntries;
                keys[numEntries] = key;
                ++numEntries;
            }
        }
    }

    private int findKeyIndex(int key) {
        for (int i = 0; i < numEntries; ++i) {
            if (keys[i] == key) {
                return i;
            }
        }
        return -1;
    }

    public Object getEntryByKey(int key) throws IllegalStateException, IndexOutOfBoundsException {
        int index = findKeyIndex(key);
        if (index == -1) {
            throw new IllegalStateException("No entry found with key: " + key);
        }
        return entries[index];
    }

    public void setEntryByKey(int key, Object data) throws IllegalStateException, IndexOutOfBoundsException {
        int index = findKeyIndex(key);
        if (index == -1) {
            throw new IllegalStateException("No entry found with key: " + key);
        }
        entries[index] = data;
    }

    public byte[] serialize() throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(bos);
        oos.writeObject(this);
        return bos.toByteArray();
    }

    public static RecordManager deserialize(byte[] data) throws IOException, ClassNotFoundException, InstantiationException, IllegalAccessException {
        ByteArrayInputStream bis = new ByteArrayInputStream(data);
        ObjectInputStream ois = new ObjectInputStream(bis);
        return (RecordManager) ois.readObject();
    }
}
