    (mm->items[mm->count])->data = (char*)((char*)(mm->items[mm->count]) + sizeof(data_item));

    snprintf((mm->items[mm->count])->data, size, "Item %zu", mm->count);
    (mm->items[mm->count])->key = mm->count;
    mm->count++;

    log("Allocated data item at index %zu with size %zu and success status: %s", mm->count - 1, size, mm->failed ? "false" : "true");

    return mm->items[mm->count - 1];
}

void deallocate_data_item(struct mem_manager* mm, data_item* item) {
    free(item);
}

void resize_mem_manager(struct mem_manager* mm, size_t new_capacity) {
    data_item** new_items = realloc(mm->items, new_capacity * sizeof(data_item*));
    if (!new_items) return;

    mm->items = new_items;
    mm->capacity = new_capacity;
}

void destroy_mem_manager(struct mem_manager* mm) {
    for (size_t i = 0; i < mm->count; ++i) {
        deallocate_data_item(mm, mm->items[i]);
    }
    free(mm->items);
    free(mm);
}
```

