[' Here is a high-level outline of how you might structure this C function:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>

typedef struct {
    int rows;
    int cols;
    int nnz; // number of non-zero elements
    int *row_ptr;
    int *col_idx;
    double *values;
    pthread_mutex_t mutex;
} SparseMatrix;

SparseMatrix* create_sparse_matrix(int rows, int cols, int nnz) {
    // Validate input and ensure reasonable bounds are met
    if (rows <= 0 || cols <= 0 || nnz < 0) return NULL;

    SparseMatrix *sm = malloc(sizeof(SparseMatrix));
    sm->rows = rows;
    sm->cols = cols;
    sm->nnz = nnz;

    // Allocate memory for row_ptr, col_idx, and values
    sm->row_ptr = (int *) mmap(NULL, (size_t)(nnz + 2) * sizeof(int), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (sm->row_ptr == MAP_FAILED) return NULL;

    sm->col_idx = sm->row_ptr;
    sm->values = (double *)(sm->row_ptr + nnz + 2);

    // Initialize row_ptr and col_idx arrays
    *(sm->row_ptr++) = 0;
    for (int i = 0; i < nnz; ++i) {
        *(sm->col_idx++) = -1; // sentinel value to indicate empty slot
    }
    *(sm->col_idx++) = cols; // last entry indicates end of column indices

    pthread_mutex_init(&sm->mutex, NULL);
    return sm;
}

void destroy_sparse_matrix(SparseMatrix *sm) {
    if (munmap(sm->row_ptr, (size_t)(sm->nnz + 2) * sizeof(int)) == -1 || munmap(sm->values, (size_t)(sm->nnz) * sizeof(double)) == -1) {
        perror("Error unmapping memory");
    }
    free(sm);
}

