void check_size(size_t *size, size_t min, size_t max) {
    if (*size < min || *size > max) {
        fprintf(stderr, "Error: Size out of bounds. Expected between %zu and %zu.\n", min, max);
        exit(EXIT_FAILURE);
    }
}

void init_offsets(const char *filename, long **offsets) {
    off_t file_size = 0;
    struct stat st;

    if (stat(filename, &st) != 0) {
        perror("Error: Failed to get file size");
        exit(EXIT_FAILURE);
    }

    file_size = st.st_size;
    check_size((size_t *)&file_size, (size_t)1, (size_t)(~0ULL));

    *offsets = malloc(sizeof(long) * (file_size / 8));
    if (*offsets == NULL) {
        perror("Error: Failed to allocate memory for offsets");
        exit(EXIT_FAILURE);
    }
}

void init_keys(int key_count, int *keys) {
    check_size((size_t *)&key_count, 1, INT_MAX);

    *keys = malloc(sizeof(int) * key_count);
    if (*keys == NULL) {
        perror("Error: Failed to allocate memory for keys");
        exit(EXIT_FAILURE);
    }
}

void init_records(int record_count, int min, int max, record **records) {
    check_size((size_t *)&record_count, 1, INT_MAX);

    *records = malloc(sizeof(record) * record_count);
    if (*records == NULL) {
        perror("Error: Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL));

    for (int i = 0; i < record_count; ++i) {
        (*records)[i].value = rand() % (max - min + 1) + min;
    }
}

void deallocate(long *offsets, int *keys, record **records) {
    free(offsets);
    free(keys);
    free(*records);
}
