#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Node {
    double value;
    struct Node* next;
} Node;

Node* create_node(double value) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->value = value;
    node->next = NULL;
    return node;
}

void add_neighbor(Node** head, Node* neighbor) {
    if (*head == NULL) {
        *head = neighbor;
    } else {
        Node* current = *head;
        while (current->next != NULL) current = current->next;
        current->next = neighbor;
    }
}

void remove_node(Node** head, Node* node) {
    if (*head == node) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp);
    } else {
        Node* current = *head;
        while (current->next != node && current->next != NULL) current = current->next;
        if (current->next == NULL) return; // Node not found
        Node* temp = current->next;
        current->next = current->next->next;
        free(temp);
    }
}

