```cpp
#include <iostream>
#include <vector>
#include <string>
#include <mutex>
#include <random>
#include <functional>
#include <unordered_map>

struct Record {
    long offset;
    int key;
    int value;
};

class HashFunction {
public:
    virtual ~HashFunction() {}
    virtual std::string name() const = 0;
    virtual size_t operator()(const void* data, size_t length) const = 0;
};

class BlockCipher {
public:
    virtual ~BlockCipher() {}
    virtual std::string name() const = 0;
    virtual void encrypt(const void* plaintext, size_t length, void* ciphertext) const = 0;
    virtual void decrypt(const void* ciphertext, size_t length, void* plaintext) const = 0;
};

class MemoryManager {
private:
    std::vector<Record> records;
    std::unordered_map<std::string, HashFunction*> hashFunctions;
    std::unordered_map<std::string, BlockCipher*> blockCiphers;
    std::mutex mtx;

public:
    MemoryManager(size_t numRecords, const long* offsets, int minValue, int maxValue) {
        records.resize(numRecords);
        for (size_t i = 0; i < numRecords; ++i) {
            records[i].offset = offsets[i];
            records[i].value = std::rand() % (maxValue - minValue + 1) + minValue;
        }
    }

    void addHashFunction(const std::string& name, HashFunction* function) {
        std::unique_lock<std::mutex> lock(mtx);
        hashFunctions[name] = function;
    }

    void addBlockCipher(const std::string& name, BlockCipher* cipher) {
        std::unique_lock<std::mutex> lock(mtx);
        blockCiphers[name] = cipher;
    }

    const Record* getRecordByOffset(long offset) const {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = std::find_if(records.begin(), records.end(), [&](const Record& r) { return r.offset == offset; });
        if (it != records.end())
            return &*it;
        return nullptr;
    }

    const HashFunction* getHashFunction(const std::string& name) const {
        auto it = hashFunctions.find(name);
        return it != hashFunctions.end() ? it->second : nullptr;
    }

    const BlockCipher* getBlockCipher(const std::string& name) const {
        auto it = blockCiphers.find(name);
        return it != blockCiphers.end() ? it->second : nullptr;
    }

    ~MemoryManager() {
        records.clear();
        for (auto& pair : hashFunctions)
            delete pair.second;
        for (auto& pair : blockCiphers)
            delete pair.second;
    }
};

// Example of an external data source providing offset values
