#include <boost/serialization/array.hpp>
#include <boost/serialization/utility.hpp>

struct Record {
    int value;
    friend class boost::serialization::access;

    template<class Archive>
    void serialize(Archive & ar, const unsigned int version) {
        ar & value;
    }
};

std::mutex mtx;

void validateSize(size_t size, size_t lowerBound, size_t upperBound) {
    if (size < lowerBound || size > upperBound) {
        throw std::invalid_argument("Invalid size");
    }
}

void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        throw std::bad_alloc();
    }
    return ptr;
}

void deallocateMemory(void* ptr, size_t size) {
    free(ptr);
}

std::vector<long> createOffsetArray(size_t size) {
    validateSize(size, 1, std::numeric_limits<long>::max());
    auto offsets = (long*)allocateMemory(sizeof(long) * size);
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = i;
    }
    return std::vector<long>(offsets, offsets + size);
}

std::vector<int> createKeyArray(size_t size) {
    validateSize(size, 1, std::numeric_limits<int>::max());
    auto keys = (int*)allocateMemory(sizeof(int) * size);
    for (size_t i = 0; i < size; ++i) {
        keys[i] = i;
    }
    return std::vector<int>(keys, keys + size);
}

std::vector<Record> createRecordArray(size_t numRecords) {
    validateSize(numRecords, 1, std::numeric_limits<unsigned>::max());
    auto records = (Record*)allocateMemory(sizeof(Record) * numRecords);
    for (size_t i = 0; i < numRecords; ++i) {
        records[i].value = rand() % 100; // Random value within range [0, 99]
    }
    return std::vector<Record>(records, records + numRecords);
}

void ensureUnique(const std::vector<int>& values) {
    std::unordered_set<int> uniqueValues(values.begin(), values.end());
    if (uniqueValues.size() != values.size()) {
        throw std::runtime_error("Duplicate values detected");
    }
}

void setUniqueValues(std::vector<Record>& records, const std::vector<int>& keys) {
    ensureUnique(keys);
    for (size_t i = 0; i < keys.size(); ++i) {
        mtx.lock();
        records[keys[i]].value = rand() % 100; // Random value within range [0, 99]
        mtx.unlock();
    }
}

void saveRecords(const std::vector<Record>& records, const std::string& filename) {
    std::ofstream file(filename, std::ios::binary);
    boost::serialization::serialize(file, records);
}

std::vector<Record> loadRecords(const std::string& filename) {
    std::ifstream file(filename, std::ios::binary);
    std::vector<Record> records;
    boost::serialization::deserialize(file, records);
    return records;
}
```

