```cpp
#include <iostream>
#include <vector>
#include <mutex>
#include <atomic>
#include <thread>
#include <future>

std::mutex mtx;
std::atomic<int> nextKey(1);
std::atomic<long> maxOffset(0);

struct Record {
    int key;
    long offset;
};

struct DataContainer {
    Record* record;
    std::atomic<int> counter{ 0 };
};

void initializeRecords(std::vector<Record*> &records) {
    for (auto &record : records) {
        record->key = nextKey++;
        record->offset = 5 * (record->key % 200);
        if (record->offset > maxOffset) maxOffset = record->offset;
    }
}

void allocateAndInitialize(std::vector<Record*> &records, std::vector<DataContainer> &dataContainers) {
    records.resize(100);
    dataContainers.resize(10);
    initializeRecords(records);

    for (auto &container : dataContainers) {
        container.record = &records[container.counter];
    }
}

void updateOffset(DataContainer &dataContainer, long newOffset) {
    std::unique_lock<std::mutex> lock(mtx);

    while (dataContainer.record->offset != dataContainer.counter) {
        mtx.wait(lock);
    }

    if (newOffset > maxOffset || newOffset % 5 != 0) {
        std::cerr << "Invalid offset value: " << newOffset << std::endl;
        return;
    }

    dataContainer.record->offset = newOffset;
    dataContainer.counter++;
}

void setMaxOffset(long max) {
    mtx.lock();
    maxOffset = max;
    mtx.unlock();
}

void freeMemory(std::vector<Record*> &records, std::vector<DataContainer> &dataContainers) {
    for (auto record : records) delete record;
    records.clear();

    for (auto &container : dataContainers) delete &container;
    dataContainers.clear();
}
