#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Project {
    char name[256];
    int priority;
    char* description;
    struct Project* dependencies;
    struct Project* next;
} Project;

Project* create_project(const char* name, int priority, const char* description) {
    Project* project = (Project*)malloc(sizeof(Project));
    strcpy(project->name, name);
    project->priority = priority;
    project->description = strdup(description);
    project->dependencies = NULL;
    project->next = NULL;
    return project;
}

void add_project(Project** head, Project* project) {
    if (*head == NULL) {
        *head = project;
    } else {
        Project* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = project;
    }
}

void remove_project(Project** head, const char* name) {
    Project* current = *head;
    Project* previous = NULL;

    while (current != NULL && strcmp(current->name, name) != 0) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        fprintf(stderr, "Project not found\n");
        return;
    }

    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current->description);
    free(current);
}

Project* find_highest_priority(const Project* head) {
    Project* highest_priority = NULL;
    while (head != NULL) {
        if (highest_priority == NULL || head->priority > highest_priority->priority) {
            highest_priority = head;
        }
        head = head->next;
    }
    return highest_priority;
}

void add_dependency(Project* project, const char* dependency_name) {
    Project* current = *project->dependencies;
    while (current != NULL && strcmp(current->name, dependency_name) != 0) {
        current = current->next;
    }

    if (current == NULL) {
        project->dependencies = malloc(sizeof(Project));
        *project->dependencies = *find_project(head, dependency_name);
        project->dependencies->next = project->dependencies;
    }
}

Project* find_project(const Project* head, const char* name) {
    for (Project* current = head; current != NULL; current = current->next) {
        if (strcmp(current->name, name) == 0) {
            return current;
        }
    }
    fprintf(stderr, "Project not found\n");
    return NULL;
}

void update_description(Project* project, const char* new_description) {
    if (project->description != NULL) {
        free(project->description);
    }
    project->description = strdup(new_description);
}
```

