[' Here's a C implementation using a dynamic array for efficient memory usage and linked list for easy extension and modification of data structures. I've also included error handling for memory allocation failures and optimized the function for performance.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct Record {
    long offset;
    int *key;
    struct Record *next;
} Record;

typedef struct Set {
    Record **records;
    size_t capacity;
    size_t size;
    size_t offsets;
    size_t keys;
    long min_value;
    long max_value;
} Set;

Set *create_set(size_t offsets, size_t keys, long min_value, long max_value) {
    Set *set = malloc(sizeof(Set));
    if (!set) return NULL;

    set->offsets = offsets;
    set->keys = keys;
    set->min_value = min_value;
    set->max_value = max_value;

    set->records = malloc(offsets * sizeof(Record*));
    if (!set->records) {
        free(set);
        return NULL;
    }

    for (size_t i = 0; i < offsets; ++i) {
        set->records[i] = NULL;
    }

    set->capacity = offsets;
    set->size = 0;

    return set;
}

Record *create_record(long offset, int key) {
    Record *record = malloc(sizeof(Record));
    if (!record) return NULL;

    record->offset = offset;
    record->key = malloc(sizeof(int));
    if (!record->key) {
        free(record);
        return NULL;
    }

    *record->key = key;
    record->next = NULL;

    return record;
}

bool extend_set(Set *set, size_t new_capacity) {
    Record **new_records = realloc(set->records, new_capacity * sizeof(Record*));
    if (!new_records) return false;

    set->records = new_records;
    set->capacity = new_capacity;

    return true;
}

void free_record(Record **record) {
    if (*record) {
        free((*record)->key);
        free(*record);
        *record = NULL;
    }
}

void free_set(Set *set) {
    for (size_t i = 0; i < set->capacity; ++i) {
        Record *current = set->records[i];
        while (current) {
            Record *next = current->next;
            free_record(&current);
            current = next;
        }
    }

    free(set->records);
    free(set);
}

void insert_record(Set *set, long offset, int key) {
    if (offset >= set->capacity) {
        if (!extend_set(set, offset * 2)) {
            fprintf(stderr, "Failed to extend set\n");
            free_set(set);
            exit(EXIT_FAILURE);
        }
    }

    Record **current = &set->records[offset];
    while (*current) current = &(*current)->next;

    *current = create_record(offset, key);
    if (!*current) {
        fprintf(stderr, "Failed to allocate record\n");
        free_set(set);
        exit(EXIT_FAILURE);
    }

    set->size++;
}

int *find_record(Set *set, long offset) {
    if (offset >= set->capacity || offset < 0) return NULL;

    Record *current = set->records[offset];
    while (current) {
        if (current->offset == offset) return current->key;
        current = current->next;
    }

    return NULL;
}

int main() {
    srand(time(NULL));

    Set *set = create_set(10, 100, 0, RAND_MAX);
    if (!set) {
        fprintf(stderr, "Failed to create set\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < set->offsets; ++i) {
        long offset = rand() % set->offsets;
        int key = rand();
        insert_record(set, offset, key);
    }

    // Accessing records
    for (size_t i = 0; i < set->offsets; ++i) {
        int *key = find_record(set, i);
        if (key) printf("Record at offset %ld: %d\n", i, *key);
    }

    free_set(set);

    return EXIT_SUCCESS;
}
```

This implementation uses a dynamic array to store pointers to the records and a linked list for each array element to manage the records efficiently. The `create_set()` function initializes the set with the given parameters, while the `insert_record()` function adds new records to the set. The `find_record()` function searches for a record at a specific offset, and the main function demonstrates how to use these functions to create, insert, and access records in the set.']

[' Here's a simplified implementation of the `TaskScheduler` class in C#, using a self-balancing binary search tree (AVL Tree) for efficient memory management and performance under high concurrency. The class also includes methods to generate random values within a specified range using `UnityEngine.Random.Range`.

```csharp
using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class TaskScheduler
{
    private AVLTree<Task> _taskQueue;
    private float _minValue;
    private float _maxValue;

    public TaskScheduler(float minValue, float maxValue)
    {
        _taskQueue = new AVLTree<Task>();
        _minValue = minValue;
        _maxValue = maxValue;
    }

    public void Initialize()
    {
        // Initialize the task queue if needed
    }

    public void AddTask(string name, int priority, DateTime scheduledExecutionTime)
    {
        Task task = new Task(name, priority, scheduledExecutionTime);
        _taskQueue.Insert(task);
    }

    public bool RemoveTaskByName(string name)
    {
        return _taskQueue.RemoveByKey(name);
    }

    public void UpdateTask(Task task)
    {
        _taskQueue.Update(task);
    }

    public Task GetNextTask()
    {
        return _taskQueue.Minimum;
    }

    public float NextRandomFloat()
    {
        return UnityEngine.Random.Range(_minValue, _maxValue);
    }

    public int NextRandomInt()
    {
        return (int)UnityEngine.Random.Range((double)_minValue, (double)_maxValue + 1);
    }

    public override string ToString()
    {
        return $"Min: {_minValue}, Max: {_maxValue}";
    }

    private class Task : IComparable<Task>
    {
        public string Name { get; set; }
        public int Priority { get; set; }
        public DateTime ScheduledExecutionTime { get; set; }

        public Task(string name, int priority, DateTime scheduledExecutionTime)
        {
            Name = name;
            Priority = priority;
            ScheduledExecutionTime = scheduledExecutionTime;
        }

        public int CompareTo(Task other)
        {
            if (Priority != other.Priority)
                return Priority - other.Priority;

            return ScheduledExecutionTime.CompareTo(other.ScheduledExecutionTime);
        }
    }
}
```

