typedef struct {
    int value;
    enum { ACTIVE, INACTIVE } state;
} record;

struct data_structures {
    long *offsets;
    int *keys;
    record *records;
    size_t num_records;
    pthread_mutex_t mutex;
};

void init_data_structures(struct data_structures *ds, size_t num_records) {
    // Initialize mutex
    pthread_mutex_init(&ds->mutex, NULL);

    // Allocate memory for offsets and keys arrays
    ds->offsets = malloc(num_records * sizeof(long));
    if (!ds->offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        exit(EXIT_FAILURE);
    }

    // Initialize unique offset values within a specified range
    for (size_t i = 0; i < num_records; ++i) {
        ds->offsets[i] = i + MIN_OFFSET;
    }

    // Allocate memory for keys array using hash-based approach to avoid collisions
    size_t key_count = 0;
    ds->keys = calloc(num_records, sizeof(int));
    if (!ds->keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        exit(EXIT_FAILURE);
    }

    // External source containing duplicates keys
    int external_keys[] = {1, 2, 3, 4, 5, 5, 6, 7, 8, 9};
    size_t external_key_count = sizeof(external_keys) / sizeof(int);

    // Hash function for keys
    unsigned int hash(const void *key) {
        const int *k = (const int *) key;
        return (*k) % num_records;
    }

    // Resolve duplicates using a hash-based approach and ensure no collisions within the key array
    for (size_t i = 0; i < external_key_count; ++i) {
        size_t index = hash(external_keys + i);
        while (ds->keys[index] != 0) {
            index = (index + 1) % num_records;
        }
        ds->keys[index] = external_keys[i];
        key_count++;
    }

    // Allocate memory for records array
    ds->records = calloc(num_records, sizeof(record));
    if (!ds->records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        exit(EXIT_FAILURE);
    }

    // Initialize each record with a random value within a specified range and set state to ACTIVE
    for (size_t i = 0; i < num_records; ++i) {
        ds->records[i].value = rand() % MAX_VALUE;
        ds->records[i].state = ACTIVE;
    }

    // Set number of records
    ds->num_records = num_records;
}

void reset_data_structures(struct data_structures *ds) {
    pthread_mutex_lock(&ds->mutex);

    for (size_t i = 0; i < ds->num_records; ++i) {
        ds->records[i].value = 0;
        ds->records[i].state = INACTIVE;
    }

    pthread_mutex_unlock(&ds->mutex);
}

void selective_reset(struct data_structures *ds, size_t index) {
    pthread_mutex_lock(&ds->mutex);

    if (index < ds->num_records) {
        ds->records[index].value = 0;
        ds->records[index].state = INACTIVE;
    }

    pthread_mutex_unlock(&ds->mutex);
}
