import java.util.concurrent.Executors;

public class CompressionManager {
    private final Map<String, ProcessBuilder> compressors = new HashMap<>();

    public void addCompressor(String name, String command) {
        compressors.put(name, new ProcessBuilder(command));
    }

    public byte[] compress(byte[] data, String compressorName) throws IOException {
        ProcessBuilder pb = compressors.getOrDefault(compressorName, null);
        if (pb == null) throw new IllegalArgumentException("Unknown compressor: " + compressorName);

        Process process = pb.start();
        try (InputStream is = process.getInputStream()) {
            byte[] compressedData = is.readAllBytes();
            process.waitFor();
            return compressedData;
        }
    }

    public void zipArchive(String archivePath, List<File> files) throws IOException {
        try (ZipOutputStream zos = new ZipOutputStream(new FileOutputStream(archivePath))) {
            for (File file : files) {
                String fileName = file.getName();
                try (FileInputStream fis = new FileInputStream(file)) {
                    zos.putNextEntry(new ZipEntry(fileName));
                    byte[] buffer = new byte[8192];
                    int len;
                    while ((len = fis.read(buffer)) != -1) {
                        zos.write(buffer, 0, len);
                    }
                }
            }
        }
    }
}
