Record* create_records(long offset_size, long key_size, unsigned int num_records, unsigned int min_value, unsigned int max_value, unsigned int seed) {
    // Allocate memory for offset and key arrays
    long *offsets = malloc(offset_size * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offset array\n");
        return NULL;
    }

    int *keys = malloc(key_size * sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Failed to allocate memory for key array\n");
        return NULL;
    }

    // Initialize rollback mechanism
    Record *rollback_records = NULL;

    // Allocate memory for records
    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        fprintf(stderr, "Failed to allocate memory for record array\n");
        return NULL;
    }

    // Set up random number generator
    srand(seed);

    // Initialize pointers in records and generate random keys
    Record *current_record = records;
    for (unsigned int i = 0; i < num_records; ++i) {
        current_record->offset = offsets[i];
        current_record->key = min_value + rand() % (max_value - min_value + 1);
        current_record->next = NULL;

        // Update pointers in the offset and key arrays
        current_record->offset++;
        keys[i] = current_record->key;

        current_record = current_record->next;
    }

    // Handle potential external data source failures or network latency
    for (unsigned int i = num_records; i < offset_size; ++i) {
        if (!offsets[i]) {
            // If a missing element is encountered, set it to the last valid index and continue
            offsets[i] = offsets[num_records - 1];
        }
    }

    return records;
}

void rollback(Record *rollback_records, Record *current_records) {
    // Free all previously allocated memory in case of errors
    for (Record *temp = current_records; temp != NULL; ) {
        Record *next = temp->next;
        free(temp);
        temp = next;
    }

    free(rollback_records);
}
