```cpp
#include <iostream>
#include <vector>
#include <random>
#include <mutex>
#include <new>

struct Record {
    int id;
    long offset;
    void* data_ptr;
};

class DynamicDataset {
private:
    std::vector<Record> records;
    std::vector<long> offsets;
    std::mutex mtx;
    unsigned long capacity = 0;
    unsigned long size = 0;
    unsigned long min_allocation = 1024; // Minimum number of records to allocate at once
    unsigned long max_record_id = 0;
    std::random_device rd;
    std::mt19937 gen;
    std::uniform_int_distribution<> dis;

public:
    DynamicDataset(unsigned long min_allocation, unsigned long max, unsigned long seed) :
        rd(), gen(rd()), dis(0, max - 1), min_allocation(min_allocation) {
        gen.seed(seed);
        capacity = min_allocation;
    }

    ~DynamicDataset() {
        clear();
    }

    void clear() {
        for (auto& record : records) {
            if (record.data_ptr != nullptr) {
                delete[] static_cast<char*>(record.data_ptr);
            }
        }
        records.clear();
        offsets.clear();
        capacity = size = 0;
    }

    Record& add() {
        if (size >= capacity) {
            auto new_capacity = std::max(capacity * 2, min_allocation);
            auto new_records = std::vector<Record>(new_capacity);
            auto new_offsets = std::vector<long>(new_capacity);

            if (records.empty()) {
                for (unsigned long i = 0; i < new_capacity; ++i) {
                    new_records[i].id = i;
                    new_records[i].offset = i;
                    new_records[i].data_ptr = nullptr;
                    new_offsets[i] = 0;
                }
            } else {
                std::copy(records.begin(), records.end(), new_records.begin());
                std::copy(offsets.begin(), offsets.end(), new_offsets.begin());

                for (unsigned long i = size; i < new_capacity; ++i) {
                    new_records[i].id = i;
                    new_records[i].offset = offsets[size - 1] + size;
                    new_records[i].data_ptr = nullptr;
                    new_offsets[i] = offsets[size - 1] + size;
                }
            }

            records.swap(new_records);
            offsets.swap(new_offsets);
            capacity = new_capacity;
        }

        Record& record = records[size];
        record.id = max_record_id++;
        record.offset = offsets[size];
        record.data_ptr = new char[sizeof(long) * (max_record_id + 1)]; // Allocate enough space for all future records' long integers

        std::lock_guard<std::mutex> lock(mtx);
        offsets[size] += sizeof(long) * max_record_id;
        size++;

        return record;
    }

    Record& get(unsigned long id) {
        if (id >= max_record_id || id >= size) {
            throw std::out_of_range("Requested record ID is out of range.");
        }

        auto record = records[id];
        if (record.data_ptr == nullptr) {
            record.data_ptr = new char[sizeof(long) * (id + 1)]; // Allocate enough space for the requested record's long integers
        }

        return record;
    }
};
```

This implementation uses a `DynamicDataset` class to manage the dynamic dataset of records. The constructor takes in the minimum number of records to allocate at once, the maximum record ID, and an optional seed for the random number generator. The destructor clears all allocated memory.

The `add()` function adds a new record to the dataset, handling allocation failures gracefully by doubling the capacity when necessary. It also minimizes memory fragmentation by allocating enough space for all future records' long integers at once.

The `get()` function retrieves a specific record from the dataset, creating and initializing its long integer array if it hasn't been done yet. It throws an exception if the requested record ID is out of range.

Concurrent access to the dataset is managed using a mutex (`std::mutex`). This ensures that no two threads can modify the dataset simultaneously, preventing race conditions.']

