    uint32_t destIP;
    uint8_t protocol;
    size_t payloadLength;
};

class NetworkPackets {
public:
    NetworkPackets(const std::map<uint8_t, std::pair<size_t, char*>>& config) : _config(config), _capacity(64) {
        _packets = new Packet[_capacity];
    }

    ~NetworkPackets() {
        delete[] _packets;
    }

    void addPacket(const Packet& packet) {
        if (_index >= _capacity) {
            resize();
        }

        _packets[_index] = packet;
        _index++;
    }

    void removePacket(size_t index) {
        if (index >= _index || index >= _capacity) {
            throw std::out_of_range("Invalid index");
        }

        _packets[index] = _packets[_index - 1];
        _index--;
    }

    const Packet& getPacket(size_t index) const {
        if (index >= _index || index >= _capacity) {
            throw std::out_of_range("Invalid index");
        }

        return _packets[index];
    }

private:
    void resize() {
        Packet* newPackets = new Packet[_capacity * 2];
        std::copy(_packets, _packets + _index, newPackets);
        delete[] _packets;
        _packets = newPackets;
        _capacity *= 2;
    }

    std::map<uint8_t, std::pair<size_t, char*>> _config;
    Packet* _packets;
    size_t _index = 0;
    size_t _capacity;
};
