    pthread_mutex_lock(&mutex);
    if (index >= offsets->size || offsets->data[index].key == -1) {
        log("Invalid record index");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    pthread_mutex_unlock(&mutex);
    return &offsets->data[index];
}

void set_record(size_t index, Record* record) {
    pthread_mutex_lock(&mutex);
    if (index >= offsets->size) {
        Offset* new_offset = allocate_offset(offsets->capacity * 2);
        if (!new_offset) {
            pthread_mutex_unlock(&mutex);
            return;
        }
        size_t i;
        for (i = 0; i < offsets->size; ++i) {
            Record* current = &offsets->data[i];
            if (current->key != -1) {
                current->offset = index;
                offsets->data[index] = *current;
                offsets->data[i].key = -1;
            }
        }
        free_offset(offsets);
        offsets = new_offset;
    }
    Record* current = &offsets->data[index];
    if (current->key == -1) {
        current->key = index;
        current->value = record->value;
        current->offset = index;
    } else {
        log("Attempt to overwrite existing record");
    }
    pthread_mutex_unlock(&mutex);
}
