typedef struct {
    int id;
    long offset;
    void* data_ptr;
} Record;

Record* records = NULL;
long* offsets = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init(int size, int range) {
    records = malloc(size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }
    offsets = calloc(size + 1, sizeof(long));
    if (!offsets) {
        free(records);
        fprintf(stderr, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < size; ++i) {
        records[i].id = i;
        records[i].offset = offsets[i];
        records[i].data_ptr = malloc(sizeof(long));
        if (!records[i].data_ptr) {
            fprintf(stderr, "Memory allocation failure\n");
            exit(EXIT_FAILURE);
        }
        *(long*)records[i].data_ptr = rand() % range;
        offsets[i + 1] = offsetof(Record, data_ptr) + sizeof(long) + *(long*)records[i].data_ptr;
    }
}

void* get_record(int id) {
    pthread_mutex_lock(&lock);
    Record* record = &records[id];
    long offset = offsets[id];
    void* data_ptr = malloc(offset - offsetof(Record, data_ptr));
    if (!data_ptr) {
        fprintf(stderr, "Memory allocation failure\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    memcpy(data_ptr, record + 1, offset - offsetof(Record, data_ptr));
    pthread_mutex_unlock(&lock);
    return data_ptr;
}
