typedef struct Record {
    long offset;
    int key;
} Record;

unsigned long hash(long offset) {
    unsigned long hash = 5381;
    for (int i = 0; i < sizeof(offset) * CHAR_BIT; ++i) {
        hash = ((hash << 5) + hash) + (offset & 0xFF);
        offset >>= 8;
    }
    return hash % INT_MAX;
}

Record* create_record(long offset) {
    Record *record = malloc(sizeof(Record));
    if (!record) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }
    record->offset = offset;
    record->key = hash(offset);
    return record;
}

void* create_sparse_map(long start, long end, size_t *size) {
    if (start >= end) {
        printf("Invalid range: start (%ld) must be less than end (%ld)\n", start, end);
        return NULL;
    }

    void *sparse_map = calloc((end - start) + 1, sizeof(long));
    if (!sparse_map) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }

    *size = end - start + 1;
    return sparse_map;
}

void populate_sparse_map(void *sparse_map, Record **records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        long offset = records[i]->offset;
        if (offset >= ((long*)sparse_map - 1) && offset < ((long*)sparse_map + *(size_t*)sparse_map)) {
            ((long*)sparse_map)[offset - ((long*)sparse_map - 1)] = records[i]->key;
        }
    }
}

void validate_sparse_map(void *sparse_map, Record **records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        long offset = records[i]->offset;
        if (offset >= ((long*)sparse_map - 1) && offset < ((long*)sparse_map + *(size_t*)sparse_map)) {
            if (((long*)sparse_map)[offset - ((long*)sparse_map - 1)] != records[i]->key) {
                printf("Invalid sparse map: Offset %ld has key %d, but should have key %d\n", offset, ((long*)sparse_map)[offset - ((long*)sparse_map - 1)], records[i]->key);
            }
        }
    }
}

size_t populate(Record **records, size_t *record_count, size_t *sparse_map_size, long start, long end) {
    srand(time(NULL));

    for (*record_count = 0; *record_count < 100; ++*record_count) {
        Record *record = create_record((*record_count + 1) * rand());
        if (!record) {
            break;
        }
        records[*record_count] = record;
    }

    void *sparse_map = create_sparse_map(start, end);
    if (sparse_map) {
        populate_sparse_map(sparse_map, records, *record_count);
        validate_sparse_map(sparse_map, records, *record_count);
        free(sparse_map);
    }

    return *record_count;
}
```

