    }

    record_t *records = NULL;
    size_t records_size = max_records * (record_size + sizeof(long) * 2);
    if (posix_memalign((void**)&records, boundary, records_size) != 0) {
        perror("Error allocating record array");
        free(offsets);
        free(keys);
        fclose(file);
        return NULL;
    }

    offsets[0] = offset_start;
    keys[0] = key_start;

    srand(time(NULL));
    for (size_t i = 1; i <= max_records; ++i) {
        records[i - 1].offset = offsets[i - 1];
        records[i - 1].key = keys[i - 1];
        records[i - 1].value = rand() % record_range + 1;
        offsets[i] = records[i - 1].offset + sizeof(record_t);
        keys[i] = records[i - 1].key + 1;
    }

    if (free_all) {
        free(offsets);
        free(keys);
        munmap(records, records_size);
    }

    fclose(file);
    return records;
}
