#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdbool.h>

typedef struct Record {
    long offset;
    int key;
    char description[65]; // 1 extra for null terminator
} Record;

// Custom hash function that generates pronounceable strings
char* generate_description(long offset) {
    static const char alphabet[] = "abcdefghijklmnopqrstuvwxyz";
    char *desc = malloc(64);
    for (int i = 0; i < 64; ++i) {
        desc[i] = alphabet[(offset * i + 31) % 26];
    }
    desc[64] = '\0';
    return desc;
}

// Custom hash function for evaluating the impact on retrieval speed
unsigned long fast_hash(long offset) {
    unsigned long hash = 5381;
    for (int i = 0; i < sizeof(long); ++i) {
        hash = ((hash << 5) + hash) + offset[i];
    }
    return hash % (1LL << 32); // Ensure the result fits within an int
}

// Sparse map structure
typedef struct SparseMap {
    Record** records;
    unsigned long size, capacity;
} SparseMap;

void sparse_map_init(SparseMap* map, unsigned long capacity) {
    map->records = malloc(capacity * sizeof(Record*));
    for (unsigned long i = 0; i < capacity; ++i) {
        map->records[i] = NULL;
    }
    map->size = 0;
    map->capacity = capacity;
}

void sparse_map_resize(SparseMap* map, unsigned long new_capacity) {
    Record** temp = malloc(new_capacity * sizeof(Record*));
    for (unsigned long i = 0; i < min(map->capacity, new_capacity); ++i) {
        if (map->records[i]) {
            temp[i] = map->records[i];
        }
    }
    free(map->records);
    map->records = temp;
    map->capacity = new_capacity;
}

void sparse_map_insert(SparseMap* map, Record* record) {
    unsigned long index = fast_hash(record->offset) % map->capacity;
    while (map->records[index]) {
        if (map->records[index]->offset == record->offset) {
            // Overwrite existing entry if it already exists
            free(map->records[index]->description);
            strcpy(map->records[index]->description, record->description);
            map->records[index]->key = record->key;
            return;
        }
        index = (index + 1) % map->capacity;
    }
    if (map->size >= map->capacity) {
        sparse_map_resize(map, map->capacity * 2);
    }
    map->records[index] = record;
    ++map->size;
}

Record* sparse_map_find(const SparseMap* map, long offset) {
    unsigned long index = fast_hash(offset) % map->capacity;
    for (; map->records[index]; index = (index + 1) % map->capacity) {
        if (map->records[index]->offset == offset) {
            return map->records[index];
        }
    }
    return NULL;
}

// Serialization and deserialization functions are omitted for brevity.

unsigned long count_populated(const SparseMap* map) {
    unsigned long count = 0;
    for (unsigned long i = 0; i < map->capacity; ++i) {
        if (map->records[i]) {
            ++count;
        }
    }
    return count;
}
```

