            shapes = realloc(shapes, (shape_count + 1) * sizeof(Shape));
            shapes[shape_count].vertices = total_vertices;
            shapes[shape_count].coords = malloc(2 * total_vertices * sizeof(double));
            fscanf(file, "COORDINATES %*s", shapes[shape_count].coords);
            shape_count++;
        }
    }
