void populate_sparse_map(Record** map, Shape* shapes, int shape_count) {
    for (int i = 0; i < shape_count; ++i) {
        long offset = i * (2 * shapes[i].vertices);
        unsigned long key = hash(offset);
        while (map[key])
            key = (key + 1) % size;
        map[key] = malloc(sizeof(Record));
        map[key]->offset = offset;
        map[key]->key = i;
    }
}

int main() {
    const char* filename = "geometry.txt";
    int min_vertices = 4;
    Shape* shapes = parse_geometry_file(filename, min_vertices);
