    populate_sparse_map(sparse_map, shapes, shapes ? shapes[0].vertices : 0);

    int count = 0;
    for (int i = 0; i < 1000000; ++i) {
        if (sparse_map[i])
            count++;
    }

    printf("Number of shapes: %d\n", count);
