void init_record_pool(size_t initialRecords) {
    if ((recordPool = malloc(initialRecords * recordSize)) == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

Record* get_record_from_pool() {
    Record* record;

    if (recordPool != NULL && (size_t)(recordPool + recordSize) <= (size_t)&recordPool[initialRecords]) {
        record = (Record*)((char*)recordPool);
        recordPool += recordSize;
    } else {
        init_record_pool(initialRecords * 2);
        record = get_record_from_pool();
    }

    return record;
}

void free_record(Record* record) {
    if (recordPool != NULL && (char*)record < (char*)&recordPool[0]) {
        memcpy((char*)recordPool - recordSize, record, recordSize);
    }
}

void init_records(Record** records, size_t numRecords, size_t minNumRecords, size_t maxNumRecords) {
    if (numRecords < minNumRecords || numRecords > maxNumRecords) {
        fprintf(stderr, "Invalid number of records\n");
        exit(EXIT_FAILURE);
    }

    *records = malloc(numRecords * sizeof(Record));

    pthread_t threads[numRecords];
    for (size_t i = 0; i < numRecords; ++i) {
        Record* record = &((*records)[i]);
        pthread_create(&threads[i], NULL, [record]() {
            *record = get_record_from_pool();
            srand(time(NULL) + (long)pthread_self());
            (*record)->value = rand() % 100;
            return NULL;
        }, NULL);
    }

    for (size_t i = 0; i < numRecords; ++i) {
        pthread_join(threads[i], NULL);
    }
}

void free_records(Record** records, size_t numRecords) {
    for (size_t i = 0; i < numRecords; ++i) {
        free_record((*records + i));
    }
    free(*records);
}
