        try {
            deserializationAttempts++;
            Object result = objectMapper.readValue(data, config.getTargetClass());
            if (result instanceof Collection && CollectionUtils.isEmpty((Collection<?>) result)) {
                throw new DeserializationFailureException("Empty collection received");
            }
            successCount++;
            return result;
        } catch (IOException | InstantiationException | IllegalAccessException e) {
            handleException(e);
        }
