pthread_mutex_t lock;

void write_to_file(const char* filename, Record* records, int num_records) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_lock(&lock);
    fwrite(records, sizeof(Record), num_records, file);
    pthread_mutex_unlock(&lock);
    fclose(file);
}

void read_from_file(const char* filename, Record** records, int* num_records) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_lock(&lock);
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);
    *records = malloc(sizeof(Record) * file_size / sizeof(Record));
    if (*records == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    fread(*records, sizeof(Record), file_size / sizeof(Record), file);
    pthread_mutex_unlock(&lock);
    *num_records = file_size / sizeof(Record);
    fclose(file);
}
```

