const axios = require('axios');
const _ = require('lodash');
const qs = require('qs';

class FileUploader {
  constructor(options) {
    this.apiUrl = options.apiUrl;
    this.chunkSize = options.chunkSize || 10 * 1024 * 1024; // 10 MB chunks
    this.maxRetries = options.maxRetries || 3;
    this.retryInterval = options.retryInterval || 5000;
    this.recordRange = options.recordRange || Array(1000).fill().map((_, i) => i); // Adjust the range size as needed
    this.recordStructure = _.times(this.recordRange.length, () => ({ id: -1 }));
  }

  async uploadFile(fileUrl) {
    try {
      const response = await axios.get(fileUrl, { responseType: 'arraybuffer' });
      const fileData = response.data;

      if (!fileData || fileData.length === 0) {
        throw new Error('Empty file data');
      }

      const numChunks = Math.ceil(fileData.length / this.chunkSize);

      for (let i = 0; i < numChunks; i++) {
        const chunkStart = i * this.chunkSize;
        const chunkEnd = Math.min((i + 1) * this.chunkSize, fileData.length);
        const chunkData = fileData.slice(chunkStart, chunkEnd);

        await this.uploadChunk(this.apiUrl, chunkData, i);
      }

      return `File uploaded successfully: ${fileUrl}`;
    } catch (error) {
      console.error(`Error uploading file: ${error.message}`);
      throw error;
    }
  }

  async uploadChunk(apiUrl, chunkData, chunkIndex) {
    let retries = this.maxRetries;

    while (retries > 0) {
      try {
        const config = {
          data: qs.stringify({ file: chunkData }),
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          url: `${apiUrl}/upload/${chunkIndex}`,
        };

        await axios.post(config);
        retries = 0;
      } catch (error) {
        console.error(`Error uploading chunk ${chunkIndex}: ${error.message}`);
        if (retries === this.maxRetries - 1) {
          throw error;
        }
        await new Promise(resolve => setTimeout(resolve, this.retryInterval));
        retries--;
      }
    }
  }
}
```

