struct Record {
    int value;
};

class MemoryPool {
public:
    std::unique_ptr<Record[]> records;
    size_t capacity;

    MemoryPool(size_t capacity) : capacity(capacity) {
        records.reset(new Record[capacity]);
    }

    Record* allocate() {
        if (freeIndex >= capacity) {
            std::cerr << "Memory pool is full.\n";
            return nullptr;
        }
        auto result = &records[freeIndex];
        freeIndex++;
        return result;
    }

    void deallocate(Record* record) {
        if (freeIndex == capacity) {
            std::cerr << "Memory pool is already full.\n";
            return;
        }
        freeIndex--;
    }

private:
    size_t freeIndex = 0;
};

std::mutex offsetsMutex, keysMutex, recordsMutex;
std::vector<long> offsets(1024);
std::vector<int> keys(1024);
MemoryPool recordPool(512);

void initializeDataStructures() {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 1000000);

    std::unique_lock<std::mutex> lockOffsets(offsetsMutex), lockKeys(keysMutex), lockRecords(recordsMutex);

    for (auto& record : *recordPool.records) {
        record.value = dis(gen);
        lockRecords.unlock();
        auto it = std::find_if(recordPool.records->begin(), recordPool.records->end(),
