int init_data(size_t *offsets, int *keys, Record **records, size_t record_capacity, size_t budget, enum LogLevel log_level, int min_value, int max_value) {
    size_t offset_size = sizeof(size_t);
    size_t key_size = sizeof(int);
    size_t record_size = sizeof(Record);

    void *memory = mmap(NULL, budget, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (memory == MAP_FAILED) {
        perror("mmap failed");
        return -1;
    }

    *offsets = 0;
    *keys = 0;

    size_t current_size = offset_size + key_size;
    for (size_t i = 0; i < record_capacity; ++i) {
        Record *record = (Record *)((char*)memory + current_size);
        if (!record) {
            log(log_level, "Out of memory\n");
            munmap(memory, budget);
            return -1;
        }

        record->value = rand() % (max_value - min_value + 1) + min_value;
        current_size += record_size;
        (*keys)++;
    }

    *records = memory;

    log(log_level, "Memory allocated: %zu bytes\n", budget);
    log(log_level, "Offsets: ");
    for (size_t i = 0; i < *offsets + *keys; ++i) {
        log(log_level, "%zu ", ((char*)*records + offset_size + key_size * i - (char*)memory)[0]);
    }
    log(log_level, "\nKeys: ");
    for (size_t i = 0; i < *keys; ++i) {
        log(log_level, "%d ", (*keys > i ? (*(int *)((char*)*records + offset_size + key_size * i) : -1));
    }
    log(log_level, "\nRecords: ");
    for (size_t i = 0; i < *keys; ++i) {
        log(log_level, "%d ", (*records + *(int *)((char*)*records + offset_size + key_size * i))->value);
    }
    log(log_level, "\n");

    return 0;
}
