```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct Record {
    int *key;
    size_t key_index;
    long *offset;
    size_t offset_index;
    int value;
} Record;

Record* initRecords(size_t n, size_t m, size_t k, size_t p, size_t q, long max_offset, int key_range_start, int key_range_end, int value_range_start, int value_range_end) {
    Record *records = (Record *)malloc(q * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation for records failed.\n");
        return NULL;
    }

    // Allocate key arrays and offset arrays
    int **keys = (int **)calloc(k, sizeof(int *));
    long *offsets = (long *)malloc(n * m * sizeof(long));
    if (!keys || !offsets) {
        fprintf(stderr, "Memory allocation for keys or offsets failed.\n");
        free(records);
        return NULL;
    }

    // Initialize key arrays and offset arrays
    for (size_t i = 0; i < k; ++i) {
        keys[i] = (int *)malloc((p + 1) * sizeof(int));
        if (!keys[i]) {
            fprintf(stderr, "Memory allocation for key %zu failed.\n", i);
            for (size_t j = 0; j < i; ++j) free(keys[j]);
            free(offsets);
            free(records);
            return NULL;
        }
        keys[i][p] = key_range_end + 1; // Mark the end of the array as one more than the range end
    }

    size_t offset_counter = 0;
    for (size_t i = 0; i < n; ++i) {
        if (offset_counter + m > max_offset) {
            fprintf(stderr, "The total number of offsets exceeds the maximum allowed value.\n");
            for (size_t j = 0; j < i; ++j) free(keys[j]);
            free(offsets);
            free(records);
            return NULL;
        }
        for (size_t j = 0; j < m; ++j, ++offset_counter) offsets[offset_counter] = offset_counter + 1;
    }

    // Generate unique keys and fill records with random values
    srand(time(NULL));
    size_t used_keys[k];
    for (size_t i = 0; i < k; ++i) used_keys[i] = 0;
    for (size_t i = 0; i < q; ++i) {
        do {
            records[i].key = NULL;
            records[i].offset = NULL;
            records[i].value = 0;
            records[i].key_index = 0;
            records[i].offset_index = 0;

            records[i].key = keys[rand() % k];
            records[i].key_index = rand() % (keys[records[i].key - keys][p] - key_range_start);
            records[i].key[records[i].key_index] = key_range_start + records[i].key_index;

            records[i].offset = &offsets[records[i].offset_index];
            records[i].offset_index = rand() % (m * n - offset_counter);

            records[i].value = rand() % (value_range_end - value_range_start + 1) + value_range_start;
        } while (used_keys[records[i].key - keys] == records[i].key_index);
        used_keys[records[i].key - keys][records[i].key_index] = true;
    }

    // Free unused key arrays and offset array
    for (size_t i = 0; i < k; ++i) {
        free(keys[i]);
        for (size_t j = used_keys[i] + 1; j < p + 1; ++j) keys[i][j] = 0;
    }

    return records;
}
```

