Record* records = NULL;
long* offsets = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void resize(size_t new_size) {
    Record* temp = realloc(records, new_size * sizeof(Record));
    if (!temp) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    records = temp;
}

void init(size_t num_offsets, size_t num_keys, long min_value, long max_value) {
    resize(num_offsets);
    offsets = realloc(offsets, num_offsets * sizeof(long));

    for (size_t i = 0; i < num_offsets; ++i) {
        offsets[i] = -1; // negative values indicate empty slots
    }

    resize(num_keys);
    records = realloc(records, num_keys * sizeof(Record));

    srand(time(NULL));

    for (size_t i = 0; i < num_keys; ++i) {
        int key_value = rand() % (max_value - min_value + 1) + min_value;
        records[i].key = &offsets[key_value];
        records[i].offset = i;
    }
}

