typedef struct Record {
    int value;
    long offset;
} Record;

void validate_size(int size, int min_size, int max_size) {
    if (size < min_size || size > max_size) {
        fprintf(stderr, "Invalid size: %d\n", size);
        exit(EXIT_FAILURE);
    }
}

void* allocate_and_init_offsets(int size) {
    validate_size(size, 1, INT_MAX);
    long *offsets = malloc(sizeof(long) * size);
    if (!offsets) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < size; ++i) offsets[i] = -1; // Initialize to invalid values
    return offsets;
}

void* allocate_and_init_keys(int size) {
    validate_size(size, 1, INT_MAX);
    int *keys = malloc(sizeof(int) * size);
    if (!keys) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < size; ++i) keys[i] = -1; // Initialize to invalid values
    return keys;
}

void* allocate_and_init_records(int num_records, int offset_size, int *offsets) {
    validate_size(num_records, 0, INT_MAX);
    Record *records = malloc(sizeof(Record) * num_records);
    if (!records) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = offsets[i];
        records[i].value = -1; // Initialize to invalid values
    }
    return records;
}

void init_random(unsigned long seed) {
    srand(seed);
}

int get_random_in_range(int min, int max) {
    if (min >= max) return min; // No need to generate a random number in this case
    return rand() % (max - min + 1) + min;
}

void set_record_values(Record *records, int num_records, int *keys, long *offsets) {
    for (int i = 0; i < num_records; ++i) {
        while (1) {
            records[i].value = get_random_in_range(0, INT_MAX);
            if (keys[records[i].value] == -1) {
                keys[records[i].value] = i;
                break;
            }
        }
        offsets[i] = i; // Update the offset to point to the correct record
    }
}

void deallocate(void *ptr) {
    free(ptr);
}

// Implement a reference counting mechanism for efficient memory deallocation
typedef struct RefCounted {
    void *data;
    int ref_count;
} RefCounted;

RefCounted* allocate_refcounted(void *data) {
    RefCounted *rc = malloc(sizeof(RefCounted));
    if (!rc) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }
    rc->data = data;
    rc->ref_count = 1;
    return rc;
}

void increment_refcount(RefCounted *rc) {
    ++rc->ref_count;
}

void decrement_refcount(RefCounted *rc) {
    if (--rc->ref_count == 0) {
        deallocate(rc->data);
        free(rc);
    }
}

// Concurrent access handling using mutexes
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void lock() {
    pthread_mutex_lock(&mutex);
}

void unlock() {
    pthread_mutex_unlock(&mutex);
}

// File I/O using mmap and munmap for serialization and deserialization
int serialize(const char *filename, void *data, size_t size) {
    int fd = open(filename, O_RDWR | O_CREAT, 0644);
    if (fd == -1) {
        perror("open failed");
        return -1;
    }
    void *mapped_data = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mapped_data == MAP_FAILED) {
        perror("mmap failed");
        close(fd);
        return -1;
    }
    memcpy(mapped_data, data, size);
    msync(mapped_data, size, MS_SYNC);
    close(fd);
    return 0;
}

int deserialize(const char *filename, void **data, size_t *size) {
    int fd = open(filename, O_RDWR, 0644);
    if (fd == -1) {
        perror("open failed");
        return -1;
    }
    fstat(fd, NULL); // Get the file size
    void *mapped_data = mmap(NULL, filesize, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mapped_data == MAP_FAILED) {
        perror("mmap failed");
        close(fd);
        return -1;
    }
    *data = mapped_data;
    *size = filesize;
    msync(mapped_data, filesize, MS_SYNC);
    close(fd);
    return 0;
}
```

