```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct Record {
    long value;
    bool flag;
} Record;

typedef struct Config {
    size_t initial_capacity;
    size_t growth_threshold;
    size_t min_reallocation_size;
} Config;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static Record* records = NULL;
static size_t capacity = 0;
static size_t num_records = 0;

Config default_config = {.initial_capacity = 16, .growth_threshold = 75, .min_reallocation_size = 8};

void resize(size_t new_capacity) {
    Record* temp = realloc(records, new_capacity * sizeof(Record));
    if (!temp) {
        fprintf(stderr, "Out of memory error\n");
        exit(EXIT_FAILURE);
    }
    records = temp;
    capacity = new_capacity;
}

void add_record(const Record* record) {
    pthread_mutex_lock(&mutex);

    if (num_records >= capacity && num_records < capacity * default_config.growth_threshold / 100) {
        resize(capacity * 2);
    } else if (num_records >= capacity) {
        resize(capacity + (capacity - default_config.min_reallocation_size));
    }

    records[num_records++] = *record;

    pthread_mutex_unlock(&mutex);
}

size_t get_total_records() {
    pthread_mutex_lock(&mutex);
    size_t total = num_records;
    pthread_mutex_unlock(&mutex);
    return total;
}

long long get_sum() {
    pthread_mutex_lock(&mutex);
    long long sum = 0;
    for (size_t i = 0; i < num_records; ++i) {
        sum += records[i].value;
    }
    pthread_mutex_unlock(&mutex);
    return sum;
}
```

