    if (list == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    memset(list, 0, sizeof(entry_list));
    list->capacity = initial_capacity;
    list->entries = calloc(initial_capacity, sizeof(struct entry));
    if (list->entries == NULL) {
        perror("calloc failed");
        munmap(list, sizeof(entry_list));
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&list->lock, NULL);

    log_mem("created", list, sizeof(entry_list));
    return list;
}

void resize_entry_list(entry_list *list, size_t new_capacity) {
