}

void add_entry(entry_list *list, const struct entry *entry) {
    pthread_mutex_lock(&list->lock);

    if (list->length >= list->capacity) resize_entry_list(list, list->capacity * 2);

    memcpy(&list->entries[list->length], entry, sizeof(struct entry));
    list->length++;

    pthread_mutex_unlock(&list->lock);
}

void update_entry(entry_list *list, int key, float (*transform)(float)) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->length; ++i) {
        if (list->entries[i].key == key) {
            list->entries[i].value = transform(list->entries[i].value);
            break;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void free_entry_list(entry_list *list) {
    if (list == NULL) return;

    free(list->entries);
    munmap(list, sizeof(entry_list));

    log_mem("destroyed", list, sizeof(entry_list));
}
