using namespace boost::log::expressions;
using namespace boost::log::sources;
using namespace boost::log::utility;
using namespace boost::log::utility::setup;

struct Record {
    long value;
    bool flag;
};

class RecordPool {
public:
    RecordPool(size_t initialSize, size_t threshold, bool logEnabled)
        : m_records(initialSize), m_threshold(threshold), m_logEnabled(logEnabled) {
        if (m_logEnabled)
            initLogger();
    }

    ~RecordPool() {
        clear();
        if (m_logEnabled)
            log("Destroying RecordPool with " + std::to_string(m_records.size()) + " records.");
    }

    void push_back(const Record& record) {
        if (!addRecord(record)) {
            if (m_logEnabled)
                log("Failed to add record: Out of memory.");
            throw std::runtime_error("Out of memory");
        }
    }

    const Record& front() const {
        return m_records.front();
    }

    const Record& back() const {
        return m_records.back();
    }

    size_t size() const {
        return m_records.size();
    }

    void clear() {
        for (auto& record : m_records) {
            record.value = 0;
            record.flag = false;
        }
        m_records.clear();
    }

private:
    std::vector<Record> m_records;
    const size_t m_threshold;
    bool m_logEnabled;

    bool addRecord(const Record& record) {
        if (m_records.size() >= m_threshold) {
            resize();
        }
        m_records.push_back(record);
        return true;
