[" Here's a simplified C++ implementation using smart pointers for memory management and avoiding race conditions with mutexes. This example does not include the actual data loading from an external source but provides a foundation for further development.

```cpp
#include <iostream>
#include <vector>
#include <mutex>
#include <memory>
#include <chrono>
#include <thread>
#include <atomic>

struct Node {
    std::unique_ptr<char[]> buffer;
    int value;
};

struct Transaction {
    std::shared_ptr<Node> node;
    std::uint64_t timestamp;
    // metadata
};

struct Batch {
    std::vector<std::shared_ptr<Transaction>> transactions;
    std::size_t count;
};

class TransactionProcessingSystem {
public:
    TransactionProcessingSystem(std::size_t initialCapacity, std::size_t growthThreshold, std::size_t minReallocationSize)
        : nodes_(initialCapacity), transactions_(minReallocationSize), batches_{}, growthThreshold_(growthThreshold), minReallocationSize_(minReallocationSize) {}

    void addTransaction(std::shared_ptr<Node> node, std::uint64_t timestamp, const std::string& metadata) {
        transactions_.emplace_back(new Transaction{node, timestamp, metadata});
        if (transactions_.size() > growthThreshold_) {
            resize();
        }
    }

    std::size_t getTransactionCount() const {
        return transactions_.size();
    }

    int getSumOfNodeValues() const {
        int sum = 0;
        for (const auto& transaction : transactions_) {
            sum += transaction->node->value;
        }
        return sum;
    }

    void resize() {
        std::vector<Transaction> newTransactions(transactions_.size());
        std::copy(transactions_.begin(), transactions_.end(), newTransactions.begin());

        if (nodes_.capacity() < transactions_.size()) {
            nodes_.resize(transactions_.size());
        }

        for (std::size_t i = 0; i < transactions_.size(); ++i) {
            nodes_[i].reset(new Node{std::move(newTransactions[i]->node), newTransactions[i]->timestamp, newTransactions[i]->metadata});
        }

        transactions_.resize(minReallocationSize_);
    }

private:
    std::vector<Node> nodes_;
    std::vector<Transaction> transactions_;
    std::vector<std::shared_ptr<Batch>> batches_;
    const std::size_t growthThreshold_;
    const std::size_t minReallocationSize_;

    std::mutex mtx;
};
```

