#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int key;
    long timestamp;
    struct Record *next;
} Record;

Record* create_record(int key) {
    Record *record = (Record *)malloc(sizeof(Record));
    record->key = key;
    record->timestamp = time(NULL);
    record->next = NULL;
    return record;
}

void delete_record(Record **head, Record *record) {
    if (*head == record) {
        *head = record->next;
    } else {
        Record *current = *head;
        while (current && current->next != record) {
            current = current->next;
        }
        if (!current) {
            return;
        }
        current->next = record->next;
    }
    free(record);
}

Record* find_record(Record **head, int key) {
    for (Record *current = *head; current != NULL; current = current->next) {
        if (current->key == key) {
            return current;
        }
    }
    return NULL;
}

void insert_record(Record **head, Record *new_record) {
    if (*head == NULL) {
        *head = new_record;
        return;
    }

    Record *current = *head;
    Record *prev = NULL;

    while (current != NULL && current->key < new_record->key) {
        prev = current;
        current = current->next;
    }

    if (prev == NULL) {
        new_record->next = *head;
        *head = new_record;
    } else {
        new_record->next = current;
        prev->next = new_record;
    }
}

Record* resize_array(Record **array, size_t *size, size_t new_size) {
    Record *new_array = (Record *)realloc(*array, new_size * sizeof(Record));
    if (!new_array) {
        return NULL;
    }

    *size = new_size;
    for (size_t i = *size; i < new_size; ++i) {
        new_array[i].next = NULL;
    }
    return new_array;
}

void generate_unique_values(Record **records, size_t size, int min, int max) {
    int values[max - min + 1];
    for (int i = min; i <= max; ++i) {
        values[i - min] = i;
    }

    for (size_t i = 0; i < size; ++i) {
        int value;
        do {
            value = values[rand() % (max - min + 1)];
        } while (find_record(records, value) != NULL);
        records[i]->key = value;
    }
}
```

