[' Here's an example implementation in C using the standard library, `stdlib`, `stdio`, `time.h`, `math.h` and `sys/types.h` for time handling, file I/O, math functions, and system types respectively. For random number generation, we use the Mersenne Twister algorithm from the `gsl` library (GNU Scientific Library).

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>
#include <sys/types.h>
#include <gsl/gsl_rng.h>
#include <gsl/gsl_randist.h>

typedef struct {
    long offset;
    int key;
    int value;
    time_t timestamp;
} record;

int initializeDataBundle(const char *filePath, const config_t *config) {
    FILE *fp = fopen(filePath, "r");
    if (!fp) {
        perror("Error opening file");
        return -1;
    }

    size_t numRecords = 0;
    fseek(fp, 0, SEEK_END);
    numRecords = ftell(fp) / sizeof(record);
    rewind(fp);

    record *records = malloc(numRecords * sizeof(record));
    if (!records) {
        perror("Error allocating memory for records");
        fclose(fp);
        return -1;
    }

    int *keys = malloc(numRecords * sizeof(int));
    if (!keys) {
        perror("Error allocating memory for keys");
        free(records);
        fclose(fp);
        return -1;
    }

    long *offsets = malloc((numRecords + 1) * sizeof(long));
    if (!offsets) {
        perror("Error allocating memory for offsets");
        free(records);
        free(keys);
        fclose(fp);
        return -1;
    }

    gsl_rng *rng = gsl_rng_alloc(gsl_rng_mt19937);
    if (!rng) {
        perror("Error initializing random number generator");
        free(records);
        free(keys);
        free(offsets);
        fclose(fp);
        return -1;
    }

    for (size_t i = 0; i < numRecords; ++i) {
        record *recordPtr = &records[i];
        recordPtr->key = keys[i] = config->dataRange.min + rand_r(rng) % (config->dataRange.max - config->dataRange.min + 1);
        recordPtr->value = configToValue(config, recordPtr->key);
        recordPtr->timestamp = time(NULL);
        offsets[i+1] = offsetOf(records, i) + sizeof(record);
    }

    offsets[0] = 0;

    fread(records, sizeof(record), numRecords, fp);
    if (ferror(fp)) {
        perror("Error reading file");
        gsl_rng_free(rng);
        free(records);
        free(keys);
        free(offsets);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    gsl_rng_free(rng);

    // Implement caching, bloom filter, and other optimizations as needed.

    return numRecords;
}
```

This implementation assumes the presence of a `config_t` structure representing the configuration and a function `configToValue(config_t*, int)` that maps keys to values according to the specified configuration. The code also handles potential memory allocation failures, file I/O errors, and random number generation. It uses dynamic memory allocation for records, offsets, and keys arrays, ensuring efficient handling of variable data sizes without reallocating memory.

The implementation does not include caching, bloom filter, or other optimizations as they are beyond the scope of this task. However, you can easily integrate them into the provided code based on your specific requirements and performance considerations.']

