[" Here's a C++11 implementation using std::vector and std::mutex for thread safety. The function dynamically allocates memory for three containers: `std::vector<long> offsets`, `std::vector<int> keys` and `std::vector<struct Record> records`. Each `Record` structure contains an integer value.

The function uses the C++11 random library to generate random values within a given range, and checks for memory allocation errors using try-catch blocks. It also employs a simple validation mechanism to ensure data integrity after the loop completes.

To support concurrent usage by multiple threads, I've used std::mutex to protect shared resources during access and modification.

```cpp
#include <vector>
#include <random>
#include <new>
#include <stdexcept>
#include <mutex>

struct Record {
    int value;
};

std::mutex mtx;

int initialize_arrays(size_t num_records, size_t offset_range, size_t key_range, size_t record_value_range) {
    std::vector<long> offsets;
    std::vector<int> keys;
    std::vector<Record> records;

    try {
        offsets.reserve(num_records);
        keys.reserve(num_records);
        records.reserve(num_records);

        // Allocate memory for each container
        offsets.resize(num_records);
        keys.resize(num_records);
        records.resize(num_records);

        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis_offset(0, offset_range - 1);
        std::uniform_int_distribution<> dis_key(0, key_range - 1);
        std::uniform_int_distribution<> dis_value(0, record_value_range - 1);

        // Initialize records with random values and validate data integrity
        for (size_t i = 0; i < num_records; ++i) {
            mtx.lock();
            offsets[i] = dis_offset(gen);
            keys[i] = dis_key(gen);
            records[i].value = dis_value(gen);
            mtx.unlock();
        }

        // Validate data integrity after loop completes
        for (size_t i = 0; i < num_records; ++i) {
            if (offsets[i] >= num_records || keys[i] >= num_records || records[keys[i]].value < 0) {
                return -1; // Error code indicating data integrity issue
            }
        }
    } catch (std::bad_alloc& e) {
        return -2; // Error code indicating memory allocation failure
    }

    return 0; // Successful initialization
}
