int generate_and_execute(unsigned long size, unsigned min, unsigned max, unsigned cmd_arg1, unsigned cmd_arg2, const char* command) {
    std::vector<long> offsets;
    std::vector<int> keys;
    std::vector<std::unique_ptr<Record>> records;

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> distr(min, max);

