        keys.push_back(key);

        Record* record = new (offset) Record();
        record->value = distr(gen);
        records.push_back(std::unique_ptr<Record>(record));
    }

    std::thread command_thread([=]() {
        int pid = _spawnl(P_NOWAIT, "sh", "sh", "-c", command, std::to_string(cmd_arg1).c_str(), std::to_string(cmd_arg2).c_str());
        if (pid <= 0) {
