[" Here's a simplified C++ code example that addresses some of the requirements you've mentioned. Note that this is a basic implementation and may need further refinement to meet all your specifications.

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <cstdlib>
#include <ctime>
#include <cassert>

struct DataBlock {
    int size;
    char data[1]; // Variable-sized array with 1 byte of overhead for alignment
};

struct Entry {
    DataBlock* data_block;
    int key;
    long offset;
};

class Pipeline {
public:
    Pipeline(size_t num_entries, size_t keys_size, size_t offsets_size, size_t buffer_size)
        : num_entries_(num_entries), keys_(keys_size), offsets_(offsets_size), buffer_(buffer_size), log_mutex_() {
        data_blocks_ = new Entry[num_entries];
        for (auto& entry : data_blocks_) {
            entry.data_block = new DataBlock{static_cast<int>(sizeof(DataBlock))};
            entry.key = -1;
            entry.offset = -1;
        }

        keys_.reserve(keys_size);
        offsets_.reserve(offsets_size);

        srand(time(nullptr));
    }

    ~Pipeline() {
        for (auto& entry : data_blocks_) {
            delete[] entry.data_block;
        }
        delete[] data_blocks_;
    }

    void readInput() {
        int input;
        while (std::cin >> input) {
            largest_ = std::max(input, largest_);
            auto it = find(input);
            if (it == keys_.end()) {
                keys_.push_back(input);
                offsets_.push_back(-1);
                data_blocks_[keys_.size - 1].key = keys_.size - 1;
                data_blocks_[keys_.size - 1].offset = offsets_.size();
            } else {
                it->second = data_blocks_[it->second].offset;
            }
        }
    }

    int findLargest() const {
        return largest_;
    }

private:
    std::unordered_map<int, long> keys_;
    std::vector<long> offsets_;
    std::vector<Entry> data_blocks_;
    size_t num_entries_;
    int largest_ = INT_MIN;
    size_t keys_size_;
    size_t offsets_size_;
    size_t buffer_size_;
    std::mutex log_mutex_;

    auto find(int key) {
        return keys_.find(key);
    }
};
```

