[" I will provide a simplified C++ version of the requested function using the Standard Template Library (STL) for concurrent access management and dynamic memory allocation. This solution utilizes `std::mutex` for locking, `std::atomic` for atomic operations, and `std::list` for the event linked list.

```cpp
#include <iostream>
#include <list>
#include <string>
#include <vector>
#include <atomic>
#include <mutex>

enum class EventType { ADD, REMOVE };

struct Record {
    long offset;
    int key;
    short length;
};

struct Stats {
    std::atomic<int> counter{0};
    char status{' '};
    bool active{true};
    mutex mtx;
};

struct Event {
    time_t timestamp;
    std::string message;
    EventType event_type;
};

std::list<Event> events;
std::vector<Record> records;
std::vector<Stats> stats;

void insert_event(const Event& event, size_t index) {
    mutex mtx;
    lock_guard<mutex> lock(mtx);

    events.emplace_back(event);

    if (index < stats.size()) {
        auto& stat = stats[index];
        switch (event.event_type) {
            case EventType::ADD:
                ++stat.counter;
                break;
            case EventType::REMOVE:
                --stat.counter;
                break;
        }
    }
}
```

