[" Here's a C function that addresses the given programming task. This function uses a custom allocator for both `long` and `int` arrays, minimizing memory overhead and optimizing cache utilization. It also integrates a simple random number generator to set values within a given range.

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
} Record;

// Custom allocator for Record arrays
Record* record_alloc(size_t size) {
    size_t alignment = sizeof(Record);
    size_t block_size = size * sizeof(Record);
    void* block = malloc(block_size + (alignment - 1));
    if (!block) return NULL;
    void* data = (char*)block + ((size_t)block % alignment);
    return (Record*)data;
}

// Custom allocator for int arrays
int* int_alloc(size_t size) {
    size_t alignment = sizeof(int);
    size_t block_size = size * sizeof(int);
    void* block = malloc(block_size + (alignment - 1));
    if (!block) return NULL;
    void* data = (char*)block + ((size_t)block % alignment);
    return (int*)data;
}

// Custom allocator for long arrays
long* long_alloc(size_t size) {
    size_t alignment = sizeof(long);
    size_t block_size = size * sizeof(long);
    void* block = malloc(block_size + (alignment - 1));
    if (!block) return NULL;
    void* data = (char*)block + ((size_t)block % alignment);
