[' Here is a C implementation of the requested hash table using a separate chaining approach. The code uses `long` for offset values, `int` for keys, and a custom record structure containing an `int` value and a pointer to a `long`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
    long offset;
    struct Record *next;
} Record;

Record* create_record(int value, long offset) {
    Record *new_record = (Record *)malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }
    new_record->value = value;
    new_record->offset = offset;
    new_record->next = NULL;
    return new_record;
}

unsigned long hash(int key, unsigned long table_size) {
    return key % table_size;
}

void init_hash_table(Record ***table, unsigned long *table_size, int capacity) {
    *table = (Record **)calloc(*table_size, sizeof(Record*));
    if (!*table) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }
    for (unsigned long i = 0; i < *table_size; ++i) {
        (*table)[i] = NULL;
    }
}

void free_hash_table(Record **table, unsigned long table_size) {
    for (unsigned long i = 0; i < table_size; ++i) {
        Record *current = (*table)[i];
        while (current != NULL) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }
    free(*table);
}

void populate_hash_table(Record **table, unsigned long table_size, int capacity) {
    srand(time(NULL));
    for (int i = 0; i < capacity; ++i) {
        int key = rand() % table_size;
        Record *record = create_record(rand() % INT_MAX, i);
        unsigned long index = hash(key, table_size);
        record->next = (*table)[index];
        (*table)[index] = record;
    }
}

void print_memory_usage(Record **table, unsigned long table_size) {
    size_t total_memory = 0;
    for (unsigned long i = 0; i < table_size; ++i) {
        Record *current = (*table)[i];
        while (current != NULL) {
            total_memory += sizeof(Record);
            current = current->next;
        }
    }
    printf("Total memory usage: %zu bytes\n", total_memory);
}
```

This code defines a `Record` structure, a hash function for the given table size, and functions to initialize, populate, and free the hash table. The `print_memory_usage()` function reports the total memory usage at the end of execution.

To use this code, you can create a main function that initializes the hash table with a specified capacity, populates it, and then prints the memory usage:

```c
