    int capacity = 10000;
    Record **table;

    init_hash_table(&table, &table_size, capacity);
    populate_hash_table(table, table_size, capacity);
    print_memory_usage(table, table_size);

    free_hash_table(table, table_size);

    return 0;
}
```']

[' Here's a C++ code implementation using a pool-based allocation strategy for `record` structures, supporting concurrent access from multiple threads, detailed logging, and dynamic resizing. The code uses a custom allocator with a linked list to manage the pool of records, ensuring efficient memory utilization and minimizing fragmentation.

```cpp
#include <iostream>
#include <vector>
#include <list>
#include <atomic>
#include <mutex>
#include <chrono>
#include <thread>
#include <memory>

struct Record {
    long* offset;
    int* key;
    int* value;
    Record* next;
};

class RecordPool {
public:
    RecordPool(size_t initialSize) {
        if (initialSize == 0)
            throw std::invalid_argument("Initial size must be greater than zero.");

        currentSize = initialSize;
        freeList.reset(new std::list<Record>());
        for (size_t i = 0; i < initialSize; ++i) {
            Record* record = new Record();
            record->offset = nullptr;
            record->key = nullptr;
            record->value = nullptr;
            record->next = freeList->back().get();
            freeList->push_back(std::move(record));
        }
    }

    Record* allocate() {
        if (freeList->empty()) {
            std::unique_lock<std::mutex> lock(mutex);
            if (freeList->empty()) {
                if (currentSize == maxSize) {
                    throw std::runtime_error("Out of memory.");
                }

                Record* record = new Record();
                record->offset = nullptr;
                record->key = nullptr;
                record->value = nullptr;
                record->next = nullptr;

                freeList->push_back(std::move(record));
                currentSize++;
            }
        }

        Record* record = freeList->front().get();
        freeList->pop_front();
        return record;
    }

    void deallocate(Record* record) {
        record->offset = nullptr;
        record->key = nullptr;
        record->value = nullptr;
        record->next = freeList->back().get();
        freeList->push_back(record);
    }

    ~RecordPool() {
        for (auto& record : *freeList) {
            delete record;
        }
    }

    size_t getCurrentSize() const { return currentSize; }

private:
    std::list<Record>* freeList;
    size_t currentSize;
    mutable std::mutex mutex;
    size_t maxSize = 1024 * 1024; // Default maximum size is 1MB
};

class Logger {
public:
    void log(const char* message, ...) {
        std::lock_guard<std::mutex> lock(logMutex);
        va_list args;
        va_start(args, message);
        vprintf(message, args);
        va_end(args);
        logs.push_back({ std::chrono::system_clock::now(), message });
    }

    void printLogs() {
        for (const auto& log : logs) {
            printf("%s\n", log.message.c_str());
        }
        logs.clear();
    }

private:
    struct LogEntry {
        std::chrono::system_time_point timestamp;
        std::string message;
    };

    std::vector<LogEntry> logs;
    mutable std::mutex logMutex;
};

Logger logger;
RecordPool recordPool(1024); // Initialize with 1K records

void worker(int id) {
    for (size_t i = 0; i < 100000; ++i) {
        Record* record = recordPool.allocate();
        record->offset = new long(i * 10);
        record->key = new int(id * 2);
        record->value = new int(0);

        logger.log("Thread %d allocated record at offset %ld with key %d\n", id, record->offset, record->key);

        std::this_thread::sleep_for(std::chrono::milliseconds(rand() % 100)); // Simulate random processing time

        logger.log("Thread %d deallocating record\n", id);
        recordPool.deallocate(record);
    }
}

int main() {
    std::thread workers[4];
    for (size_t i = 0; i < 4; ++i) {
        workers[i] = std::thread(worker, i);
    }

    for (auto& worker : workers) {
        worker.join();
    }

    logger.printLogs();
    return 0;
}
```

This code creates a `RecordPool` class that manages a pool of `Record` structures, minimizing memory fragmentation and providing efficient memory utilization. The pool supports concurrent access from multiple threads using a linked list and a mutex for synchronization. The code also includes a simple logger to track memory usage and allocation attempts.

The example demonstrates the use of the `RecordPool` by creating four worker threads that allocate, process, and deallocate records dynamically. The worker threads simulate varying processing times to demonstrate the pool's ability to handle peak load scenarios while minimizing memory fragmentation.']

