typedef enum {
    TASK_STATUS_PENDING,
    TASK_STATUS_IN_PROGRESS,
    TASK_STATUS_COMPLETED
} TaskStatus;

typedef struct Task {
    char name[256];
    int priority;
    TaskStatus status;
} Task;

struct TaskList {
    size_t capacity;
    size_t size;
    Task* tasks;
};

void task_list_init(struct TaskList* list, size_t initial_capacity) {
    list->tasks = malloc(initial_capacity * sizeof(Task));
    if (!list->tasks) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->size = 0;
}

void task_list_resize(struct TaskList* list, size_t new_capacity) {
    if (new_capacity <= list->size) {
        fprintf(stderr, "New capacity cannot be smaller than the current size\n");
        return;
    }

    Task* new_tasks = realloc(list->tasks, new_capacity * sizeof(Task));
    if (!new_tasks) {
        fprintf(stderr, "Memory allocation failure during resize\n");
        exit(EXIT_FAILURE);
    }
    list->tasks = new_tasks;
    list->capacity = new_capacity;
}

void task_list_add(struct TaskList* list, const char* name, int priority) {
    if (list->size == list->capacity) {
        task_list_resize(list, list->capacity * 2);
    }

    strcpy(list->tasks[list->size].name, name);
    list->tasks[list->size].priority = priority;
    list->tasks[list->size].status = TASK_STATUS_PENDING;
    list->size++;
}

void task_list_save(const struct TaskList* list, FILE* file) {
    fwrite(&list->capacity, sizeof(size_t), 1, file);
    for (size_t i = 0; i < list->size; ++i) {
        fwrite(list->tasks[i].name, sizeof(char), strlen(list->tasks[i].name) + 1, file);
        fwrite(&list->tasks[i].priority, sizeof(int), 1, file);
        fwrite(&list->tasks[i].status, sizeof(TaskStatus), 1, file);
    }
}

void task_list_load(struct TaskList* list, FILE* file) {
    size_t capacity;
    fread(&capacity, sizeof(size_t), 1, file);
    task_list_init(list, capacity);

    for (size_t i = 0; i < capacity; ++i) {
        Task task;
        fread(task.name, sizeof(char), 256, file);
        fread(&task.priority, sizeof(int), 1, file);
        fread(&task.status, sizeof(TaskStatus), 1, file);
        task_list_add(list, task.name, task.priority);
    }
