void TaskList::insert(const Task& task, size_t pos) {
    std::lock_guard<std::mutex> lock(this->lock);

    if (pos >= tasks_.size()) {
        tasks_.resize(2 * tasks_.size());
    }

    tasks_[pos] = task;
    names_[task.name] = pos;
}

void TaskList::remove(size_t index) {
    std::lock_guard<std::mutex> lock(this->lock);

    if (index >= tasks_.size()) return;

    auto it = names_.find(tasks_[index].name);
    if (it != names_.end()) {
        names_.erase(it);
    }

    tasks_.erase(tasks_.begin() + index);
}

void TaskList::remove(const std::string& name) {
