typedef struct {
    long offset;
    int key;
    char type;
} record;

void initialize_data_structures(int n, int m, record** records) {
    if (n <= 0 || m < 0) {
        fprintf(stderr, "Invalid input: n and m must be positive integers.\n");
        return;
    }

    long* offsets = malloc(n * sizeof(long));
    if (!offsets) {
        perror("Memory allocation for offsets failed.");
        return;
    }

    int* keys = malloc(m * sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Memory allocation for keys failed.");
        return;
    }

    record* records_array = malloc(m * sizeof(record));
    if (!records_array) {
        free(offsets);
        free(keys);
        perror("Memory allocation for records failed.");
        return;
    }

    srand(time(NULL));

    // Initialize keys array with sequential integers starting from 0.
    for (int i = 0; i < m; ++i) {
        keys[i] = i;
    }

    // Randomly assign each offset to a unique value within the range of 0 to 1000000000, ensuring no two records have the same offset.
    for (int i = 0; i < m; ++i) {
        bool found = false;
        do {
            offsets[i] = rand() % 1000000000;
            for (int j = 0; j < i; ++j) {
                if (offsets[i] == offsets[j]) {
                    found = true;
                    break;
                }
            }
        } while (found);

        records_array[i].offset = offsets[i];
        records_array[i].key = keys[i];

        // Assign the type of each record based on a specific pattern: 'A' for even key, 'B' for odd key, and 'C' for keys divisible by 3.
        records_array[i].type = (keys[i] % 2 == 0) ? 'A' : ((keys[i] % 3 == 0) ? 'C' : 'B');
    }

    *records = records_array;
}
```

