#include <thread>

struct Record {
    long offset;
    int key;
    double weight;
    std::vector<short> secondary;
    float cumulative_weight = 0.0f;
};

std::vector<Record> allocateRecords(size_t size, int min_key, int max_key) {
    std::vector<Record> records(size);
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(min_key, max_key);

    for (auto& record : records) {
        record.offset = static_cast<long>(std::distance(records.begin(), &record));
        record.key = dis(gen);
        record.weight = static_cast<double>(rd()) / RAND_MAX; // Generates a random weight between 0 and 1
    }

    return records;
}

void logMemoryAllocation(const std::vector<Record>& records, bool success) {
    // Initialize the logger with your configuration file
    log4cplus::Logger::root().setLevel(log4cplus::Level::getTraceLevel());
    log4cplus::Configurator::configure("log4cplus.properties");

    if (success) {
        log4cplus::Logger::getRootLogger()->trace("Successfully allocated " + std::to_string(records.size()) + " records.");
    } else {
        log4cplus::Logger::getRootLogger()->error("Failed to allocate memory for " + std::to_string(records.size()) + " records.");
    }
}

void fillSecondaryAndCumulativeWeight(std::vector<Record>& records) {
    // Fill secondary and cumulative weight arrays concurrently using threads
    const int num_threads = std::thread::hardware_concurrency();

    std::vector<std::vector<short>> secondary_parts(num_threads);
    std::vector<float> cumulative_weights_parts(num_threads + 1);

    auto partitionSize = records.size() / num_threads;

    std::vector<std::thread> threads;

    for (size_t i = 0; i < num_threads; ++i) {
        size_t start = i * partitionSize;
        size_t end = (i == num_threads - 1) ? records.size() : start + partitionSize;

        auto part = std::make_move_iterator(records.begin() + start);
        auto partEnd = std::make_move_iterator(records.begin() + end);

        secondary_parts[i] = std::vector<short>(part, partEnd);
        threads.emplace_back([=] { fillSecondaryArray(secondary_parts[i]); });
    }

    for (auto& thread : threads) thread.join();

    cumulative_weights_parts[0] = 0;

    for (size_t i = 1; i <= num_threads; ++i) {
        cumulative_weights_parts[i] = cumulative_weights_parts[i - 1] + secondary_parts[i - 1].size();
    }

    for (auto& record : records) {
        record.cumulative_weight = cumulative_weights_parts[record.offset];
        record.secondary = secondary_parts[record.offset];
    }
}

void fillSecondaryArray(std::vector<short>& secondary) {
    // Fill the secondary array with random values
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(-100, 100);

    for (auto& value : secondary) {
        value = dis(gen);
    }
}

std::vector<Record> manageMemoryAllocation(size_t size, int min_key, int max_key) {
    std::vector<Record> records = allocateRecords(size, min_key, max_key);
    fillSecondaryAndCumulativeWeight(records);

    // Handle edge cases and performance metrics based on your configuration file
    if (size == 0 || min_key > max_key) {
        logMemoryAllocation(records, false);
        throw std::invalid_argument("Invalid array size or key range.");
    }

    logMemoryAllocation(records, true);
    return records;
}
```

